import fs from 'fs'
import path from 'path'
import { fileURLToPath } from 'url'
import { MODEL_CATALOG, type ModelInfo } from '../src/routes/ai/modelCatalog.js'

const __dirname = path.dirname(fileURLToPath(import.meta.url))

async function fetchModelsDevCatalog() {
  const url = 'https://models.dev/api.json'
  try {
    const res = await fetch(url)
    if (!res.ok) throw new Error(`HTTP ${res.status}`)
    return await res.json()
  } catch (err) {
    console.error(`Failed to fetch models.dev API: ${err}`)
    process.exit(1)
  }
}

const INTENTIONAL_OVERRIDES = [
  'gitlab-duo-agentic', // Intentionally restricted capabilities for agentic chat compatibility
  'grok-code-fast-1',   // Intentionally restricted image_input locally (xai models.dev defaults to true for all but local marks false)
]

async function checkParity() {
  const remote = await fetchModelsDevCatalog()
  let hasErrors = false

  console.log('Checking model catalog parity with models.dev...')

  for (const [catalogId, modelInfo] of Object.entries(MODEL_CATALOG)) {
    if (INTENTIONAL_OVERRIDES.includes(catalogId)) {
      console.log(`[SKIP] ${catalogId} (Intentional Override)`)
      continue
    }

    const { provider, providerModelId, capabilities } = modelInfo

    // Models.dev places google models under 'google' or 'google-vertex' but keys are the same
    const remoteProvider = remote[provider] || (provider === 'google' ? remote['google-vertex'] : undefined)

    if (!remoteProvider) {
      console.error(`[ERROR] ${catalogId}: Provider '${provider}' not found in models.dev`)
      hasErrors = true
      continue
    }

    const remoteModel = remoteProvider.models?.[providerModelId]
    if (!remoteModel) {
      console.error(`[ERROR] ${catalogId}: Model ID '${providerModelId}' not found in models.dev provider '${provider}'`)
      hasErrors = true
      continue
    }

    const remoteReasoning = !!remoteModel.reasoning
    const localReasoning = capabilities.supportsExtendedThinking
    if (remoteReasoning !== localReasoning) {
      console.error(`[ERROR] ${catalogId}: Reasoning flag mismatch. Local: ${localReasoning}, Remote: ${remoteReasoning}`)
      hasErrors = true
    }

    const modalIn = remoteModel.modalities?.input || []
    const remoteImage = modalIn.includes('image')
    const remotePdf = modalIn.includes('pdf')

    if (capabilities.supportsImageInput !== remoteImage) {
      console.error(`[ERROR] ${catalogId}: Image input mismatch. Local: ${capabilities.supportsImageInput}, Remote: ${remoteImage}`)
      hasErrors = true
    }

    if (capabilities.supportsPdfInput !== remotePdf) {
      console.error(`[ERROR] ${catalogId}: PDF input mismatch. Local: ${capabilities.supportsPdfInput}, Remote: ${remotePdf}`)
      hasErrors = true
    }

    const localToolCall = 
      capabilities.supportsWebSearch || 
      capabilities.supportsFileSearch || 
      capabilities.supportsCodeInterpreter || 
      capabilities.supportsComputerUse || 
      capabilities.supportsShellTool || 
      capabilities.supportsApplyPatch || 
      capabilities.supportsTextEditor

    const remoteToolCall = !!remoteModel.tool_call

    if (localToolCall !== remoteToolCall) {
      if (remoteToolCall && !localToolCall) {
        console.warn(`[WARN] ${catalogId}: Remote supports tools, but local exposes 0 tool capabilities.`)
      } else if (!remoteToolCall && localToolCall) {
        console.error(`[ERROR] ${catalogId}: Local exposes tools, but remote says tools are NOT supported.`)
        hasErrors = true
      }
    }
  }

  if (hasErrors) {
    console.error('\nParity check failed. Update modelCatalog.ts or add to INTENTIONAL_OVERRIDES.')
    process.exit(1)
  } else {
    console.log('\nParity check passed! ✅')
  }
}

checkParity()

import { randomUUID, createHash } from 'node:crypto'
import { spawnSync } from 'node:child_process'
import { mkdtemp, mkdir, readFile, rm, writeFile } from 'node:fs/promises'
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import { getRedisClient } from './redis.js'
import {
  createProjectReplicaSessionForServer,
  generateProjectReplicaBundleUploadUrlForServer,
  generateProjectReplicaLfsUploadUrlForServer,
  getProjectReplicaForServer,
  getProjectReplicaLfsObjectForServer,
  getStorageUrlForServer,
  upsertProjectReplicaForServer,
  upsertProjectReplicaLfsObjectForServer,
  updateProjectReplicaSessionForServer,
} from './convex.js'

export interface ReplicaSnapshotFile {
  path: string
  contentBase64: string
  isBinary: boolean
  size: number
  hash: string
}

export interface ReplicaPlanOperation {
  path: string
  reason: string
}

export interface ReplicaPlanConflict {
  path: string
  reason: string
  kind: 'text' | 'binary'
  localExists: boolean
  remoteExists: boolean
}

export interface ReplicaPlanResponse {
  success: boolean
  sessionId: string
  baseCommit?: string
  localCommit?: string
  remoteCommit?: string
  downloads: ReplicaPlanOperation[]
  uploads: ReplicaPlanOperation[]
  localDeletes: ReplicaPlanOperation[]
  cloudDeletes: ReplicaPlanOperation[]
  autoMerged: ReplicaPlanOperation[]
  conflicts: ReplicaPlanConflict[]
  noChange: number
  error?: string
}

export interface ReplicaExecuteResponse {
  success: boolean
  applied: boolean
  requiresConflictResolution?: boolean
  conflicts?: ReplicaPlanConflict[]
  diagnostics?: {
    baseCommit?: string
    localCommit?: string
    remoteCommit?: string
    resultCommit?: string
    mergeDurationMs?: number
    failureClass?: string
  }
  workspacePatch?: Array<{
    path: string
    deleted?: boolean
    contentBase64?: string
    encoding?: 'base64'
  }>
  canonicalHeadCommit?: string
  error?: string
}

export interface ReplicaWorkspaceHydrationResult {
  success: boolean
  source: 'canonical' | 'none'
  written: number
  canonicalHead?: string
  error?: string
}

interface GitResult {
  ok: boolean
  code: number | null
  stdout: string
  stderr: string
  stdoutBuffer: Buffer
}

interface ParsedNameStatus {
  code: string
  path: string
}

const CANONICAL_REF = 'refs/heads/canonical'
const LOCK_TTL_MS = 120_000
const LOCK_WAIT_MS = 30_000
const LOCK_RETRY_MS = 250
const LFS_POINTER_VERSION = 'version https://git-lfs.github.com/spec/v1'

const FALLBACK_LOCKS = new Map<string, { owner: string; expiresAt: number }>()
const REPLICA_GIT_DISABLE_REDIS_LOCKS = process.env.REPLICA_GIT_DISABLE_REDIS_LOCKS === '1'
let hasLoggedReplicaLockBypass = false

function getReplicaLockClient() {
  if (!REPLICA_GIT_DISABLE_REDIS_LOCKS) {
    return getRedisClient()
  }

  if (!hasLoggedReplicaLockBypass) {
    hasLoggedReplicaLockBypass = true
    console.warn('[ReplicaGit] Redis lock bypass enabled; using in-memory replica locks for diagnostics')
  }

  return null
}

function normalizeRepoPath(input: string): string {
  return input.replace(/\\/g, '/').replace(/^\/+/, '').trim()
}

function decodeBase64ToBuffer(value: string): Buffer {
  return Buffer.from(value, 'base64')
}

function encodeBufferToBase64(value: Buffer): string {
  return value.toString('base64')
}

async function persistReplicaSessionStatusBestEffort(args: {
  projectId: string
  sessionId: string
  userId: string
  status: 'planned' | 'applied' | 'conflict' | 'failed' | 'queued'
  baseCommit?: string
  localCommit?: string
  remoteCommit?: string
  resultCommit?: string
  diagnostics?: Record<string, unknown>
}): Promise<void> {
  try {
    await updateProjectReplicaSessionForServer({
      projectId: args.projectId,
      sessionId: args.sessionId,
      status: args.status,
      baseCommit: args.baseCommit,
      localCommit: args.localCommit,
      remoteCommit: args.remoteCommit,
      resultCommit: args.resultCommit,
      diagnostics: args.diagnostics,
    })
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    console.warn('[ReplicaGit] Failed to update replica session; falling back to create', {
      projectId: args.projectId,
      sessionId: args.sessionId,
      status: args.status,
      error: message,
    })
    try {
      await createProjectReplicaSessionForServer({
        projectId: args.projectId,
        sessionId: args.sessionId,
        userId: args.userId,
        baseCommit: args.baseCommit,
        localCommit: args.localCommit,
        remoteCommit: args.remoteCommit,
        status: args.status,
        diagnostics: args.diagnostics,
      })
      if (args.resultCommit) {
        await updateProjectReplicaSessionForServer({
          projectId: args.projectId,
          sessionId: args.sessionId,
          status: args.status,
          resultCommit: args.resultCommit,
          diagnostics: args.diagnostics,
        })
      }
    } catch (fallbackError) {
      console.warn('[ReplicaGit] Replica session persistence failed after fallback create', {
        projectId: args.projectId,
        sessionId: args.sessionId,
        status: args.status,
        error: fallbackError instanceof Error ? fallbackError.message : String(fallbackError),
      })
    }
  }
}

function encodeTextToBase64(value: string): string {
  return Buffer.from(value, 'utf-8').toString('base64')
}

function sha256Hex(value: Buffer): string {
  return createHash('sha256').update(value).digest('hex')
}

function createLfsPointerText(oid: string, size: number): string {
  return `${LFS_POINTER_VERSION}\noid sha256:${oid}\nsize ${size}\n`
}

function parseLfsPointerText(content: string): { oid: string; size: number } | null {
  if (!content.startsWith(LFS_POINTER_VERSION)) return null
  const oidMatch = content.match(/^oid sha256:([a-f0-9]{64})$/m)
  const sizeMatch = content.match(/^size ([0-9]+)$/m)
  if (!oidMatch || !sizeMatch) return null
  const size = Number(sizeMatch[1])
  if (!Number.isFinite(size) || size < 0) return null
  return {
    oid: oidMatch[1],
    size,
  }
}

function runGit(cwd: string, args: string[], stdin?: Buffer | string): GitResult {
  const result = spawnSync('git', args, {
    cwd,
    env: {
      ...process.env,
      GIT_TERMINAL_PROMPT: '0',
      GIT_CONFIG_NOSYSTEM: '1',
      GIT_ATTR_NOSYSTEM: '1',
    },
    input: stdin,
    encoding: 'utf-8',
    maxBuffer: 50 * 1024 * 1024,
  })

  return {
    ok: result.status === 0,
    code: result.status,
    stdout: result.stdout ?? '',
    stderr: result.stderr ?? '',
    stdoutBuffer: Buffer.isBuffer(result.stdout)
      ? result.stdout
      : Buffer.from(result.stdout ?? '', 'utf-8'),
  }
}

function runGitBytes(cwd: string, args: string[]): GitResult {
  const result = spawnSync('git', args, {
    cwd,
    env: {
      ...process.env,
      GIT_TERMINAL_PROMPT: '0',
      GIT_CONFIG_NOSYSTEM: '1',
      GIT_ATTR_NOSYSTEM: '1',
    },
    maxBuffer: 50 * 1024 * 1024,
    encoding: 'buffer',
  })
  const stdoutBuffer = Buffer.isBuffer(result.stdout) ? result.stdout : Buffer.alloc(0)
  const stderrBuffer = Buffer.isBuffer(result.stderr) ? result.stderr : Buffer.alloc(0)
  return {
    ok: result.status === 0,
    code: result.status,
    stdout: stdoutBuffer.toString('utf-8'),
    stderr: stderrBuffer.toString('utf-8'),
    stdoutBuffer,
  }
}

function ensureGitOk(result: GitResult, context: string): void {
  if (!result.ok) {
    const detail = result.stderr.trim() || result.stdout.trim() || `exit=${result.code}`
    throw new Error(`${context}: ${detail}`)
  }
}

async function ensureRepoInitialized(repoDir: string): Promise<void> {
  await mkdir(repoDir, { recursive: true })
  const gitDir = path.join(repoDir, '.git')
  if (!fs.existsSync(gitDir)) {
    ensureGitOk(runGit(repoDir, ['init']), 'Failed to init repository')
  }
  runGit(repoDir, ['config', 'user.name', 'Cozea Replica'])
  runGit(repoDir, ['config', 'user.email', 'replica@cozea.local'])
}

function commitExists(repoDir: string, commit: string | undefined): boolean {
  if (!commit) return false
  const result = runGit(repoDir, ['cat-file', '-e', `${commit}^{commit}`])
  return result.ok
}

function resolveCurrentHead(repoDir: string): string | undefined {
  const result = runGit(repoDir, ['rev-parse', '--verify', 'HEAD'])
  if (!result.ok) return undefined
  return result.stdout.trim() || undefined
}

function resolveCanonicalHead(repoDir: string): string | undefined {
  const canonical = runGit(repoDir, ['rev-parse', '--verify', CANONICAL_REF])
  if (canonical.ok) return canonical.stdout.trim() || undefined
  return resolveCurrentHead(repoDir)
}

function listCommitFiles(repoDir: string, commit: string | undefined): Set<string> {
  if (!commit) return new Set()
  const result = runGit(repoDir, ['ls-tree', '-r', '--name-only', commit])
  if (!result.ok) return new Set()
  const values = result.stdout
    .split(/\r?\n/)
    .map((value) => value.trim())
    .filter(Boolean)
  return new Set(values)
}

function parseNameStatusOutput(output: string): ParsedNameStatus[] {
  const records: ParsedNameStatus[] = []
  const tokens = output.split('\0').filter(Boolean)
  let index = 0
  while (index < tokens.length) {
    const status = tokens[index++]
    const code = status[0] ?? 'M'
    if (code === 'R' || code === 'C') {
      const _oldPath = tokens[index++] ?? ''
      const newPath = tokens[index++] ?? ''
      if (newPath) records.push({ code, path: newPath })
      continue
    }
    const filePath = tokens[index++] ?? ''
    if (filePath) records.push({ code, path: filePath })
  }
  return records
}

function getDiffMap(repoDir: string, baseCommit: string | undefined, targetCommit: string | undefined): Map<string, string> {
  if (!baseCommit || !targetCommit || baseCommit === targetCommit) return new Map()
  const result = runGit(repoDir, ['diff', '--name-status', '-z', baseCommit, targetCommit])
  if (!result.ok) return new Map()
  const parsed = parseNameStatusOutput(result.stdout)
  const map = new Map<string, string>()
  for (const entry of parsed) {
    map.set(entry.path, entry.code)
  }
  return map
}

function buildWorkspacePatchFromCommit(
  repoDir: string,
  commit: string
): Array<{
  path: string
  contentBase64: string
  encoding: 'base64'
}> {
  const workspacePatch: Array<{
    path: string
    contentBase64: string
    encoding: 'base64'
  }> = []

  for (const filePath of Array.from(listCommitFiles(repoDir, commit)).sort()) {
    const blobResult = runGitBytes(repoDir, ['show', `${commit}:${filePath}`])
    if (!blobResult.ok) continue
    workspacePatch.push({
      path: filePath,
      encoding: 'base64',
      contentBase64: encodeBufferToBase64(blobResult.stdoutBuffer),
    })
  }

  return workspacePatch
}

function mapChangeReason(code: string, lane: 'local' | 'remote'): string {
  if (lane === 'remote') {
    if (code === 'D') return 'Deleted in canonical replica'
    if (code === 'A') return 'Created in canonical replica'
    return 'Updated in canonical replica'
  }
  if (code === 'D') return 'Deleted locally'
  if (code === 'A') return 'Created locally'
  return 'Updated locally'
}

function isLikelyBinaryPath(filePath: string): boolean {
  const ext = filePath.split('.').pop()?.toLowerCase() ?? ''
  return [
    'png', 'jpg', 'jpeg', 'gif', 'webp', 'ico', 'bmp', 'tiff', 'svg',
    'pdf', 'zip', 'gz', 'tar', 'rar', '7z',
    'mp3', 'wav', 'ogg', 'mp4', 'mov', 'avi', 'webm',
    'ttf', 'otf', 'woff', 'woff2', 'eot', 'wasm',
  ].includes(ext)
}

function detectConflicts(repoDir: string): string[] {
  const result = runGit(repoDir, ['diff', '--name-only', '--diff-filter=U'])
  if (!result.ok) return []
  return result.stdout
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean)
}

function selectConflictKind(filePath: string): 'text' | 'binary' {
  return isLikelyBinaryPath(filePath) ? 'binary' : 'text'
}

async function downloadFile(url: string): Promise<Buffer> {
  const response = await fetch(url)
  if (!response.ok) {
    throw new Error(`Download failed (${response.status})`)
  }
  const arrayBuffer = await response.arrayBuffer()
  return Buffer.from(arrayBuffer)
}

async function uploadFile(uploadUrl: string, bytes: Buffer): Promise<string> {
  const response = await fetch(uploadUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/octet-stream',
    },
    body: bytes,
  })
  if (!response.ok) {
    throw new Error(`Upload failed (${response.status})`)
  }
  const json = await response.json() as { storageId?: string }
  if (!json.storageId) {
    throw new Error('Upload response is missing storageId')
  }
  return json.storageId
}

export async function materializeCanonicalRepository(projectId: string): Promise<{
  tempDir: string
  repoDir: string
  canonicalHead?: string
  replicaMeta: Awaited<ReturnType<typeof getProjectReplicaForServer>>
}> {
  const tempDir = await mkdtemp(path.join(os.tmpdir(), `cozea-replica-${projectId}-`))
  const repoDir = path.join(tempDir, 'repo')
  const replicaMeta = await getProjectReplicaForServer(projectId)

  if (replicaMeta?.bundleStorageId) {
    const url = await getStorageUrlForServer(replicaMeta.bundleStorageId)
    if (url) {
      const bundleBytes = await downloadFile(url)
      const bundlePath = path.join(tempDir, 'canonical.bundle')
      await writeFile(bundlePath, bundleBytes)
      ensureGitOk(runGit(tempDir, ['clone', bundlePath, repoDir]), 'Failed to clone canonical bundle')
      await ensureRepoInitialized(repoDir)
      return {
        tempDir,
        repoDir,
        canonicalHead: resolveCanonicalHead(repoDir),
        replicaMeta,
      }
    }
  }

  await ensureRepoInitialized(repoDir)
  return {
    tempDir,
    repoDir,
    canonicalHead: resolveCanonicalHead(repoDir),
    replicaMeta,
  }
}

function checkoutBranch(repoDir: string, branch: string, startPoint?: string): void {
  const args = startPoint
    ? ['checkout', '-B', branch, startPoint]
    : ['checkout', '-B', branch]
  ensureGitOk(runGit(repoDir, args), `Failed to checkout branch ${branch}`)
}

function createSnapshotCommit(repoDir: string, branch: string, snapshotFiles: ReplicaSnapshotFile[], startPoint?: string): string {
  if (startPoint && commitExists(repoDir, startPoint)) {
    checkoutBranch(repoDir, branch, startPoint)
  } else {
    const head = resolveCurrentHead(repoDir)
    if (head) {
      checkoutBranch(repoDir, branch, head)
    } else {
      checkoutBranch(repoDir, branch)
    }
  }
  const commit = snapshotCommitUnsafe(repoDir, snapshotFiles)
  return commit
}

function snapshotCommitUnsafe(repoDir: string, snapshotFiles: ReplicaSnapshotFile[]): string {
  const entries = fs.readdirSync(repoDir, { withFileTypes: true })
  for (const entry of entries) {
    if (entry.name === '.git') continue
    fs.rmSync(path.join(repoDir, entry.name), { recursive: true, force: true })
  }
  for (const file of snapshotFiles) {
    const rel = normalizeRepoPath(file.path)
    if (!rel || rel.startsWith('.git/')) continue
    const fullPath = path.join(repoDir, rel)
    fs.mkdirSync(path.dirname(fullPath), { recursive: true })
    fs.writeFileSync(fullPath, decodeBase64ToBuffer(file.contentBase64))
  }
  ensureGitOk(runGit(repoDir, ['add', '-A']), 'Failed to stage snapshot')
  ensureGitOk(
    runGit(repoDir, ['commit', '--allow-empty', '-m', `replica-snapshot:${Date.now()}`]),
    'Failed to create snapshot commit'
  )
  const commit = runGit(repoDir, ['rev-parse', '--verify', 'HEAD'])
  ensureGitOk(commit, 'Failed to resolve snapshot commit')
  return commit.stdout.trim()
}

async function storeCanonicalBundle(projectId: string, userId: string, repoDir: string, canonicalHead: string): Promise<void> {
  const bundlePath = path.join(repoDir, '..', 'canonical.bundle')
  ensureGitOk(runGit(repoDir, ['bundle', 'create', bundlePath, '--all']), 'Failed to create canonical bundle')
  const bundleBytes = await readFile(bundlePath)
  const checksum = sha256Hex(bundleBytes)
  const uploadUrl = await generateProjectReplicaBundleUploadUrlForServer(projectId)
  const storageId = await uploadFile(uploadUrl, bundleBytes)

  await upsertProjectReplicaForServer({
    projectId,
    userId,
    canonicalRef: CANONICAL_REF,
    headCommit: canonicalHead,
    bundleStorageId: storageId,
    bundleChecksum: checksum,
    bundleSizeBytes: bundleBytes.byteLength,
  })
}

async function ensureLfsObjectStored(args: {
  projectId: string
  userId: string
  oid: string
  size: number
  content: Buffer
}): Promise<void> {
  const existing = await getProjectReplicaLfsObjectForServer(args.projectId, args.oid)
  if (existing) {
    return
  }

  const uploadUrl = await generateProjectReplicaLfsUploadUrlForServer(args.projectId)
  const storageId = await uploadFile(uploadUrl, args.content)
  await upsertProjectReplicaLfsObjectForServer({
    projectId: args.projectId,
    userId: args.userId,
    oid: args.oid,
    size: args.size,
    storageId,
  })
}

async function rewriteSnapshotWithLfsPointers(args: {
  projectId: string
  userId: string
  snapshot: ReplicaSnapshotFile[]
}): Promise<ReplicaSnapshotFile[]> {
  const rewritten: ReplicaSnapshotFile[] = []

  for (const file of args.snapshot) {
    if (!file.isBinary) {
      rewritten.push(file)
      continue
    }

    const content = decodeBase64ToBuffer(file.contentBase64)
    const digest = sha256Hex(content)
    const oid = file.hash?.trim().toLowerCase() || digest
    const size = file.size >= 0 ? file.size : content.byteLength

    if (digest !== oid) {
      throw new Error(`Binary snapshot hash mismatch for ${file.path}`)
    }

    await ensureLfsObjectStored({
      projectId: args.projectId,
      userId: args.userId,
      oid,
      size,
      content,
    })

    const pointer = createLfsPointerText(oid, size)
    rewritten.push({
      ...file,
      isBinary: false,
      contentBase64: encodeTextToBase64(pointer),
      hash: sha256Hex(Buffer.from(pointer, 'utf-8')),
      size: pointer.length,
    })
  }

  return rewritten
}

function buildPlanFromDiffs(args: {
  localDiff: Map<string, string>
  remoteDiff: Map<string, string>
  conflictPaths: Set<string>
}): Omit<ReplicaPlanResponse, 'success' | 'sessionId' | 'noChange'> {
  const downloads: ReplicaPlanOperation[] = []
  const uploads: ReplicaPlanOperation[] = []
  const localDeletes: ReplicaPlanOperation[] = []
  const cloudDeletes: ReplicaPlanOperation[] = []
  const autoMerged: ReplicaPlanOperation[] = []
  const conflicts: ReplicaPlanConflict[] = []

  const allPaths = new Set<string>([
    ...Array.from(args.localDiff.keys()),
    ...Array.from(args.remoteDiff.keys()),
  ])

  for (const filePath of allPaths) {
    const localCode = args.localDiff.get(filePath)
    const remoteCode = args.remoteDiff.get(filePath)
    const bothChanged = Boolean(localCode) && Boolean(remoteCode)
    const hasConflict = args.conflictPaths.has(filePath)

    if (bothChanged && hasConflict) {
      conflicts.push({
        path: filePath,
        reason: 'Concurrent local and canonical changes could not be auto-merged',
        kind: selectConflictKind(filePath),
        localExists: localCode !== 'D',
        remoteExists: remoteCode !== 'D',
      })
      continue
    }

    if (bothChanged) {
      autoMerged.push({
        path: filePath,
        reason: 'Concurrent local and canonical changes auto-merged',
      })
      continue
    }

    if (localCode && !remoteCode) {
      if (localCode === 'D') {
        cloudDeletes.push({ path: filePath, reason: mapChangeReason(localCode, 'local') })
      } else {
        uploads.push({ path: filePath, reason: mapChangeReason(localCode, 'local') })
      }
      continue
    }

    if (!localCode && remoteCode) {
      if (remoteCode === 'D') {
        localDeletes.push({ path: filePath, reason: mapChangeReason(remoteCode, 'remote') })
      } else {
        downloads.push({ path: filePath, reason: mapChangeReason(remoteCode, 'remote') })
      }
    }
  }

  return {
    downloads,
    uploads,
    localDeletes,
    cloudDeletes,
    autoMerged,
    conflicts,
  }
}

async function acquireReplicaLock(projectId: string, owner: string): Promise<boolean> {
  const redis = getReplicaLockClient()
  const key = `replica-git:lock:${projectId}`
  const startedAt = Date.now()

  if (redis) {
    while (Date.now() - startedAt < LOCK_WAIT_MS) {
      const result = await redis.set(key, owner, 'PX', LOCK_TTL_MS, 'NX')
      if (result === 'OK') return true
      await new Promise((resolve) => setTimeout(resolve, LOCK_RETRY_MS))
    }
    return false
  }

  while (Date.now() - startedAt < LOCK_WAIT_MS) {
    const now = Date.now()
    const current = FALLBACK_LOCKS.get(key)
    if (!current || current.expiresAt <= now) {
      FALLBACK_LOCKS.set(key, { owner, expiresAt: now + LOCK_TTL_MS })
      return true
    }
    await new Promise((resolve) => setTimeout(resolve, LOCK_RETRY_MS))
  }
  return false
}

async function releaseReplicaLock(projectId: string, owner: string): Promise<void> {
  const redis = getReplicaLockClient()
  const key = `replica-git:lock:${projectId}`
  if (redis) {
    const script = `
      if redis.call("GET", KEYS[1]) == ARGV[1] then
        return redis.call("DEL", KEYS[1])
      end
      return 0
    `
    await redis.eval(script, 1, key, owner)
    return
  }

  const current = FALLBACK_LOCKS.get(key)
  if (current?.owner === owner) {
    FALLBACK_LOCKS.delete(key)
  }
}

async function withReplicaLock<T>(projectId: string, owner: string, action: () => Promise<T>): Promise<T> {
  const acquired = await acquireReplicaLock(projectId, owner)
  if (!acquired) {
    throw new Error('Timed out waiting for replica lock')
  }
  try {
    return await action()
  } finally {
    await releaseReplicaLock(projectId, owner)
  }
}

export async function bootstrapReplica(args: {
  projectId: string
  userId: string
  localSnapshot: ReplicaSnapshotFile[]
}): Promise<{
  success: boolean
  canonicalRef?: string
  headCommit?: string
  seededFrom?: 'canonical' | 'local' | 'empty'
  error?: string
}> {
  const owner = `bootstrap:${args.projectId}:${randomUUID()}`

  try {
    return await withReplicaLock(args.projectId, owner, async () => {
      const existing = await getProjectReplicaForServer(args.projectId)
      if (existing) {
        return {
          success: true,
          canonicalRef: existing.canonicalRef,
          headCommit: existing.headCommit,
          seededFrom: 'canonical' as const,
        }
      }

      let seedFiles = args.localSnapshot
      const seededFrom: 'local' | 'empty' = seedFiles.length > 0 ? 'local' : 'empty'

      if (seedFiles.length > 0) {
        seedFiles = await rewriteSnapshotWithLfsPointers({
          projectId: args.projectId,
          userId: args.userId,
          snapshot: seedFiles,
        })
      }

      const { tempDir, repoDir } = await materializeCanonicalRepository(args.projectId)
      try {
        const canonicalBranch = 'canonical'
        checkoutBranch(repoDir, canonicalBranch)
        const headCommit = createSnapshotCommit(repoDir, canonicalBranch, seedFiles, undefined)
        await storeCanonicalBundle(args.projectId, args.userId, repoDir, headCommit)
        return {
          success: true,
          canonicalRef: CANONICAL_REF,
          headCommit,
          seededFrom,
        }
      } finally {
        await rm(tempDir, { recursive: true, force: true })
      }
    })
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Bootstrap failed',
    }
  }
}

export async function planReplica(args: {
  projectId: string
  userId: string
  sessionId: string
  baseCommit?: string
  localSnapshot: ReplicaSnapshotFile[]
  deviceId?: string
}): Promise<ReplicaPlanResponse> {
  const startedAt = Date.now()
  const owner = `plan:${args.projectId}:${args.sessionId}:${randomUUID()}`
  try {
    return await withReplicaLock(args.projectId, owner, async () => {
      const { tempDir, repoDir } = await materializeCanonicalRepository(args.projectId)
      try {
        const normalizedSnapshot = await rewriteSnapshotWithLfsPointers({
          projectId: args.projectId,
          userId: args.userId,
          snapshot: args.localSnapshot,
        })
        const remoteCommit = resolveCanonicalHead(repoDir)
        const effectiveBase = commitExists(repoDir, args.baseCommit) ? args.baseCommit : remoteCommit
        const remoteFiles = listCommitFiles(repoDir, remoteCommit)

        // Recovery path: local workspace was wiped, but canonical still has files.
        // Prefer restoring local files from cloud over planning destructive cloud deletes.
        if (normalizedSnapshot.length === 0 && remoteFiles.size > 0) {
          const downloads: ReplicaPlanOperation[] = Array.from(remoteFiles)
            .sort()
            .map((filePath) => ({
              path: filePath,
              reason: 'Local workspace is empty; restore from canonical replica',
            }))

          const response: ReplicaPlanResponse = {
            success: true,
            sessionId: args.sessionId,
            baseCommit: effectiveBase,
            remoteCommit,
            downloads,
            uploads: [],
            localDeletes: [],
            cloudDeletes: [],
            autoMerged: [],
            conflicts: [],
            noChange: 0,
          }

          await createProjectReplicaSessionForServer({
            projectId: args.projectId,
            sessionId: args.sessionId,
            userId: args.userId,
            deviceId: args.deviceId,
            baseCommit: response.baseCommit,
            remoteCommit: response.remoteCommit,
            status: 'planned',
            diagnostics: {
              mergeDurationMs: Date.now() - startedAt,
              changedPaths: downloads.length,
            },
          })

          return response
        }

        const localStart = effectiveBase ?? remoteCommit
        const localCommit = createSnapshotCommit(repoDir, `session-${args.sessionId}`, normalizedSnapshot, localStart)

        const localDiff = getDiffMap(repoDir, effectiveBase, localCommit)
        const remoteDiff = getDiffMap(repoDir, effectiveBase, remoteCommit)

        let conflictPaths = new Set<string>()
        if (remoteCommit && localCommit && remoteCommit !== localCommit) {
          checkoutBranch(repoDir, '__cozea_merge_probe', remoteCommit)
          const mergeResult = runGit(repoDir, ['merge', '--no-commit', '--no-ff', localCommit])
          if (!mergeResult.ok) {
            conflictPaths = new Set(detectConflicts(repoDir))
            runGit(repoDir, ['merge', '--abort'])
          } else {
            runGit(repoDir, ['merge', '--abort'])
          }
        }

        const planOps = buildPlanFromDiffs({
          localDiff,
          remoteDiff,
          conflictPaths,
        })

        const changedPaths = new Set<string>([
          ...planOps.downloads.map((entry) => entry.path),
          ...planOps.uploads.map((entry) => entry.path),
          ...planOps.localDeletes.map((entry) => entry.path),
          ...planOps.cloudDeletes.map((entry) => entry.path),
          ...planOps.autoMerged.map((entry) => entry.path),
          ...planOps.conflicts.map((entry) => entry.path),
        ])

        const unionPaths = new Set<string>([
          ...listCommitFiles(repoDir, remoteCommit),
          ...normalizedSnapshot.map((file) => normalizeRepoPath(file.path)),
        ])

        const response: ReplicaPlanResponse = {
          success: true,
          sessionId: args.sessionId,
          baseCommit: effectiveBase,
          localCommit,
          remoteCommit,
          downloads: planOps.downloads,
          uploads: planOps.uploads,
          localDeletes: planOps.localDeletes,
          cloudDeletes: planOps.cloudDeletes,
          autoMerged: planOps.autoMerged,
          conflicts: planOps.conflicts,
          noChange: Math.max(0, unionPaths.size - changedPaths.size),
        }

        await createProjectReplicaSessionForServer({
          projectId: args.projectId,
          sessionId: args.sessionId,
          userId: args.userId,
          deviceId: args.deviceId,
          baseCommit: response.baseCommit,
          localCommit: response.localCommit,
          remoteCommit: response.remoteCommit,
          status: response.conflicts.length > 0 ? 'conflict' : 'planned',
          diagnostics: {
            mergeDurationMs: Date.now() - startedAt,
            changedPaths: changedPaths.size,
          },
        })

        return response
      } finally {
        await rm(tempDir, { recursive: true, force: true })
      }
    })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Replica planning failed'
    await createProjectReplicaSessionForServer({
      projectId: args.projectId,
      sessionId: args.sessionId,
      userId: args.userId,
      deviceId: args.deviceId,
      status: 'failed',
      diagnostics: {
        failureClass: 'plan',
        error: message,
      },
    })
    return {
      success: false,
      sessionId: args.sessionId,
      downloads: [],
      uploads: [],
      localDeletes: [],
      cloudDeletes: [],
      autoMerged: [],
      conflicts: [],
      noChange: 0,
      error: message,
    }
  }
}

export async function executeReplica(args: {
  projectId: string
  userId: string
  sessionId: string
  baseCommit?: string
  localSnapshot: ReplicaSnapshotFile[]
  conflictDecisions?: Record<string, 'local' | 'cloud'>
}): Promise<ReplicaExecuteResponse> {
  const startedAt = Date.now()
  const owner = `apply:${args.projectId}:${args.sessionId}:${randomUUID()}`
  let stage = 'acquire_lock'
  try {
    return await withReplicaLock(args.projectId, owner, async () => {
      stage = 'materialize_canonical_repository'
      const { tempDir, repoDir } = await materializeCanonicalRepository(args.projectId)
      try {
        stage = 'rewrite_snapshot_with_lfs_pointers'
        const normalizedSnapshot = await rewriteSnapshotWithLfsPointers({
          projectId: args.projectId,
          userId: args.userId,
          snapshot: args.localSnapshot,
        })
        stage = 'resolve_remote_commit'
        const remoteCommit = resolveCanonicalHead(repoDir)
        const effectiveBase = commitExists(repoDir, args.baseCommit) ? args.baseCommit : remoteCommit

        // Recovery path: local workspace is empty but canonical has files.
        // Hydrate local files from canonical without mutating cloud state.
        if (normalizedSnapshot.length === 0 && remoteCommit && listCommitFiles(repoDir, remoteCommit).size > 0) {
          stage = 'build_workspace_patch_from_canonical'
          const workspacePatch = buildWorkspacePatchFromCommit(repoDir, remoteCommit)

          stage = 'persist_applied_session_restore'
          await persistReplicaSessionStatusBestEffort({
            projectId: args.projectId,
            sessionId: args.sessionId,
            userId: args.userId,
            status: 'applied',
            baseCommit: effectiveBase,
            remoteCommit,
            resultCommit: remoteCommit,
            diagnostics: {
              mergeDurationMs: Date.now() - startedAt,
              workspacePatchCount: workspacePatch.length,
            },
          })

          return {
            success: true,
            applied: true,
            canonicalHeadCommit: remoteCommit,
            diagnostics: {
              baseCommit: effectiveBase,
              remoteCommit,
              resultCommit: remoteCommit,
              mergeDurationMs: Date.now() - startedAt,
            },
            workspacePatch,
          }
        }

        stage = 'create_local_snapshot_commit'
        const localCommit = createSnapshotCommit(
          repoDir,
          `session-${args.sessionId}`,
          normalizedSnapshot,
          effectiveBase ?? remoteCommit
        )

        stage = 'diff_local_and_remote'
        const localDiff = getDiffMap(repoDir, effectiveBase, localCommit)
        const remoteDiff = getDiffMap(repoDir, effectiveBase, remoteCommit)

        if (!remoteCommit) {
          stage = 'bootstrap_canonical_branch'
          checkoutBranch(repoDir, 'canonical', localCommit)
          const resultCommit = resolveCurrentHead(repoDir)
          if (!resultCommit) {
            throw new Error('Failed to resolve canonical head after bootstrap apply')
          }
          stage = 'store_bootstrap_bundle'
          await storeCanonicalBundle(args.projectId, args.userId, repoDir, resultCommit)
          stage = 'persist_applied_session_bootstrap'
          await persistReplicaSessionStatusBestEffort({
            projectId: args.projectId,
            sessionId: args.sessionId,
            userId: args.userId,
            status: 'applied',
            baseCommit: effectiveBase,
            localCommit,
            remoteCommit,
            resultCommit,
            diagnostics: {
              mergeDurationMs: Date.now() - startedAt,
            },
          })
          return {
            success: true,
            applied: true,
            diagnostics: {
              baseCommit: effectiveBase,
              localCommit,
              remoteCommit,
              resultCommit,
              mergeDurationMs: Date.now() - startedAt,
            },
            canonicalHeadCommit: resultCommit,
            workspacePatch: [],
          }
        }

        stage = 'merge_local_into_canonical'
        checkoutBranch(repoDir, '__cozea_apply', remoteCommit)
        const mergeResult = runGit(repoDir, ['merge', '--no-commit', '--no-ff', localCommit])
        let conflictPaths = new Set<string>()
        if (!mergeResult.ok) {
          stage = 'detect_conflicts'
          conflictPaths = new Set(detectConflicts(repoDir))
        }

        if (conflictPaths.size > 0) {
          const missingDecision = Array.from(conflictPaths).find((filePath) => !args.conflictDecisions?.[filePath])
          if (missingDecision) {
            const conflicts: ReplicaPlanConflict[] = Array.from(conflictPaths).map((filePath) => ({
              path: filePath,
              reason: 'Conflict requires explicit local/cloud decision',
              kind: selectConflictKind(filePath),
              localExists: localDiff.get(filePath) !== 'D',
              remoteExists: remoteDiff.get(filePath) !== 'D',
            }))
            stage = 'persist_conflict_session'
            await persistReplicaSessionStatusBestEffort({
              projectId: args.projectId,
              sessionId: args.sessionId,
              userId: args.userId,
              status: 'conflict',
              baseCommit: effectiveBase,
              localCommit,
              remoteCommit,
              diagnostics: {
                conflictCount: conflicts.length,
                mergeDurationMs: Date.now() - startedAt,
              },
            })
            runGit(repoDir, ['merge', '--abort'])
            return {
              success: true,
              applied: false,
              requiresConflictResolution: true,
              conflicts,
              diagnostics: {
                baseCommit: effectiveBase,
                localCommit,
                remoteCommit,
                mergeDurationMs: Date.now() - startedAt,
              },
            }
          }

          // TODO(sync): replace whole-file local/cloud conflict decisions for text files
          // with hunk-level resolution payloads to avoid dropping unrelated edits.
          stage = 'resolve_conflicts_from_decisions'
          for (const filePath of conflictPaths) {
            const decision = args.conflictDecisions?.[filePath]
            if (decision === 'local') {
              const checkoutLocal = runGit(repoDir, ['checkout', localCommit, '--', filePath])
              if (!checkoutLocal.ok) {
                runGit(repoDir, ['rm', '-f', '--ignore-unmatch', '--', filePath])
              }
            } else {
              const checkoutRemote = runGit(repoDir, ['checkout', remoteCommit, '--', filePath])
              if (!checkoutRemote.ok) {
                runGit(repoDir, ['rm', '-f', '--ignore-unmatch', '--', filePath])
              }
            }
          }
        }

        stage = 'commit_merged_state'
        ensureGitOk(runGit(repoDir, ['add', '-A']), 'Failed to stage merged state')
        const commitMerged = runGit(
          repoDir,
          ['commit', '--allow-empty', '-m', `replica-merge:${args.sessionId}`]
        )
        ensureGitOk(commitMerged, 'Failed to finalize merge commit')
        stage = 'resolve_result_commit'
        const resultCommitResult = runGit(repoDir, ['rev-parse', '--verify', 'HEAD'])
        ensureGitOk(resultCommitResult, 'Failed to resolve result commit')
        const resultCommit = resultCommitResult.stdout.trim()

        stage = 'store_canonical_bundle'
        checkoutBranch(repoDir, 'canonical', resultCommit)
        await storeCanonicalBundle(args.projectId, args.userId, repoDir, resultCommit)

        stage = 'build_workspace_patch_from_merge_result'
        const patchResult = runGit(repoDir, ['diff', '--name-status', '-z', localCommit, resultCommit])
        const patchEntries = patchResult.ok ? parseNameStatusOutput(patchResult.stdout) : []
        const workspacePatch: Array<{
          path: string
          deleted?: boolean
          contentBase64?: string
          encoding?: 'base64'
        }> = []

        for (const entry of patchEntries) {
          if (entry.code === 'D') {
            workspacePatch.push({ path: entry.path, deleted: true })
            continue
          }
          const blobResult = runGitBytes(repoDir, ['show', `${resultCommit}:${entry.path}`])
          if (!blobResult.ok) continue
          workspacePatch.push({
            path: entry.path,
            encoding: 'base64',
            contentBase64: encodeBufferToBase64(blobResult.stdoutBuffer),
          })
        }

        stage = 'persist_applied_session_merge'
        await persistReplicaSessionStatusBestEffort({
          projectId: args.projectId,
          sessionId: args.sessionId,
          userId: args.userId,
          status: 'applied',
          baseCommit: effectiveBase,
          localCommit,
          remoteCommit,
          resultCommit,
          diagnostics: {
            mergeDurationMs: Date.now() - startedAt,
            workspacePatchCount: workspacePatch.length,
          },
        })

        return {
          success: true,
          applied: true,
          canonicalHeadCommit: resultCommit,
          diagnostics: {
            baseCommit: effectiveBase,
            localCommit,
            remoteCommit,
            resultCommit,
            mergeDurationMs: Date.now() - startedAt,
          },
          workspacePatch,
        }
      } finally {
        await rm(tempDir, { recursive: true, force: true })
      }
    })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Replica apply failed'
    console.error('[ReplicaGit] Execute failed', {
      projectId: args.projectId,
      sessionId: args.sessionId,
      stage,
      error: message,
    })
    await updateProjectReplicaSessionForServer({
      projectId: args.projectId,
      sessionId: args.sessionId,
      status: 'failed',
      diagnostics: {
        failureClass: 'apply',
        error: message,
      },
    }).catch(() => undefined)
    return {
      success: false,
      applied: false,
      error: `[${stage}] ${message}`,
      diagnostics: {
        failureClass: 'apply',
      },
    }
  }
}

export async function hydrateWorkspaceFromReplica(args: {
  projectId: string
  workspaceDir: string
}): Promise<ReplicaWorkspaceHydrationResult> {
  try {
    const { tempDir, repoDir, canonicalHead } = await materializeCanonicalRepository(args.projectId)
    try {
      if (!canonicalHead) {
        return {
          success: true,
          source: 'none',
          written: 0,
        }
      }

      await mkdir(args.workspaceDir, { recursive: true })
      const workspacePatch = buildWorkspacePatchFromCommit(repoDir, canonicalHead)
      let written = 0

      for (const entry of workspacePatch) {
        const normalizedPath = normalizeRepoPath(entry.path)
        if (!normalizedPath || normalizedPath.startsWith('../')) {
          continue
        }

        const absolutePath = path.join(args.workspaceDir, normalizedPath.split('/').join(path.sep))
        const relative = path.relative(args.workspaceDir, absolutePath)
        if (relative.startsWith('..') || path.isAbsolute(relative)) {
          continue
        }

        await mkdir(path.dirname(absolutePath), { recursive: true })
        await writeFile(absolutePath, decodeBase64ToBuffer(entry.contentBase64))
        written += 1
      }

      return {
        success: true,
        source: 'canonical',
        written,
        canonicalHead,
      }
    } finally {
      await rm(tempDir, { recursive: true, force: true })
    }
  } catch (error) {
    return {
      success: false,
      source: 'none',
      written: 0,
      error: error instanceof Error ? error.message : 'Replica hydration failed',
    }
  }
}

