export async function putReplicaLfsObject(args: {
  projectId: string
  userId: string
  oid: string
  size: number
  contentBase64: string
}): Promise<{ success: boolean; oid: string; size: number; error?: string }> {
  try {
    const bytes = decodeBase64ToBuffer(args.contentBase64)
    const checksum = sha256Hex(bytes)
    if (checksum !== args.oid) {
      return {
        success: false,
        oid: args.oid,
        size: args.size,
        error: 'OID does not match payload SHA256',
      }
    }

    const uploadUrl = await generateProjectReplicaLfsUploadUrlForServer(args.projectId)
    const storageId = await uploadFile(uploadUrl, bytes)
    await upsertProjectReplicaLfsObjectForServer({
      projectId: args.projectId,
      userId: args.userId,
      oid: args.oid,
      size: args.size,
      storageId,
    })
    return {
      success: true,
      oid: args.oid,
      size: args.size,
    }
  } catch (error) {
    return {
      success: false,
      oid: args.oid,
      size: args.size,
      error: error instanceof Error ? error.message : 'Failed to store LFS object',
    }
  }
}

export async function getReplicaLfsObject(args: {
  projectId: string
  oid: string
}): Promise<{ success: boolean; oid: string; size?: number; contentBase64?: string; error?: string }> {
  try {
    const object = await getProjectReplicaLfsObjectForServer(args.projectId, args.oid)
    if (!object?.url) {
      return {
        success: false,
        oid: args.oid,
        error: 'LFS object not found',
      }
    }
    const bytes = await downloadFile(object.url)
    return {
      success: true,
      oid: args.oid,
      size: object.size,
      contentBase64: encodeBufferToBase64(bytes),
    }
  } catch (error) {
    return {
      success: false,
      oid: args.oid,
      error: error instanceof Error ? error.message : 'Failed to fetch LFS object',
    }
  }
}

