// Validate redirect URIs in production
function isValidRedirectUri(uri: string): boolean {
  // Allow custom protocols for desktop apps
  if (uri.startsWith('cozea://') || uri.startsWith('cozea-dev://') || uri.startsWith('vscode://')) {
    return true
  }
  // In production, require HTTPS
  if (process.env.NODE_ENV === 'production') {
    return uri.startsWith('https://')
  }
  // In development, allow HTTP localhost
  return uri.startsWith('http://localhost') || uri.startsWith('https://')
}

function isAllowedDesktopRedirectUri(uri: string): boolean {
  return (
    uri.startsWith('cozea://') ||
    uri.startsWith('cozea-dev://') ||
    uri.startsWith('vscode://cozea.workos-authentication/')
  )
}

function normalizeHttpUrl(uri: string): string | null {
  try {
    const url = new URL(uri)
    const normalizedPathname = url.pathname.replace(/\/+$/, '') || '/'
    return `${url.origin}${normalizedPathname}`
  } catch {
    return null
  }
}

function getConfiguredWebRedirectAllowlist(defaultWebRedirectUri: string): Set<string> {
  const normalized = new Set<string>()
  const defaultNormalized = normalizeHttpUrl(defaultWebRedirectUri)
  if (defaultNormalized) {
    normalized.add(defaultNormalized)
  }

  const rawAllowlist = (process.env.WEB_REDIRECT_URI_ALLOWLIST || '').trim()
  if (!rawAllowlist) {
    return normalized
  }

  for (const value of rawAllowlist.split(',')) {
    const candidate = normalizeHttpUrl(value.trim())
    if (candidate) {
      normalized.add(candidate)
    }
  }

  return normalized
}

function isAllowedWebRedirectUri(uri: string, defaultWebRedirectUri: string): boolean {
  const normalizedCandidate = normalizeHttpUrl(uri)
  if (!normalizedCandidate) {
    return false
  }

  let parsed: URL
  try {
    parsed = new URL(uri)
  } catch {
    return false
  }

  const protocol = parsed.protocol.toLowerCase()
  const isHttps = protocol === 'https:'
  const isHttp = protocol === 'http:'
  const isLocalhost = parsed.hostname === 'localhost' || parsed.hostname === '127.0.0.1'
  const isDevelopment = process.env.NODE_ENV !== 'production'
  const normalizedPath = parsed.pathname.toLowerCase()
  const looksLikeAuthCallbackPath =
    normalizedPath.endsWith('/api/auth/callback') || normalizedPath.endsWith('/auth/callback')
  const allowlist = getConfiguredWebRedirectAllowlist(defaultWebRedirectUri)

  if (isHttp && isLocalhost && looksLikeAuthCallbackPath) {
    // Allow loopback callbacks for native/local development auth bridges.
    // These redirects only receive a short-lived one-time token and resolve
    // on the same machine that initiated the login flow.
    return true
  }

  if (!isHttps) {
    return false
  }

  return allowlist.has(normalizedCandidate)
}

interface RefreshErrorDiagnostics {
  statusCode?: number
  requestId?: string
  name?: string
  message?: string
  rawData?: unknown
}

function getRefreshErrorDiagnostics(err: unknown): RefreshErrorDiagnostics {
  if (!err || typeof err !== 'object') {
    return {}
  }

  const data = err as Record<string, unknown>
  return {
    statusCode: typeof data.status === 'number' ? data.status : undefined,
    requestId: typeof data.requestID === 'string' ? data.requestID : undefined,
    name: typeof data.name === 'string' ? data.name : undefined,
    message: typeof data.message === 'string' ? data.message : undefined,
    rawData: 'rawData' in data ? data.rawData : undefined,
  }
}

function normalizeHostHeader(value: string | undefined): string | null {
  if (!value) return null
  return value.split(',')[0]?.trim().toLowerCase() || null
}

function stripDefaultPort(host: string): string {
  if (host.endsWith(':80')) return host.slice(0, -3)
  if (host.endsWith(':443')) return host.slice(0, -4)
  return host
}

const VALID_WAITLIST_ROLES = new Set(['nontechnical', 'developer', 'both'])
const MAX_WAITLIST_NAME_LENGTH = 120
const MAX_WAITLIST_SOURCE_LENGTH = 120
const WAITLIST_ERROR_CODE = 'waitlisted'
