type WaitlistEnforcementMode = 'off' | 'desktop'

function isValidEmail(email: string): boolean {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
}

function buildDesktopAuthErrorRedirect(baseRedirectUri: string, errorCode: string): string {
  const url = new URL(baseRedirectUri)
  url.searchParams.set('error', errorCode)
  return url.toString()
}

