function getOptionalQueryParam(value: unknown): string | undefined {
  if (typeof value !== 'string') return undefined
  const trimmed = value.trim()
  return trimmed.length > 0 ? trimmed : undefined
}

export const authRoutes: FastifyPluginAsync = async (fastify) => {
  const clientId = process.env.WORKOS_CLIENT_ID || ''
  const redirectUri = process.env.WORKOS_REDIRECT_URI || 'http://localhost:3001/auth/callback'
  const desktopRedirectUri = process.env.DESKTOP_REDIRECT_URI || 'cozea://auth/callback'
  const frontendUrl = process.env.FRONTEND_URL || 'http://localhost:3000'
  const webRedirectUri =
    process.env.WEB_REDIRECT_URI ||
    `${frontendUrl.replace(/\/+$/, '')}/api/auth/callback`
  const stateSecret = process.env.WORKOS_COOKIE_PASSWORD || 'development-secret'
  const waitlistEnforcementModeRaw = (process.env.WAITLIST_ENFORCEMENT_MODE || 'off').trim().toLowerCase()
  const waitlistEnforcementMode: WaitlistEnforcementMode =
    waitlistEnforcementModeRaw === 'desktop' ? 'desktop' : 'off'

  if (waitlistEnforcementModeRaw !== 'off' && waitlistEnforcementModeRaw !== 'desktop') {
    if (process.env.NODE_ENV === 'production') {
      throw new Error(
        `WAITLIST_ENFORCEMENT_MODE must be one of: off, desktop. Received: ${waitlistEnforcementModeRaw}`
      )
    }
    fastify.log.warn(
      { waitlistEnforcementModeRaw },
      'Invalid WAITLIST_ENFORCEMENT_MODE, defaulting to off for development'
    )
  }

  if (!clientId) {
    if (process.env.NODE_ENV === 'production') {
      throw new Error('WORKOS_CLIENT_ID must be configured in production')
    }
    fastify.log.warn('WORKOS_CLIENT_ID not set - auth routes will not work correctly')
  }

  if (stateSecret === 'development-secret') {
    if (process.env.NODE_ENV === 'production') {
      throw new Error('WORKOS_COOKIE_PASSWORD must be configured in production')
    }
    fastify.log.warn('WORKOS_COOKIE_PASSWORD not set - using insecure development fallback')
  }

  // Validate configured redirect URIs at startup
  if (process.env.NODE_ENV === 'production') {
    if (!isValidRedirectUri(redirectUri)) {
      throw new Error(`WORKOS_REDIRECT_URI must use HTTPS in production: ${redirectUri}`)
    }
    if (!isValidRedirectUri(desktopRedirectUri)) {
      throw new Error(`DESKTOP_REDIRECT_URI must use HTTPS or custom protocol: ${desktopRedirectUri}`)
    }
    if (!isValidRedirectUri(webRedirectUri)) {
      throw new Error(`WEB_REDIRECT_URI must use HTTPS in production: ${webRedirectUri}`)
    }
  }

  // GET /auth - Root auth route (avoid 404)
  fastify.get('/', async (_request, reply) => {
    return reply.redirect('/auth/login?client=desktop')
  })

  // GET /auth/login - Initiate login flow
  fastify.get<{
    Querystring: {
      client?: string
      state?: string
      redirectUri?: string
      invitationToken?: string
      invitation_token?: string
    }
  }>('/login', async (request, reply) => {
    const {
      client,
      state,
      redirectUri: requestedRedirectUri,
      invitationToken: invitationTokenQuery,
      invitation_token: invitationTokenQueryLegacy,
    } = request.query
    const clientType = client || 'web' // 'desktop', 'vscode', or 'web'
    const trimmedRequestedRedirectUri =
      typeof requestedRedirectUri === 'string' ? requestedRedirectUri.trim() : ''
    const requestedDesktopRedirectUri =
      clientType === 'desktop' ? trimmedRequestedRedirectUri : ''
    const requestedWebRedirectUri =
      clientType === 'web' ? trimmedRequestedRedirectUri : ''
    const invitationToken =
      getOptionalQueryParam(invitationTokenQuery) ?? getOptionalQueryParam(invitationTokenQueryLegacy)

    if (
      clientType === 'desktop' &&
      requestedDesktopRedirectUri &&
      !isAllowedDesktopRedirectUri(requestedDesktopRedirectUri)
    ) {
      return reply.status(400).send({ error: 'Invalid desktop redirect URI' })
    }
    if (
      clientType === 'web' &&
      requestedWebRedirectUri &&
      !isAllowedWebRedirectUri(requestedWebRedirectUri, webRedirectUri)
    ) {
      return reply.status(400).send({ error: 'Invalid web redirect URI' })
    }

    try {
      let invitationEmail: string | undefined
      let invitationOrganizationId: string | undefined

      if (invitationToken) {
        try {
          const invitation = await fastify.workos.userManagement.findInvitationByToken(invitationToken)
          if (invitation.state && invitation.state !== 'pending') {
            return reply.status(400).type('text/html').send(
              renderAuthRecoveryPage({
                title: 'Invitation Unavailable',
                heading: 'This invitation is no longer available',
                description:
                  invitation.state === 'accepted'
                    ? 'This workspace invitation has already been accepted. Sign in to continue.'
                    : 'This workspace invitation is no longer pending. Ask a workspace admin to resend it.',
                primaryLabel: 'Sign in',
                primaryHref: '/auth/login?client=web',
              }),
            )
          }
          invitationEmail = invitation.email?.trim() || undefined
          invitationOrganizationId = invitation.organizationId || undefined
        } catch (err) {
          fastify.log.warn({ err }, 'Rejected login request with invalid WorkOS invitation token')
          return reply.status(400).type('text/html').send(
            renderAuthRecoveryPage({
              title: 'Invitation Invalid',
              heading: 'This invitation link is invalid',
              description:
                'The workspace invite could not be verified. Ask a workspace admin to resend the invitation email.',
              primaryLabel: 'Sign in',
              primaryHref: '/auth/login?client=web',
            }),
          )
        }
      }

      // Create HMAC-signed state to prevent CSRF
      const signedState = signState(
        {
          clientType,
          originalState: state || '',
          desktopRedirectUri: clientType === 'desktop' ? requestedDesktopRedirectUri : undefined,
          webRedirectUri: clientType === 'web' ? requestedWebRedirectUri : undefined,
          flow: invitationToken ? 'invitation' : 'login',
          invitationToken,
        },
        stateSecret,
      )

      // Generate authorization URL
      // Force account chooser so browser auth does not silently reuse a prior SSO session.
      const authPrompt = 'select_account'
      const authorizationUrl = fastify.workos.userManagement.getAuthorizationUrl({
        provider: 'authkit',
        clientId,
        redirectUri,
        state: signedState,
        prompt: authPrompt,
        loginHint: invitationEmail,
        organizationId: invitationOrganizationId,
        providerQueryParams: {
          prompt: authPrompt,
        },
        screenHint: 'sign-in',
      })

      return reply.redirect(authorizationUrl)
    } catch (err) {
      fastify.log.error({ err, clientId, redirectUri }, 'Failed to generate authorization URL')

      // Return a user-friendly error page
      return reply.status(500).type('text/html').send(`
        <!DOCTYPE html>
        <html>
          <head>
            <title>Authentication Error - Cozea</title>
            <style>
              body {
                font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
                display: flex;
                justify-content: center;
                align-items: center;
                min-height: 100vh;
                margin: 0;
                background: #0a0a0a;
                color: #fff;
              }
              .container {
                text-align: center;
                padding: 2rem;
                max-width: 400px;
              }
              h1 { color: #ef4444; margin-bottom: 1rem; }
              p { color: #a1a1aa; line-height: 1.6; }
              .error-code {
                font-family: monospace;
                background: #1f1f1f;
                padding: 0.5rem 1rem;
                border-radius: 4px;
                margin-top: 1rem;
                font-size: 0.875rem;
                color: #f87171;
              }
              a {
                color: #3b82f6;
                text-decoration: none;
              }
              a:hover { text-decoration: underline; }
            </style>
          </head>
          <body>
            <div class="container">
              <h1>Authentication Error</h1>
              <p>We couldn't start the login process. This might be a configuration issue.</p>
              <p>Please contact support or <a href="/auth/login?client=${clientType}">try again</a>.</p>
              <div class="error-code">Error: Failed to initialize authentication</div>
            </div>
          </body>
        </html>
      `)
    }
  })

  // GET /auth/callback - Handle OAuth callback from WorkOS
  fastify.get<{
    Querystring: { code?: string; state?: string; error?: string }
  }>('/callback', async (request, reply) => {
    const callbackTarget = new URL(redirectUri)
    const forwardedHostRaw = Array.isArray(request.headers['x-forwarded-host'])
      ? request.headers['x-forwarded-host'][0]
      : request.headers['x-forwarded-host']
    const hostRaw = Array.isArray(request.headers.host)
      ? request.headers.host[0]
      : request.headers.host

    const requestHost = stripDefaultPort(
      normalizeHostHeader(
        typeof forwardedHostRaw === 'string' ? forwardedHostRaw : hostRaw,
      ) || '',
    )
    const callbackHost = stripDefaultPort(callbackTarget.host.toLowerCase())

    if (requestHost && requestHost !== callbackHost) {
      const canonicalUrl = new URL(request.raw.url || '/auth/callback', callbackTarget.origin)
      fastify.log.info(
        { requestHost, callbackHost, canonicalUrl: canonicalUrl.toString() },
        'Redirecting OAuth callback to canonical auth host',
      )
      return reply.redirect(canonicalUrl.toString())
    }

    const { code, state, error } = request.query

    if (error) {
      fastify.log.error({ error }, 'OAuth error')
      return reply.status(400).send({ error: 'Authentication failed' })
    }

    if (!code) {
      return reply.status(400).send({ error: 'Missing authorization code' })
    }

    const verifiedStateResult = verifyRequiredState(state, stateSecret)
    if (!verifiedStateResult.ok) {
      const stateError = verifiedStateResult.error
      fastify.log.warn(
        { hasState: typeof state === 'string' && state.length > 0, stateError },
        'Rejected OAuth callback without valid state',
      )
      return reply.status(400).type('text/html').send(
        renderAuthRecoveryPage({
          title: 'Sign-in Expired',
          heading: 'Your sign-in session expired',
          description:
            stateError === 'Missing state parameter'
              ? 'This sign-in did not start from an active Cozea session. Restart sign in from Cozea or reopen the invitation email to continue.'
              : 'This sign-in session is no longer valid. Restart sign in to continue.',
          primaryLabel: 'Continue to sign in',
          primaryHref: '/auth/login?client=web',
        }),
      )
    }

    try {
      const {
        clientType,
        originalState,
        desktopRedirectUri: stateDesktopRedirectUri,
        webRedirectUri: stateWebRedirectUri,
        invitationToken,
      } = verifiedStateResult.state

      // Exchange code for user and tokens
      const authResponse = await fastify.workos.userManagement.authenticateWithCode({
        clientId,
        code,
        invitationToken,
      })

      const { user, accessToken, refreshToken } = authResponse

      // Fetch user's organization memberships
      let normalizedMemberships: WorkOSMembershipRecord[] = []
      let organizations: OrganizationMembership[] = []
      try {
        const membershipsResponse = await fastify.workos.userManagement.listOrganizationMemberships({
          userId: user.id,
        })
        const rawMemberships = membershipsResponse.data as unknown as WorkOSMembershipRecord[]
        const normalizationStats = summarizeMembershipNormalization(rawMemberships)
        if (
          normalizationStats.droppedDuplicateOrganization > 0 ||
          normalizationStats.droppedInactive > 0
        ) {
          fastify.log.warn(
            { userId: user.id, normalizationStats },
            'WorkOS memberships required normalization during auth callback'
          )
        }

        normalizedMemberships = normalizeActiveMemberships(rawMemberships)
        organizations = await enrichOrganizationMembershipsWithIdentity(normalizedMemberships.map((m) => ({
          id: m.id,
          organizationId: m.organizationId,
          organizationName: m.organizationName || "Workspace",
          role: m.role?.slug || 'member',
          status: m.status,
        })))
      } catch (err) {
        fastify.log.warn({ err }, 'Failed to fetch organization memberships')
        // Continue without organizations - user might not have any
      }

      // Sync canonical user/org/membership mirror into Convex at auth bootstrap.
      try {
        const primaryEmail = user.email?.trim()
        if (primaryEmail) {
          await syncUserFromWorkOS({
            workosId: user.id,
            email: primaryEmail,
            firstName: user.firstName || undefined,
            lastName: user.lastName || undefined,
            profileImageUrl: user.profilePictureUrl || undefined,
          })
        }

        for (const membership of normalizedMemberships) {
          await syncOrganizationFromWorkOS({
            workosId: membership.organizationId,
            name: membership.organizationName || 'Workspace',
          })
        }

        await reconcileMembershipSetFromWorkOS({
          workosUserId: user.id,
          memberships: normalizedMemberships.map((membership) => ({
            workosId: membership.id,
            workosOrgId: membership.organizationId,
            role: membership.role?.slug || 'member',
            status: membership.status,
          })),
        })
      } catch (syncErr) {
        fastify.log.warn(
          { err: syncErr, userId: user.id },
          'Failed to sync Convex identity mirror during auth callback'
        )
      }

      const effectiveDesktopRedirectUri =
        stateDesktopRedirectUri && isAllowedDesktopRedirectUri(stateDesktopRedirectUri)
          ? stateDesktopRedirectUri
          : desktopRedirectUri
      const effectiveWebRedirectUri =
        stateWebRedirectUri && isAllowedWebRedirectUri(stateWebRedirectUri, webRedirectUri)
          ? stateWebRedirectUri
          : webRedirectUri

      if (clientType === 'desktop' || clientType === 'vscode' || clientType === 'web') {
        if (clientType === 'desktop' && waitlistEnforcementMode === 'desktop') {
          let waitlistLookupFailed = false
          let waitlistStatus: 'pending' | 'approved' | 'rejected' | null = null
          const userEmail = user.email?.trim().toLowerCase()

          if (!userEmail) {
            waitlistLookupFailed = true
            fastify.log.error(
              { userId: user.id },
              'Authenticated user is missing email; denying desktop login (fail closed)',
            )
          } else {
            try {
              waitlistStatus = await getWaitlistStatus(userEmail)
            } catch (waitlistError) {
              waitlistLookupFailed = true
              fastify.log.error(
                { err: waitlistError, userId: user.id, email: userEmail },
                'Waitlist lookup failed; denying desktop login (fail closed)',
              )
            }
          }

          if (!waitlistLookupFailed && waitlistStatus === null && userEmail) {
            try {
              const fullName = `${user.firstName || ''} ${user.lastName || ''}`.trim()
              const submission = await submitWaitlistEntry({
                email: userEmail,
                name: fullName || undefined,
                roleHint: 'both',
                source: 'desktop_auth',
              })
              waitlistStatus = submission.status
              fastify.log.info(
                { userId: user.id, email: userEmail, waitlistStatus },
                'Auto-created waitlist entry during desktop login',
              )
            } catch (waitlistCreateError) {
              waitlistLookupFailed = true
              fastify.log.error(
                { err: waitlistCreateError, userId: user.id, email: userEmail },
                'Failed to auto-create waitlist entry; denying desktop login (fail closed)',
              )
            }
          }

          if (waitlistLookupFailed || waitlistStatus !== 'approved') {
            const redirectUrl = buildDesktopAuthErrorRedirect(
              effectiveDesktopRedirectUri,
              WAITLIST_ERROR_CODE,
            )
            fastify.log.info(
              { userId: user.id, email: userEmail, waitlistStatus, waitlistLookupFailed },
              'Blocked desktop login due to waitlist status',
            )

            return reply.type('text/html').send(
              renderDesktopBridgePage({
                title: 'Cozea Access Pending',
                badge: 'Access pending',
                heading: "You're on the Cozea waitlist",
                description: WAITLIST_BLOCK_MESSAGE,
                primaryLabel: 'Open Cozea',
                primaryHref: redirectUrl,
                secondaryLabel: 'Try again',
                secondaryHref: '/auth/login?client=desktop',
                hint: 'If Cozea does not open, return to the app and try login again.',
                autoRedirectHref: redirectUrl,
                autoRedirectDelayMs: 240,
                tone: 'pending',
              }),
            )
          }
        }

        // Create one-time token for desktop/vscode/web handoff
        const oneTimeToken = await createOneTimeToken({
          userId: user.id,
          accessToken,
          refreshToken: refreshToken || '',
          user: {
            id: user.id,
            email: user.email,
            firstName: user.firstName,
            lastName: user.lastName,
            profileImageUrl: user.profilePictureUrl,
          },
          organizations,
        })

        // Determine redirect URL based on client type
        let redirectUrl: string
        if (clientType === 'vscode') {
          // VS Code URI handler format
          redirectUrl = `vscode://cozea.workos-authentication/auth/callback?token=${oneTimeToken}&state=${originalState}`
        } else if (clientType === 'desktop') {
          // Desktop app custom protocol
          const url = new URL(effectiveDesktopRedirectUri)
          url.searchParams.set('token', oneTimeToken)
          redirectUrl = url.toString()
        } else {
          // Web app callback (Next.js)
          const url = new URL(effectiveWebRedirectUri)
          url.searchParams.set('token', oneTimeToken)
          if (originalState) {
            url.searchParams.set('state', originalState)
          }
          redirectUrl = url.toString()
        }

        // Web handoff should be a direct HTTP redirect (no intermediate page)
        if (clientType === 'web') {
          return reply.redirect(redirectUrl)
        }

        // Return HTML handoff page for desktop/vscode custom protocol redirects
        return reply.type('text/html').send(
          renderDesktopBridgePage({
            title: 'Opening Cozea...',
            badge: 'Secure login complete',
            heading: 'Opening Cozea',
            description: 'We authenticated your account. If Cozea does not open automatically, use the button below.',
            primaryLabel: 'Open Cozea',
            primaryHref: redirectUrl,
            secondaryLabel: 'Try again',
            secondaryHref: `/auth/login?client=${clientType}`,
            hint: 'macOS may ask permission to open the desktop app from your browser.',
            autoRedirectHref: redirectUrl,
            autoRedirectDelayMs: 80,
            tone: 'default',
          }),
        )
      }

      // For unknown clients, fall back to cookie-based session on gateway domain
      reply.setCookie('session', JSON.stringify({
        userId: user.id,
        accessToken,
        refreshToken,
      }), {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'lax',
        path: '/',
        maxAge: 60 * 60 * 24 * 7, // 7 days
      })

      return reply.redirect('/')
    } catch (err) {
      fastify.log.error({ err }, 'Failed to authenticate')
      return reply.status(500).send({ error: 'Authentication failed' })
    }
  })

  // POST /auth/desktop/exchange - Exchange one-time token for session
  fastify.post<{
    Body: { token: string }
  }>('/desktop/exchange', async (request, reply) => {
    const { token } = request.body

    if (!token) {
      return reply.status(400).send({ error: 'Missing token' })
    }

    const session = await exchangeOneTimeToken(token)

    if (!session) {
      return reply.status(401).send({ error: 'Invalid or expired token' })
    }

    return {
      accessToken: session.accessToken,
      refreshToken: session.refreshToken,
      user: session.user,
      organizations: session.organizations,
    }
  })

  // GET /auth/me - Get current user
  fastify.get('/me', async (request, reply) => {
    const payload = await getTokenPayload(request.headers.authorization)

    if (!payload) {
      return reply.status(401).send({ error: 'Unauthorized' })
    }

    return {
      user: {
        id: payload.sub,
        email: payload.email,
      },
    }
  })

  // POST /auth/waitlist - Submit waitlist request
  fastify.post<{
    Body: { email?: string; name?: string; role?: string; source?: string }
  }>('/waitlist', async (request, reply) => {
    const email = typeof request.body?.email === 'string'
      ? request.body.email.trim().toLowerCase()
      : ''
    const name = typeof request.body?.name === 'string'
      ? request.body.name.trim().slice(0, MAX_WAITLIST_NAME_LENGTH)
      : undefined
    const role = typeof request.body?.role === 'string' ? request.body.role.trim().toLowerCase() : 'both'
    const source = typeof request.body?.source === 'string'
      ? request.body.source.trim().slice(0, MAX_WAITLIST_SOURCE_LENGTH)
      : 'web'

    if (!email || !isValidEmail(email)) {
      return reply.status(400).send({ error: 'Valid email is required' })
    }

    if (!VALID_WAITLIST_ROLES.has(role)) {
      return reply.status(400).send({ error: 'Invalid role value' })
    }

    try {
      const result = await submitWaitlistEntry({
        email,
        name: name || undefined,
        roleHint: role as 'nontechnical' | 'developer' | 'both',
        source: source || 'web',
      })

      return {
        ok: true,
        status: result.status,
        isNew: result.isNew,
      }
    } catch (err) {
      fastify.log.error({ err }, 'Failed to submit waitlist entry')
      return reply.status(500).send({ error: 'Failed to submit waitlist entry' })
    }
  })

  // POST /auth/refresh - Refresh access token
  fastify.post<{
    Body: { refreshToken: string }
  }>('/refresh', async (request, reply) => {
    const { refreshToken } = request.body

    if (!refreshToken) {
      return reply.status(400).send({ error: 'Missing refresh token' })
    }

    try {
      const authResponse = await fastify.workos.userManagement.authenticateWithRefreshToken({
        clientId,
        refreshToken,
      })

      const nextRefreshToken =
        typeof authResponse.refreshToken === 'string' && authResponse.refreshToken.length > 0
          ? authResponse.refreshToken
          : refreshToken

      fastify.log.info({
        refreshTokenPresent: true,
        returnedRefreshToken: typeof authResponse.refreshToken === 'string' && authResponse.refreshToken.length > 0,
      }, 'Refresh token exchange succeeded')

      if (nextRefreshToken === refreshToken && (!authResponse.refreshToken || authResponse.refreshToken.length === 0)) {
        fastify.log.warn(
          { preservedExistingRefreshToken: true },
          'Upstream refresh exchange did not rotate the refresh token; preserving existing token',
        )
      }

      return {
        accessToken: authResponse.accessToken,
        refreshToken: nextRefreshToken,
      }
    } catch (err) {
      const diagnostics = getRefreshErrorDiagnostics(err)
      const statusCode = diagnostics.statusCode

      if (statusCode === 401 || statusCode === 403) {
        fastify.log.warn(
          {
            statusCode,
            requestId: diagnostics.requestId,
            name: diagnostics.name,
            message: diagnostics.message,
            rawData: diagnostics.rawData,
          },
          'Refresh token rejected by upstream auth provider'
        )
        return reply.status(statusCode).send({
          error: 'Failed to refresh token',
          code: 'refresh_token_rejected',
          requestId: diagnostics.requestId,
          details: {
            name: diagnostics.name,
            message: diagnostics.message,
          },
        })
      }

      const retryableStatus = statusCode === 429 ? 429 : 503
      fastify.log.error(
        {
          statusCode,
          requestId: diagnostics.requestId,
          name: diagnostics.name,
          message: diagnostics.message,
          rawData: diagnostics.rawData,
        },
        'Failed to refresh token with retryable upstream error'
      )
      return reply.status(retryableStatus).send({
        error: 'Temporary refresh failure',
        retryable: true,
        requestId: diagnostics.requestId,
        details: {
          name: diagnostics.name,
          message: diagnostics.message,
        },
      })
    }
  })

  // POST /auth/logout - Logout user
  fastify.post('/logout', async (request, reply) => {
    // Blacklist the current token to prevent reuse
    const token = extractToken(request.headers.authorization)
    const tokenPayload = token ? await getTokenPayload(request.headers.authorization) : null
    if (token) {
      // Blacklist for 24 hours (tokens typically expire sooner)
      await blacklistToken(token, 24 * 60 * 60)
    }

    if (tokenPayload?.sid) {
      try {
        await fastify.workos.userManagement.revokeSession({
          sessionId: tokenPayload.sid,
        })
      } catch (err) {
        fastify.log.warn(
          { err, sessionId: tokenPayload.sid },
          'Failed to revoke WorkOS session during logout',
        )
      }
    }

    // Clear cookie for web clients
    reply.clearCookie('session', { path: '/' })

    return { success: true }
  })
}

import type { FastifyPluginAsync, FastifyReply, FastifyRequest } from 'fastify'
import { spawn, spawnSync } from 'node:child_process'
import { existsSync } from 'node:fs'
import { mkdir } from 'node:fs/promises'
import path from 'node:path'

import {
  getAccountEntitlementForProjectForServer,
  getProjectAccessForServer,
  getUserByWorkosId,
  setProjectGitStorageMetricsForServer,
  syncUserFromWorkOS,
} from '../lib/convex.js'
import { getGitRouteAccessLevel } from '../lib/gitRouteAccess.js'
import { ensureBareProjectRepo, getProjectRepoSizeBytes } from '../lib/projectGitRepo.js'
import { getTokenPayload, type TokenPayload } from '../lib/jwt.js'

const GIT_CONTENT_TYPE_PATTERN = /^application\/x-git-(upload|receive)-pack-request$/i
const GIT_ROUTE_PATTERN = /^\/(?<projectId>[a-zA-Z0-9]+)\.git(?<suffix>\/.*)?$/
const DEFAULT_GIT_HTTP_BODY_LIMIT = 256 * 1024 * 1024
const parsedGitHttpBodyLimit = Number.parseInt(process.env.GIT_HTTP_BODY_LIMIT_BYTES ?? '', 10)
const GIT_HTTP_BODY_LIMIT =
  Number.isFinite(parsedGitHttpBodyLimit) && parsedGitHttpBodyLimit > 0
    ? parsedGitHttpBodyLimit
    : DEFAULT_GIT_HTTP_BODY_LIMIT

interface ParsedGitRoutePath {
  projectId: string
  suffix: string
  query: string
}

async function ensureBareRepo(projectId: string): Promise<void> {
  await ensureBareProjectRepo(projectId)
}

async function requireToken(request: FastifyRequest, reply: FastifyReply): Promise<TokenPayload | null> {
  const payload = await getTokenPayload(request.headers.authorization)
  if (!payload) {
    await reply.type('text/plain').status(401).send('Unauthorized')
    return null
  }
  return payload
}

async function resolveOrSyncUser(
  request: FastifyRequest,
  payload: TokenPayload
): Promise<{ _id: string } | null> {
  const existing = await getUserByWorkosId(payload.sub)
  if (existing) return existing

  const workosUser = await request.server.workos.userManagement.getUser(payload.sub)
  const email = workosUser.email || payload.email
  if (!email) {
    return null
  }

  await syncUserFromWorkOS({
    workosId: workosUser.id,
    email,
    firstName: workosUser.firstName || undefined,
    lastName: workosUser.lastName || undefined,
    profileImageUrl: workosUser.profilePictureUrl || undefined,
  })
  return await getUserByWorkosId(payload.sub)
}

async function requireProjectAccess(
  request: FastifyRequest,
  reply: FastifyReply,
  route: ParsedGitRoutePath
): Promise<{ userId: string; workosUserId: string } | null> {
  const payload = await requireToken(request, reply)
  if (!payload) return null

  const user = await resolveOrSyncUser(request, payload)
  if (!user?._id) {
    await reply.type('text/plain').status(401).send('Unable to resolve user context')
    return null
  }

  const access = await getProjectAccessForServer(route.projectId, user._id)
  const requiredAccessLevel = getGitRouteAccessLevel({
    method: request.method,
    suffix: route.suffix,
    query: route.query,
  })
  const hasRequiredAccess =
    requiredAccessLevel === 'write' ? access.canEdit : access.canAccess

  if (!hasRequiredAccess) {
    await reply
      .type('text/plain')
      .status(403)
      .send(
        requiredAccessLevel === 'write'
          ? 'Not authorized to push to this project'
          : 'Not authorized for this project'
      )
    return null
  }

  const entitlement = await getAccountEntitlementForProjectForServer({
    projectId: route.projectId,
    userId: user._id,
  })
  if (!entitlement || !entitlement.canUseSync) {
    const billingBlockedEntitlement =
      entitlement?.status === 'past_due' || entitlement?.status === 'canceled'
    const seatManagedEntitlement =
      !billingBlockedEntitlement &&
      (entitlement?.source === 'trial' || entitlement?.plan === 'startup' || entitlement?.plan === 'enterprise')

    const message =
      billingBlockedEntitlement || !seatManagedEntitlement
        ? entitlement?.status === 'past_due'
          ? 'Your subscription is past due. Update billing to restore cloud access.'
          : entitlement?.status === 'canceled'
            ? 'Your subscription is canceled. Start or renew a plan to restore cloud access.'
            : 'Cloud access requires an active subscription for this account.'
        : (entitlement?.seatCounts?.available ?? 0) > 0
          ? 'You are not assigned to a paid seat for cloud access in this workspace.'
          : 'Cloud access requires an active paid seat assignment in this workspace.'

    await reply.type('text/plain').status(402).send(message)
    return null
  }

  return {
    userId: user._id,
    workosUserId: payload.sub,
  }
}

function parseGitRoutePath(url: string | undefined): { projectId: string; suffix: string; query: string } | null {
  if (!url) return null
  const [pathname, query = ''] = url.split('?', 2)
  const relativePath = pathname.replace(/^\/git/, '')
  const match = relativePath.match(GIT_ROUTE_PATTERN)
  if (!match?.groups?.projectId) return null
  return {
    projectId: match.groups.projectId,
    suffix: match.groups.suffix || '',
    query,
  }
}

function parseBackendHeaders(rawHeaders: string): {
  statusCode: number
  headers: Record<string, string>
} {
  const headers: Record<string, string> = {}
  let statusCode = 200

  for (const line of rawHeaders.split(/\r?\n/)) {
    if (!line.trim()) continue
    const separatorIndex = line.indexOf(':')
    if (separatorIndex === -1) continue
    const name = line.slice(0, separatorIndex).trim()
    const value = line.slice(separatorIndex + 1).trim()
    if (!name) continue
    if (name.toLowerCase() === 'status') {
      const parsed = Number.parseInt(value, 10)
      if (Number.isFinite(parsed)) {
        statusCode = parsed
      }
      continue
    }
    headers[name] = value
  }

  return { statusCode, headers }
}

async function readGitRequestBody(request: FastifyRequest): Promise<Buffer | undefined> {
  if (request.method === 'GET' || request.method === 'HEAD') {
    return undefined
  }
  if (Buffer.isBuffer(request.body)) {
    return request.body
  }
  if (typeof request.body === 'string') {
    return Buffer.from(request.body, 'utf8')
  }
  return undefined
}

export const gitRoutes: FastifyPluginAsync = async (fastify) => {
  async function updateProjectGitStorageMetrics(projectId: string) {
    try {
      const repoBytes = await getProjectRepoSizeBytes(projectId)
      await setProjectGitStorageMetricsForServer({
        projectId,
        repoBytes,
        measuredAt: Date.now(),
      })
    } catch (error) {
      fastify.log.warn(
        { err: error, projectId },
        'Failed to update Git storage metrics after repository write'
      )
    }
  }

  fastify.addContentTypeParser(
    GIT_CONTENT_TYPE_PATTERN,
    { parseAs: 'buffer' },
    (_request, body, done) => {
      done(null, body)
    }
  )

  fastify.route({
    method: ['GET', 'POST'],
    url: '/*',
    bodyLimit: GIT_HTTP_BODY_LIMIT,
    handler: async (request, reply) => {
      const parsed = parseGitRoutePath(request.raw.url)
      if (!parsed) {
        await reply.code(404).send({ error: 'Git repository not found' })
        return
      }

      const access = await requireProjectAccess(request, reply, parsed)
      if (!access) return

      await ensureBareRepo(parsed.projectId)

      const requestBody = await readGitRequestBody(request)
      const repoDir = await ensureBareProjectRepo(parsed.projectId)
      const projectRoot = path.dirname(repoDir)
      const pathInfo = `/${parsed.projectId}.git${parsed.suffix}`

      const backend = spawn('git', ['http-backend'], {
        cwd: projectRoot,
        env: {
          ...process.env,
          GIT_PROJECT_ROOT: projectRoot,
          GIT_HTTP_EXPORT_ALL: '1',
          PATH_INFO: pathInfo,
          QUERY_STRING: parsed.query,
          REQUEST_METHOD: request.method,
          CONTENT_TYPE:
            typeof request.headers['content-type'] === 'string'
              ? request.headers['content-type']
              : '',
          CONTENT_LENGTH: requestBody ? String(requestBody.length) : '0',
          REMOTE_USER: access.userId,
          REMOTE_ADDR: request.ip,
        },
        stdio: ['pipe', 'pipe', 'pipe'],
      })

      const stderrChunks: Buffer[] = []
      let headerBuffer = Buffer.alloc(0)
      let responseStarted = false

      reply.hijack()

      backend.stdout.on('data', (chunk: Buffer) => {
        if (responseStarted) {
          reply.raw.write(chunk)
          return
        }

        headerBuffer = Buffer.concat([headerBuffer, chunk])
        const separatorIndex = headerBuffer.indexOf('\r\n\r\n')
        if (separatorIndex === -1) {
          return
        }

        const rawHeaders = headerBuffer.subarray(0, separatorIndex).toString('utf8')
        const { statusCode, headers } = parseBackendHeaders(rawHeaders)
        reply.raw.writeHead(statusCode, headers)
        const remainder = headerBuffer.subarray(separatorIndex + 4)
        if (remainder.length > 0) {
          reply.raw.write(remainder)
        }
        responseStarted = true
      })

      backend.stderr.on('data', (chunk: Buffer) => {
        stderrChunks.push(chunk)
      })

      backend.on('close', (code) => {
        if (!responseStarted) {
          const message = Buffer.concat(stderrChunks).toString('utf8').trim()
          if (!reply.raw.headersSent) {
            reply.raw.writeHead(code === 0 ? 200 : 500, {
              'content-type': 'text/plain; charset=utf-8',
            })
          }
          if (message) {
            reply.raw.write(message)
          }
        }
        reply.raw.end()

        if (
          code === 0 &&
          request.method === 'POST' &&
          parsed.suffix === '/git-receive-pack'
        ) {
          void updateProjectGitStorageMetrics(parsed.projectId)
        }
      })

      backend.on('error', (error) => {
        request.log.error({ err: error, projectId: parsed.projectId }, 'Failed to start git http-backend')
        if (!reply.raw.headersSent) {
          reply.raw.writeHead(500, { 'content-type': 'text/plain; charset=utf-8' })
        }
        reply.raw.end('Failed to start git backend')
      })

      if (requestBody && requestBody.length > 0) {
        backend.stdin.write(requestBody)
      }
      backend.stdin.end()
    },
  })
}

