function normalizeString(value: unknown): string | null {
  if (typeof value !== 'string') return null
  const trimmed = value.trim()
  return trimmed.length > 0 ? trimmed : null
}

function normalizeProjectId(value: unknown): string | null {
  const projectId = normalizeString(value)
  if (!projectId) return null
  if (projectId.length > 200) return null
  return projectId
}

function normalizeWorkspaceId(value: unknown): string | null {
  const workspaceId = normalizeString(value)
  if (!workspaceId) return null
  if (workspaceId.length > 200) return null
  return workspaceId
}

function normalizeProjectSlug(value: unknown): string | null {
  const slug = normalizeString(value)
  if (!slug) return null
  return slug.replace(/[^a-zA-Z0-9-_]/g, '').slice(0, 80) || null
}

function parseBoolean(value: unknown, fallback = false): boolean {
  if (typeof value === 'boolean') return value
  if (typeof value !== 'string') return fallback
  const normalized = value.trim().toLowerCase()
  if (['1', 'true', 'yes', 'on'].includes(normalized)) return true
  if (['0', 'false', 'no', 'off'].includes(normalized)) return false
  return fallback
}

function parseInteger(value: string | undefined, fallback: number): number {
  if (!value) return fallback
  const parsed = Number.parseInt(value, 10)
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback
}

function firstMeaningfulLine(value: string): string | null {
  for (const rawLine of value.split(/\r?\n/)) {
    const line = rawLine.trim()
    if (line.length > 0) {
      return line
    }
  }
  return null
}

function getRequestOrigin(request: FastifyRequest): string | null {
  const forwardedProto = normalizeString(request.headers['x-forwarded-proto'])
  const forwardedHost = normalizeString(request.headers['x-forwarded-host'])
  const host = forwardedHost || normalizeString(request.headers.host)
  const proto = forwardedProto ? forwardedProto.split(',')[0]?.trim() : request.protocol

  if (!host || !proto) return null
  return `${proto}://${host}`
}

function buildBridgeScriptUrl(request: FastifyRequest): string | null {
  const envOverride = normalizeString(process.env.PREVIEW_BRIDGE_SCRIPT_URL)
  if (envOverride) {
    try {
      return new URL(envOverride).toString()
    } catch {
      return null
    }
  }

  const origin = getRequestOrigin(request)
  if (!origin) return null
  return `${origin}/runtime/workspaces/bridge/client.js`
}

function buildPreviewBaseUrl(request: FastifyRequest, workspaceId: string, previewToken: string): string | null {
  const origin = getRequestOrigin(request)
  if (!origin) return null
  return `${origin}/runtime/workspaces/${encodeURIComponent(workspaceId)}/preview/${encodeURIComponent(previewToken)}`
}

function resolveWorkspaceRoot(): string {
  const configured = normalizeString(process.env.WEB_VM_WORKSPACE_ROOT)
  if (configured) return configured
  return path.join(os.tmpdir(), 'cozea-web-vm-workspaces')
}

function getWorkspaceDir(projectId: string): string {
  const safeProjectId = projectId.replace(/[^a-zA-Z0-9._-]/g, '_')
  return path.join(resolveWorkspaceRoot(), safeProjectId)
}

function normalizeWorkspaceFilePath(rawPath: string): string | null {
  const trimmed = rawPath.trim()
  if (!trimmed) return null

  const normalized = path.posix.normalize(trimmed.replace(/\\/g, '/').replace(/^\/+/, ''))
  if (!normalized || normalized === '.' || normalized === '..') return null
  if (normalized.startsWith('../') || normalized.includes('\0')) return null
  return normalized
}

function toAbsoluteWorkspacePath(workspaceDir: string, filePath: string): string | null {
  const normalizedPath = normalizeWorkspaceFilePath(filePath)
  if (!normalizedPath) return null

  const absolutePath = path.join(workspaceDir, normalizedPath.split('/').join(path.sep))
  const relative = path.relative(workspaceDir, absolutePath)
  if (relative.startsWith('..') || path.isAbsolute(relative)) return null

  return absolutePath
}

function pathBasename(posixPath: string): string {
  const normalized = path.posix.normalize(posixPath)
  const base = normalized.split('/').pop()
  return base && base.length > 0 ? base : normalized
}

async function statWorkspacePath(absolutePath: string): Promise<import('node:fs').Stats | null> {
  try {
    return await stat(absolutePath)
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
      return null
    }
    throw error
  }
}

function isLikelyTextBuffer(buffer: Buffer): boolean {
  if (buffer.length === 0) return true
  const sampleLength = Math.min(buffer.length, 2048)
  let suspicious = 0
  for (let index = 0; index < sampleLength; index += 1) {
    const value = buffer[index]
    if (value === 0) return false
    if ((value >= 7 && value <= 14) || value === 27) continue
    if (value >= 32 || value === 9 || value === 10 || value === 13) continue
    suspicious += 1
  }
  return suspicious / sampleLength < 0.1
}

function appendCapped(buffer: string, chunk: string, maxBytes: number): { next: string; truncated: boolean } {
  if (!chunk) return { next: buffer, truncated: false }
  const currentBytes = Buffer.byteLength(buffer, 'utf8')
  if (currentBytes >= maxBytes) {
    return { next: buffer, truncated: true }
  }

  const chunkBytes = Buffer.byteLength(chunk, 'utf8')
  if (currentBytes + chunkBytes <= maxBytes) {
    return { next: buffer + chunk, truncated: false }
  }

  const budget = Math.max(0, maxBytes - currentBytes)
  if (budget === 0) {
    return { next: buffer, truncated: true }
  }

  const cappedChunk = Buffer.from(chunk, 'utf8').subarray(0, budget).toString('utf8')
  return { next: buffer + cappedChunk, truncated: true }
}

async function walkWorkspaceEntries(args: {
  workspaceDir: string
  basePath: string
  recursive: boolean
}): Promise<WorkspaceFileEntry[]> {
  const normalizedBase = args.basePath ? normalizeWorkspaceFilePath(args.basePath) : ''
  if (args.basePath && !normalizedBase) {
    throw new Error('Invalid base path.')
  }

  const startAbsolute = normalizedBase
    ? toAbsoluteWorkspacePath(args.workspaceDir, normalizedBase)
    : args.workspaceDir

  if (!startAbsolute) {
    throw new Error('Invalid base path.')
  }

  const startStats = await statWorkspacePath(startAbsolute)
  if (!startStats) return []

  const entries: WorkspaceFileEntry[] = []

  if (startStats.isFile()) {
    if (!normalizedBase) return []
    entries.push({
      path: normalizedBase,
      name: pathBasename(normalizedBase),
      type: 'file',
      size: startStats.size,
      mtimeMs: startStats.mtimeMs,
    })
    return entries
  }

  if (!startStats.isDirectory()) return []

  const visitDirectory = async (absoluteDir: string, relativeDir: string): Promise<void> => {
    const children = await readdir(absoluteDir, { withFileTypes: true })
    children.sort((a, b) => a.name.localeCompare(b.name))

    for (const child of children) {
      if (child.name === '.DS_Store') continue
      const relativePath = relativeDir ? `${relativeDir}/${child.name}` : child.name
      const normalizedPath = normalizeWorkspaceFilePath(relativePath)
      if (!normalizedPath) continue

      const absolutePath = toAbsoluteWorkspacePath(args.workspaceDir, normalizedPath)
      if (!absolutePath) continue

      const childStats = await statWorkspacePath(absolutePath)
      if (!childStats) continue

      if (childStats.isDirectory()) {
        entries.push({
          path: normalizedPath,
          name: child.name,
          type: 'directory',
          size: childStats.size,
          mtimeMs: childStats.mtimeMs,
        })
        if (args.recursive) {
          await visitDirectory(absolutePath, normalizedPath)
        }
        continue
      }

      if (!childStats.isFile()) continue
      entries.push({
        path: normalizedPath,
        name: child.name,
        type: 'file',
        size: childStats.size,
        mtimeMs: childStats.mtimeMs,
      })
    }
  }

  await visitDirectory(startAbsolute, normalizedBase || '')
  return entries
}

async function copyWorkspaceEntry(sourcePath: string, targetPath: string): Promise<void> {
  const sourceStats = await stat(sourcePath)
  if (sourceStats.isDirectory()) {
    await mkdir(targetPath, { recursive: true })
    const children = await readdir(sourcePath, { withFileTypes: true })
    for (const child of children) {
      const fromChild = path.join(sourcePath, child.name)
      const toChild = path.join(targetPath, child.name)
      await copyWorkspaceEntry(fromChild, toChild)
    }
    return
  }

  if (!sourceStats.isFile()) {
    return
  }

  await mkdir(path.dirname(targetPath), { recursive: true })
  await copyFile(sourcePath, targetPath)
}

async function executeWorkspaceCommand(args: {
  command: string
  cwd: string
  timeoutMs: number
}): Promise<{
  stdout: string
  stderr: string
  exitCode: number | null
  signal: NodeJS.Signals | null
  truncated: boolean
  timedOut: boolean
  durationMs: number
}> {
  const startedAt = Date.now()
  const child = spawnCommandProcess(args.command, args.cwd)

  return await new Promise((resolve, reject) => {
    let stdout = ''
    let stderr = ''
    let truncated = false
    let timedOut = false
    let settled = false

    const timeout = setTimeout(() => {
      timedOut = true
      try {
        child.kill('SIGTERM')
      } catch {
        // no-op
      }
      setTimeout(() => {
        try {
          if (!child.killed) {
            child.kill('SIGKILL')
          }
        } catch {
          // no-op
        }
      }, 1500).unref()
    }, Math.max(1000, args.timeoutMs))
    timeout.unref()

    child.stdout.on('data', (chunk: Buffer | string) => {
      const appended = appendCapped(stdout, String(chunk), MAX_EXEC_CAPTURE_BYTES)
      stdout = appended.next
      truncated = truncated || appended.truncated
    })

    child.stderr.on('data', (chunk: Buffer | string) => {
      const appended = appendCapped(stderr, String(chunk), MAX_EXEC_CAPTURE_BYTES)
      stderr = appended.next
      truncated = truncated || appended.truncated
    })

    child.on('error', (error: Error) => {
      if (settled) return
      settled = true
      clearTimeout(timeout)
      reject(error)
    })

    child.on('close', (code, signal) => {
      if (settled) return
      settled = true
      clearTimeout(timeout)
      resolve({
        stdout,
        stderr,
        exitCode: code,
        signal,
        truncated,
        timedOut,
        durationMs: Math.max(0, Date.now() - startedAt),
      })
    })
  })
}

function resolveShellCommand(): { command: string; args: string[]; label: string } {
  const configured = normalizeString(process.env.WEB_VM_TERMINAL_SHELL)
  if (configured) {
    const tokens = configured.split(/\s+/).filter(Boolean)
    const command = tokens[0]
    if (command) {
      return {
        command,
        args: tokens.slice(1),
        label: path.basename(command),
      }
    }
  }

  if (process.platform === 'win32') {
    return {
      command: 'powershell.exe',
      args: ['-NoLogo'],
      label: 'powershell',
    }
  }

  if (existsSync('/bin/zsh')) {
    return {
      command: '/bin/zsh',
      args: ['-l'],
      label: 'zsh',
    }
  }

  if (existsSync('/bin/bash')) {
    return {
      command: '/bin/bash',
      args: ['-l'],
      label: 'bash',
    }
  }

  return {
    command: '/bin/sh',
    args: [],
    label: 'sh',
  }
}

function escapeShellToken(token: string): string {
  return `'${token.replace(/'/g, `'\\''`)}'`
}

function resolveScriptBinary(): string | null {
  if (process.platform === 'win32') {
    return null
  }

  const candidates = ['/usr/bin/script', '/bin/script']
  for (const candidate of candidates) {
    if (existsSync(candidate)) {
      return candidate
    }
  }

  return null
}

function toShellLaunchCommand(command: string, args: string[]): string {
  return [command, ...args].map((token) => escapeShellToken(token)).join(' ')
}

function resolvePreviewBasePath(runtime: WorkspaceRuntime): string {
  return `/runtime/workspaces/${encodeURIComponent(runtime.workspaceId)}/preview/${encodeURIComponent(runtime.previewToken)}/`
}

function applyDevServerTemplate(template: string, runtime: WorkspaceRuntime, port: number): string {
  return template
    .replace(/\{port\}/g, String(port))
    .replace(/\{host\}/g, '0.0.0.0')
    .replace(/\{basePath\}/g, resolvePreviewBasePath(runtime))
    .replace(/\{workspaceId\}/g, runtime.workspaceId)
    .replace(/\{previewToken\}/g, runtime.previewToken)
}

function commandExists(command: string): boolean {
  const result = spawnSync('sh', ['-lc', `command -v ${escapeShellToken(command)} >/dev/null 2>&1`], {
    stdio: 'ignore',
  })
  return result.status === 0
}

interface InstallCommand {
  command: string
  label: string
  fallback?: {
    command: string
    label: string
  }
}

async function resolveDependencyInstallCommand(workspaceDir: string): Promise<InstallCommand> {
  const hasPnpmLock = await statWorkspacePath(path.join(workspaceDir, 'pnpm-lock.yaml'))
  if (hasPnpmLock?.isFile() && commandExists('pnpm')) {
    return {
      command: 'pnpm install --frozen-lockfile',
      label: 'pnpm install',
      fallback: {
        command: 'pnpm install',
        label: 'pnpm install',
      },
    }
  }

  const hasYarnLock = await statWorkspacePath(path.join(workspaceDir, 'yarn.lock'))
  if (hasYarnLock?.isFile() && commandExists('yarn')) {
    return {
      command: 'yarn install --immutable',
      label: 'yarn install',
      fallback: {
        command: 'yarn install',
        label: 'yarn install',
      },
    }
  }

  const hasPackageLock = await statWorkspacePath(path.join(workspaceDir, 'package-lock.json'))
  if (hasPackageLock?.isFile()) {
    return {
      command: 'npm ci --no-audit --no-fund',
      label: 'npm ci',
      fallback: {
        command: 'npm install --no-audit --no-fund',
        label: 'npm install',
      },
    }
  }

  return {
    command: 'npm install --no-audit --no-fund',
    label: 'npm install',
  }
}

async function readWorkspacePackageJson(workspaceDir: string): Promise<Record<string, unknown> | null> {
  const packageJsonPath = path.join(workspaceDir, 'package.json')
  let source = ''
  try {
    source = await readFile(packageJsonPath, 'utf8')
  } catch {
    return null
  }

  let parsed: unknown
  try {
    parsed = JSON.parse(source)
  } catch {
    return null
  }

  if (!parsed || typeof parsed !== 'object') return null
  return parsed as Record<string, unknown>
}

function getWorkspaceScript(packageJson: Record<string, unknown>, scriptName: 'dev' | 'start'): string | null {
  if (!packageJson.scripts || typeof packageJson.scripts !== 'object') {
    return null
  }

  const scripts = packageJson.scripts as Record<string, unknown>
  const value = scripts[scriptName]
  if (typeof value !== 'string') {
    return null
  }

  const trimmed = value.trim()
  return trimmed.length > 0 ? trimmed : null
}

function isViteScript(script: string | null): boolean {
  if (!script) return false
  const normalized = script.toLowerCase()
  return /\bvite\b/.test(normalized) && !/\bvitest\b/.test(normalized)
}

interface WorkspaceDevCommandConfig {
  scriptName: 'dev' | 'start'
  prefersViteBase: boolean
}

async function resolveWorkspaceDevCommandConfig(workspaceDir: string): Promise<WorkspaceDevCommandConfig> {
  const packageJson = await readWorkspacePackageJson(workspaceDir)
  if (!packageJson) {
    throw new Error('Workspace is missing package.json. Preview requires cloud files for a runnable web app.')
  }

  const devScript = getWorkspaceScript(packageJson, 'dev')
  if (devScript) {
    return {
      scriptName: 'dev',
      prefersViteBase: isViteScript(devScript),
    }
  }

  const startScript = getWorkspaceScript(packageJson, 'start')
  if (startScript) {
    return {
      scriptName: 'start',
      prefersViteBase: false,
    }
  }

  throw new Error('Workspace package.json has no "dev" or "start" script for preview.')
}

function resolveDevServerCommand(
  runtime: WorkspaceRuntime,
  port: number,
  config: WorkspaceDevCommandConfig
): string {
  const configuredTemplate = normalizeString(process.env.WEB_VM_DEV_SERVER_COMMAND)
  if (configuredTemplate) {
    return applyDevServerTemplate(configuredTemplate, runtime, port)
  }

  if (config.prefersViteBase) {
    return applyDevServerTemplate(DEFAULT_VITE_DEVSERVER_COMMAND, runtime, port)
  }

  const template = config.scriptName === 'start' ? DEFAULT_START_DEVSERVER_COMMAND : DEFAULT_DEVSERVER_COMMAND
  return applyDevServerTemplate(template, runtime, port)
}

function isTerminalProcessRunning(session: TerminalSession): boolean {
  return Boolean(session.child && !session.child.killed && (session.status === 'running' || session.status === 'starting'))
}

function isDevServerRunning(session: DevServerSession): boolean {
  return session.status === 'running' || session.status === 'starting'
}

async function waitForTerminalReady(runtime: WorkspaceRuntime): Promise<boolean> {
  const timeoutMs = parseInteger(process.env.WEB_VM_TERMINAL_READY_TIMEOUT_MS, DEFAULT_TERMINAL_READY_TIMEOUT_MS)
  const stableWindowMs = parseInteger(process.env.WEB_VM_TERMINAL_STABLE_WINDOW_MS, DEFAULT_TERMINAL_STABLE_WINDOW_MS)
  const startedAt = Date.now()
  let stableSince: number | null = null

  while (Date.now() - startedAt <= timeoutMs) {
    if (isTerminalProcessRunning(runtime.terminal)) {
      if (stableSince === null) {
        stableSince = Date.now()
      }
      if (Date.now() - stableSince >= stableWindowMs) {
        return true
      }
    } else {
      stableSince = null
      if (runtime.terminal.status === 'error' || runtime.terminal.status === 'stopped') {
        return false
      }
    }


    await new Promise((resolve) => setTimeout(resolve, TERMINAL_READY_POLL_INTERVAL_MS))
  }

  return isTerminalProcessRunning(runtime.terminal)
}

function writeSse(response: ServerResponse, event: TerminalStreamEvent): boolean {
  if (response.destroyed || response.writableEnded) return false

  try {
    response.write(`event: terminal\\ndata: ${JSON.stringify(event)}\\n\\n`)
    return true
  } catch {
    return false
  }
}

function emitTerminalEvent(
  runtime: WorkspaceRuntime,
  event: Omit<TerminalStreamEvent, 'seq' | 'timestamp' | 'sessionId' | 'workspaceId' | 'projectId'>
): void {
  const session = runtime.terminal
  const envelope: TerminalStreamEvent = {
    ...event,
    seq: ++session.nextSeq,
    timestamp: Date.now(),
    sessionId: session.sessionId,
    workspaceId: runtime.workspaceId,
    projectId: runtime.projectId,
  }

  session.updatedAt = envelope.timestamp
  runtime.updatedAt = envelope.timestamp

  session.backlog.push(envelope)
  if (session.backlog.length > MAX_BACKLOG_EVENTS) {
    session.backlog.splice(0, session.backlog.length - MAX_BACKLOG_EVENTS)
  }

  for (const [subscriberId, response] of session.subscribers) {
    const sent = writeSse(response, envelope)
    if (!sent) {
      session.subscribers.delete(subscriberId)
      const heartbeat = subscriberHeartbeats.get(subscriberId)
      if (heartbeat) {
        clearInterval(heartbeat)
        subscriberHeartbeats.delete(subscriberId)
      }
    }
  }
}

function unregisterSubscriber(runtime: WorkspaceRuntime, subscriberId: string): void {
  const session = runtime.terminal
  const response = session.subscribers.get(subscriberId)
  if (response) {
    try {
      response.end()
    } catch {
      // no-op
    }
  }

  session.subscribers.delete(subscriberId)

  const heartbeat = subscriberHeartbeats.get(subscriberId)
  if (heartbeat) {
    clearInterval(heartbeat)
    subscriberHeartbeats.delete(subscriberId)
  }
}

function closeTerminalSubscribers(runtime: WorkspaceRuntime): void {
  for (const subscriberId of runtime.terminal.subscribers.keys()) {
    unregisterSubscriber(runtime, subscriberId)
  }
}

function spawnCommandProcess(command: string, cwd: string): ChildProcessWithoutNullStreams {
  if (process.platform === 'win32') {
    return spawn('powershell.exe', ['-NoLogo', '-Command', command], {
      cwd,
      env: {
        ...process.env,
        TERM: 'xterm-256color',
        COLORTERM: 'truecolor',
        FORCE_COLOR: '1',
      },
      stdio: 'pipe',
    })
  }

  if (existsSync('/bin/bash')) {
    return spawn('/bin/bash', ['-lc', command], {
      cwd,
      env: {
        ...process.env,
        TERM: 'xterm-256color',
        COLORTERM: 'truecolor',
        FORCE_COLOR: '1',
      },
      stdio: 'pipe',
    })
  }

  return spawn('/bin/sh', ['-c', command], {
    cwd,
    env: {
      ...process.env,
      TERM: 'xterm-256color',
      COLORTERM: 'truecolor',
      FORCE_COLOR: '1',
    },
    stdio: 'pipe',
  })
}

function attachTerminalProcess(runtime: WorkspaceRuntime, child: ChildProcessWithoutNullStreams, shellLabel: string): void {
  const terminal = runtime.terminal
  terminal.child = child
  terminal.shellLabel = shellLabel
  terminal.status = 'starting'
  terminal.updatedAt = Date.now()
  terminal.lastInputAt = Date.now()

  emitTerminalEvent(runtime, {
    type: 'session',
    status: 'starting',
    data: `Terminal spawned (${shellLabel}) in ${runtime.workspaceDir}`,
  })

  child.stdout.on('data', (chunk: Buffer | string) => {
    if (terminal.child !== child) return
    emitTerminalEvent(runtime, {
      type: 'stdout',
      data: String(chunk),
    })
  })

  child.stderr.on('data', (chunk: Buffer | string) => {
    if (terminal.child !== child) return
    emitTerminalEvent(runtime, {
      type: 'stderr',
      data: String(chunk),
    })
  })

  child.on('spawn', () => {
    if (terminal.child !== child) return
    terminal.status = 'running'
    terminal.updatedAt = Date.now()
    emitTerminalEvent(runtime, {
      type: 'session',
      status: 'running',
      data: 'Terminal session started.',
    })
  })

  child.on('error', (error: Error) => {
    if (terminal.child !== child) return
    terminal.status = 'error'
    terminal.updatedAt = Date.now()
    if (runtime.devServer.status === 'running' || runtime.devServer.status === 'starting') {
      runtime.devServer.status = 'error'
      runtime.devServer.lastError = 'Terminal process failed while preview server was running.'
      runtime.devServer.updatedAt = Date.now()
      runtime.updatedAt = Date.now()
    }
    emitTerminalEvent(runtime, {
      type: 'error',
      status: 'error',
      data: error.message || 'Terminal process failed',
    })
  })

  child.on('exit', (code, signal) => {
    if (terminal.child !== child) return
    terminal.child = null
    terminal.status = 'stopped'
    terminal.updatedAt = Date.now()
    if (runtime.devServer.status === 'running' || runtime.devServer.status === 'starting') {
      runtime.devServer.status = 'stopped'
      runtime.devServer.updatedAt = Date.now()
      runtime.updatedAt = Date.now()
      emitTerminalEvent(runtime, {
        type: 'meta',
        data: 'Preview dev server stopped because terminal session exited.',
      })
    }
    emitTerminalEvent(runtime, {
      type: 'exit',
      status: 'stopped',
      code,
      signal,
      data: 'Terminal process exited.',
    })
  })
}

function stopTerminalProcess(runtime: WorkspaceRuntime, reason?: string): void {
  const terminal = runtime.terminal
  const child = terminal.child

  if (reason) {
    emitTerminalEvent(runtime, {
      type: 'meta',
      data: reason,
    })
  }

  if (!child) {
    terminal.status = 'stopped'
    terminal.updatedAt = Date.now()
    runtime.updatedAt = Date.now()
    return
  }

  if (!child.killed) {
    try {
      child.kill('SIGTERM')
    } catch {
      // no-op
    }

    setTimeout(() => {
      if (!child.killed) {
        try {
          child.kill('SIGKILL')
        } catch {
          // no-op
        }
      }
    }, 1800).unref()
  }
}

function stopDevServerProcess(runtime: WorkspaceRuntime, reason?: string): void {
  if (reason) {
    emitTerminalEvent(runtime, {
      type: 'meta',
      data: reason,
    })
  }

  const terminalChild = runtime.terminal.child
  if (
    terminalChild
    && !terminalChild.killed
    && runtime.terminal.status === 'running'
    && (runtime.devServer.status === 'running' || runtime.devServer.status === 'starting')
  ) {
    try {
      // Send Ctrl+C to stop the foreground dev server command inside the shared terminal shell.
      terminalChild.stdin.write('\u0003')
    } catch {
      // no-op
    }
  }

  runtime.devServer.status = 'stopped'
  runtime.devServer.updatedAt = Date.now()
  runtime.updatedAt = Date.now()
}

function stablePortOffset(projectId: string): number {
  const digest = createHash('sha1').update(projectId).digest()
  return digest.readUInt16BE(0)
}

function getDevServerPortBounds(projectId: string): { start: number; end: number } {
  const base = parseInteger(process.env.WEB_VM_DEV_SERVER_PORT_BASE, DEFAULT_PORT_BASE)
  const span = parseInteger(process.env.WEB_VM_DEV_SERVER_PORT_RANGE, DEFAULT_PORT_RANGE)
  const offset = stablePortOffset(projectId) % Math.max(10, span)
  const start = base + offset
  return {
    start,
    end: start + Math.max(20, span),
  }
}

async function canBindPort(port: number): Promise<boolean> {
  return new Promise((resolve) => {
    const server = net.createServer()
    server.once('error', () => resolve(false))
    server.once('listening', () => {
      server.close(() => resolve(true))
    })
    server.listen(port, '127.0.0.1')
  })
}

async function findAvailablePort(projectId: string): Promise<number> {
  const bounds = getDevServerPortBounds(projectId)
  for (let port = bounds.start; port <= bounds.end; port += 1) {

    const available = await canBindPort(port)
    if (available) return port
  }

  throw new Error('No available dev-server port found')
}

async function canConnectToPort(host: string, port: number, timeoutMs = DEVSERVER_CONNECT_PROBE_TIMEOUT_MS): Promise<boolean> {
  return await new Promise((resolve) => {
    const socket = net.createConnection({
      host,
      port,
    })
    let settled = false

    const finish = (result: boolean) => {
      if (settled) return
      settled = true
      socket.removeAllListeners()
      try {
        socket.destroy()
      } catch {
        // no-op
      }
      resolve(result)
    }

    socket.once('connect', () => finish(true))
    socket.once('error', () => finish(false))
    socket.setTimeout(timeoutMs, () => finish(false))
  })
}

async function probeHttpEndpoint(url: string, timeoutMs = DEVSERVER_HTTP_PROBE_TIMEOUT_MS): Promise<boolean> {
  const controller = new AbortController()
  const timeout = setTimeout(() => {
    controller.abort()
  }, timeoutMs)
  timeout.unref()

  try {
    const response = await fetch(url, {
      method: 'GET',
      redirect: 'manual',
      signal: controller.signal,
    })
    return response.status >= 100
  } catch {
    return false
  } finally {
    clearTimeout(timeout)
  }
}

async function waitForDevServerWithin(port: number, timeoutMs: number): Promise<boolean> {
  const start = Date.now()
  const probeUrls = [
    `http://127.0.0.1:${port}/`,
    `http://localhost:${port}/`,
    `http://[::1]:${port}/`,
  ]

  while (Date.now() - start <= timeoutMs) {
    // Some stacks can take a while to return HTTP, but an open TCP port still
    // means the preview process is up and proxyable.

    const connected = (await canConnectToPort('127.0.0.1', port))

      || (await canConnectToPort('localhost', port))

      || (await canConnectToPort('::1', port))

    if (connected) {
      return true
    }

    for (const url of probeUrls) {

      const ok = await probeHttpEndpoint(url)
      if (ok) {
        return true
      }
    }


    await new Promise((resolve) => setTimeout(resolve, 500))
  }

  return false
}

async function waitForDevServer(port: number): Promise<void> {
  const timeoutMs = parseInteger(process.env.WEB_VM_DEVSERVER_READY_TIMEOUT_MS, DEFAULT_DEVSERVER_READY_TIMEOUT_MS)
  const ready = await waitForDevServerWithin(port, timeoutMs)
  if (ready) return

  throw new Error(`Dev server did not become ready on port ${port}`)
}

async function waitForStartingDevServerGrace(runtime: WorkspaceRuntime): Promise<void> {
  if (runtime.devServer.status !== 'starting') return
  const port = runtime.devServer.port
  if (!port) return

  const graceMs = parseInteger(process.env.WEB_VM_PREVIEW_START_GRACE_MS, DEFAULT_PREVIEW_START_GRACE_MS)
  const ready = await waitForDevServerWithin(port, graceMs)
  if (!ready) return

  runtime.devServer.status = 'running'
  runtime.devServer.lastError = null
  runtime.devServer.updatedAt = Date.now()
  runtime.updatedAt = Date.now()
}

async function isRuntimeDevServerReachable(runtime: WorkspaceRuntime): Promise<boolean> {
  const port = runtime.devServer.port
  if (!port) return false

  return (
    (await canConnectToPort('127.0.0.1', port))
    || (await canConnectToPort('localhost', port))
    || (await canConnectToPort('::1', port))
  )
}

async function refreshDevServerStatus(runtime: WorkspaceRuntime): Promise<void> {
  if (runtime.devServer.status !== 'running') {
    return
  }

  const reachable = await isRuntimeDevServerReachable(runtime)
  if (reachable) return

  runtime.devServer.status = 'stopped'
  runtime.devServer.lastError = 'Preview dev server is no longer reachable.'
  runtime.devServer.updatedAt = Date.now()
  runtime.updatedAt = Date.now()
  emitTerminalEvent(runtime, {
    type: 'meta',
    data: 'Preview dev server is no longer reachable. Marked as stopped.',
  })
}

async function hydrateWorkspace(projectId: string, workspaceDir: string): Promise<WorkspaceHydrationResult> {
  await rm(workspaceDir, { recursive: true, force: true })
  const projectInfo = await getProjectSyncInfoForServer(projectId)
  const gitHydration = await hydrateWorkspaceFromProjectGitRepo({
    projectId,
    workspaceDir,
  })

  return {
    written: gitHydration.written,
    skipped: 0,
    canonicalWritten: gitHydration.written,
    canonicalSource: gitHydration.source === 'canonical' ? 'git' : 'none',
    canonicalError: gitHydration.error ?? null,
  }
}

async function ensureWorkspaceDependencies(runtime: WorkspaceRuntime): Promise<void> {
  const packageJsonPath = path.join(runtime.workspaceDir, 'package.json')
  const packageJsonStats = await statWorkspacePath(packageJsonPath)
  if (!packageJsonStats?.isFile()) {
    return
  }

  const nodeModulesPath = path.join(runtime.workspaceDir, 'node_modules')
  const nodeModulesStats = await statWorkspacePath(nodeModulesPath)
  if (nodeModulesStats?.isDirectory()) {
    return
  }

  const existingLock = dependencyInstallLocks.get(runtime.workspaceId)
  if (existingLock) {
    await existingLock
    return
  }

  const lock = (async () => {
    const install = await resolveDependencyInstallCommand(runtime.workspaceDir)
    const installTimeoutMs = parseInteger(
      process.env.WEB_VM_DEPENDENCY_INSTALL_TIMEOUT_MS,
      DEFAULT_DEPENDENCY_INSTALL_TIMEOUT_MS
    )

    const runInstallCommand = async (attempt: { command: string; label: string }) => {
      emitTerminalEvent(runtime, {
        type: 'meta',
        data: `Installing dependencies via ${attempt.label}...`,
      })

      const result = await executeWorkspaceCommand({
        command: attempt.command,
        cwd: runtime.workspaceDir,
        timeoutMs: installTimeoutMs,
      })

      if (result.stdout) {
        emitTerminalEvent(runtime, {
          type: 'stdout',
          data: result.stdout,
        })
      }

      if (result.stderr) {
        emitTerminalEvent(runtime, {
          type: 'stderr',
          data: result.stderr,
        })
      }

      return result
    }

    let result = await runInstallCommand(install)

    if (result.timedOut) {
      throw new Error(`Dependency install timed out after ${installTimeoutMs}ms`)
    }

    if (result.exitCode !== 0 && install.fallback) {
      emitTerminalEvent(runtime, {
        type: 'meta',
        data: `${install.label} failed. Retrying with ${install.fallback.label}...`,
      })
      result = await runInstallCommand(install.fallback)
    }

    if (result.timedOut) {
      throw new Error(`Dependency install timed out after ${installTimeoutMs}ms`)
    }

    if (result.exitCode !== 0) {
      const stderrFirstLine = firstMeaningfulLine(result.stderr)
      const stdoutFirstLine = firstMeaningfulLine(result.stdout)
      throw new Error(stderrFirstLine || stdoutFirstLine || `${install.label} failed with exit code ${result.exitCode}`)
    }

    emitTerminalEvent(runtime, {
      type: 'meta',
      data: 'Dependencies installed.',
    })
  })()
    .finally(() => {
      dependencyInstallLocks.delete(runtime.workspaceId)
    })

  dependencyInstallLocks.set(runtime.workspaceId, lock)
  await lock
}

async function ensureTerminalRunning(runtime: WorkspaceRuntime): Promise<void> {
  if (isTerminalProcessRunning(runtime.terminal)) {
    return
  }

  const existingLock = terminalStartLocks.get(runtime.workspaceId)
  if (existingLock) {
    await existingLock
    return
  }

  const lock = (async () => {
    const shell = resolveShellCommand()
    const shellEnvironment = {
      ...process.env,
      TERM: 'xterm-256color',
      COLORTERM: 'truecolor',
      FORCE_COLOR: '1',
    }
    const scriptBinary = resolveScriptBinary()

    const child =
      scriptBinary && process.platform !== 'win32'
        ? spawn(
            scriptBinary,
            ['-q', '-c', toShellLaunchCommand(shell.command, shell.args), '/dev/null'],
            {
              cwd: runtime.workspaceDir,
              env: shellEnvironment,
              stdio: 'pipe',
            }
          )
        : spawn(shell.command, shell.args, {
            cwd: runtime.workspaceDir,
            env: shellEnvironment,
            stdio: 'pipe',
          })

    const shellLabel = scriptBinary && process.platform !== 'win32' ? `${shell.label} (pty)` : shell.label
    attachTerminalProcess(runtime, child, shellLabel)

    const terminalReady = await waitForTerminalReady(runtime)
    if (!terminalReady) {
      throw new Error('Terminal session is not running')
    }
  })()
    .finally(() => {
      terminalStartLocks.delete(runtime.workspaceId)
    })

  terminalStartLocks.set(runtime.workspaceId, lock)
  await lock
}

async function ensureDevServerRunning(runtime: WorkspaceRuntime): Promise<void> {
  if (runtime.devServer.status === 'running') {
    await refreshDevServerStatus(runtime)
  }

  if (isDevServerRunning(runtime.devServer)) {
    return
  }

  const existingLock = devServerStartLocks.get(runtime.workspaceId)
  if (existingLock) {
    await existingLock
    return
  }

  const lock = (async () => {
    await ensureWorkspaceDependencies(runtime)
    await ensureTerminalRunning(runtime)
    if (
      !runtime.terminal.child
      || runtime.terminal.child.killed
      || (runtime.terminal.status !== 'running' && runtime.terminal.status !== 'starting')
    ) {
      throw new Error('Terminal session is not running')
    }

    const port = await findAvailablePort(runtime.projectId)
    const commandConfig = await resolveWorkspaceDevCommandConfig(runtime.workspaceDir)
    const command = resolveDevServerCommand(runtime, port, commandConfig)

    runtime.devServer.port = port
    runtime.devServer.command = command
    runtime.devServer.status = 'starting'
    runtime.devServer.startedAt = Date.now()
    runtime.devServer.updatedAt = Date.now()
    runtime.devServer.lastError = null
    runtime.updatedAt = Date.now()

    emitTerminalEvent(runtime, {
      type: 'meta',
      data: `Starting dev server in terminal: ${command}`,
    })
    runtime.terminal.lastInputAt = Date.now()
    runtime.terminal.child.stdin.write(`${command}\n`)

    try {
      await waitForDevServer(port)
      runtime.devServer.status = 'running'
      runtime.devServer.updatedAt = Date.now()
      runtime.updatedAt = Date.now()
      emitTerminalEvent(runtime, {
        type: 'meta',
        data: `Dev server running on port ${port}`,
      })
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Dev server readiness check failed'
      runtime.devServer.status = 'error'
      runtime.devServer.lastError = message
      runtime.devServer.updatedAt = Date.now()
      runtime.updatedAt = Date.now()
      emitTerminalEvent(runtime, {
        type: 'error',
        data: message,
      })
      stopDevServerProcess(runtime, 'Stopping dev server after failed readiness check.')
      throw error
    }
  })()
    .finally(() => {
      devServerStartLocks.delete(runtime.workspaceId)
    })

  devServerStartLocks.set(runtime.workspaceId, lock)
  await lock
}

async function restartDevServer(runtime: WorkspaceRuntime): Promise<void> {
  stopDevServerProcess(runtime, 'Restarting dev server...')
  await ensureDevServerRunning(runtime)
}

function createRuntime(projectId: string, projectSlug: string | null, ownerUserId: string, bridgeScriptUrl: string | null): WorkspaceRuntime {
  const now = Date.now()
  return {
    workspaceId: randomUUID(),
    projectId,
    projectSlug,
    ownerUserId,
    workspaceDir: getWorkspaceDir(projectId),
    previewToken: randomUUID(),
    bridgeScriptUrl,
    createdAt: now,
    updatedAt: now,
    lastAction: 'start',
    terminal: {
      sessionId: randomUUID(),
      shellLabel: resolveShellCommand().label,
      child: null,
      status: 'stopped',
      createdAt: now,
      updatedAt: now,
      lastInputAt: now,
      nextSeq: 0,
      backlog: [],
      subscribers: new Map(),
    },
    devServer: {
      status: 'stopped',
      port: null,
      command: null,
      startedAt: null,
      updatedAt: now,
      lastError: null,
    },
  }
}

async function ensureWorkspace(
  projectId: string,
  projectSlug: string | null,
  ownerUserId: string,
  bridgeScriptUrl: string | null,
  resetWorkspace: boolean
): Promise<WorkspaceRuntime> {
  const existing = workspacesByProject.get(projectId)
  if (existing && !resetWorkspace) {
    existing.projectSlug = projectSlug
    existing.ownerUserId = ownerUserId
    existing.bridgeScriptUrl = bridgeScriptUrl || existing.bridgeScriptUrl
    existing.lastAction = 'read'
    existing.updatedAt = Date.now()
    await ensureTerminalRunning(existing)
    return existing
  }

  if (existing && resetWorkspace) {
    stopDevServerProcess(existing, 'Workspace reset requested.')
    stopTerminalProcess(existing, 'Workspace reset requested.')
    closeTerminalSubscribers(existing)
    workspacesByProject.delete(existing.projectId)
    workspacesById.delete(existing.workspaceId)
  }

  const existingLock = workspaceStartLocks.get(projectId)
  if (existingLock) {
    return existingLock
  }

  const lock = (async () => {
    const runtime = createRuntime(projectId, projectSlug, ownerUserId, bridgeScriptUrl)

    const hydration = await hydrateWorkspace(projectId, runtime.workspaceDir)
    runtime.updatedAt = Date.now()
    runtime.lastAction = 'start'

    workspacesByProject.set(projectId, runtime)
    workspacesById.set(runtime.workspaceId, runtime)

    await ensureTerminalRunning(runtime)

    const projectFilesWritten = Math.max(0, hydration.written - hydration.canonicalWritten)
    const hydrationParts: string[] = []
    if (hydration.canonicalSource === 'git' && hydration.canonicalWritten > 0) {
      hydrationParts.push(`${hydration.canonicalWritten} Git files restored`)
    }
    hydrationParts.push(`${projectFilesWritten} project files applied`)
    if (hydration.skipped > 0) {
      hydrationParts.push(`${hydration.skipped} project files skipped`)
    }
    if (hydration.canonicalError) {
      hydrationParts.push(`canonical restore unavailable (${hydration.canonicalError})`)
    }

    emitTerminalEvent(runtime, {
      type: 'meta',
      data: `Workspace ready (${hydrationParts.join(', ')}).`,
    })

    return runtime
  })()
    .finally(() => {
      workspaceStartLocks.delete(projectId)
    })

  workspaceStartLocks.set(projectId, lock)
  return lock
}

function findWorkspaceByLookup(projectId: string | null, workspaceId: string | null): WorkspaceRuntime | null {
  if (workspaceId) {
    return workspacesById.get(workspaceId) || null
  }

  if (projectId) {
    return workspacesByProject.get(projectId) || null
  }

  return null
}

function stopAndRemoveWorkspace(runtime: WorkspaceRuntime, reason?: string): void {
  stopDevServerProcess(runtime, reason)
  stopTerminalProcess(runtime, reason)
  closeTerminalSubscribers(runtime)

  workspacesByProject.delete(runtime.projectId)
  workspacesById.delete(runtime.workspaceId)
}

function toTerminalPaths(runtime: WorkspaceRuntime) {
  return {
    transport: 'sse' as const,
    streamPath: `/runtime/workspaces/${encodeURIComponent(runtime.workspaceId)}/terminal/stream`,
    commandPath: `/runtime/workspaces/${encodeURIComponent(runtime.workspaceId)}/terminal/command`,
    inputPath: `/runtime/workspaces/${encodeURIComponent(runtime.workspaceId)}/terminal/input`,
  }
}

function toWorkspaceResponse(
  runtime: WorkspaceRuntime,
  request: FastifyRequest,
  overrides?: Partial<WorkspaceResponse>
): WorkspaceResponse {
  const serverRunning = runtime.devServer.status === 'running' || runtime.devServer.status === 'starting'
  const terminalPaths = toTerminalPaths(runtime)

  return {
    workspaceId: runtime.workspaceId,
    projectId: runtime.projectId,
    projectSlug: runtime.projectSlug,
    status: runtime.devServer.status,
    running: serverRunning,
    serverRunning,
    previewBaseUrl: buildPreviewBaseUrl(request, runtime.workspaceId, runtime.previewToken),
    bridgeScriptUrl: runtime.bridgeScriptUrl || buildBridgeScriptUrl(request),
    mode: 'vm',
    provider: 'gateway-vm',
    createdAt: runtime.createdAt,
    updatedAt: runtime.updatedAt,
    lastAction: runtime.lastAction,
    workspaceDir: runtime.workspaceDir,
    capabilities: {
      livePreview: true,
      inspectorBridge: true,
      screenshotBridge: true,
      interactiveTerminal: true,
      workspaceFiles: true,
    },
    terminal: {
      transport: terminalPaths.transport,
      streamPath: terminalPaths.streamPath,
      commandPath: terminalPaths.commandPath,
      inputPath: terminalPaths.inputPath,
      shell: runtime.terminal.shellLabel,
      status: runtime.terminal.status,
      sessionId: runtime.terminal.sessionId,
    },
    devServer: {
      status: runtime.devServer.status,
      port: runtime.devServer.port,
      command: runtime.devServer.command,
      lastError: runtime.devServer.lastError,
    },
    ...overrides,
  }
}

