async function resolveOrSyncUser(
  request: FastifyRequest,
  payload: TokenPayload
): Promise<{ _id: string } | null> {
  const existing = await getUserByWorkosId(payload.sub)
  if (existing) {
    return { _id: existing._id }
  }

  const workosUser = await request.server.workos.userManagement.getUser(payload.sub)
  const email = workosUser.email || payload.email
  if (!email) return null

  await syncUserFromWorkOS({
    workosId: workosUser.id,
    email,
    firstName: workosUser.firstName || undefined,
    lastName: workosUser.lastName || undefined,
    profileImageUrl: workosUser.profilePictureUrl || undefined,
  })

  const synced = await getUserByWorkosId(payload.sub)
  return synced ? { _id: synced._id } : null
}

async function requireUserContext(
  request: FastifyRequest,
  reply: FastifyReply
): Promise<AccessContext | null> {
  const tokenPayload = await getTokenPayload(request.headers.authorization)
  if (!tokenPayload) {
    await reply.status(401).send({ error: 'Unauthorized' })
    return null
  }

  const user = await resolveOrSyncUser(request, tokenPayload)
  if (!user?._id) {
    await reply.status(401).send({ error: 'Unable to resolve user context' })
    return null
  }

  return {
    workosUserId: tokenPayload.sub,
    convexUserId: user._id,
  }
}

async function requireProjectAccess(
  request: FastifyRequest,
  reply: FastifyReply,
  projectId: string,
  requiredAccess: ProjectAccessLevel = 'read'
): Promise<AccessContext | null> {
  const access = await requireUserContext(request, reply)
  if (!access) return null

  const projectAccess = await getProjectAccessForServer(projectId, access.convexUserId)
  const hasRequiredAccess =
    requiredAccess === 'edit' ? projectAccess.canEdit : projectAccess.canAccess

  if (!hasRequiredAccess) {
    await reply.status(403).send({
      error:
        requiredAccess === 'edit'
          ? 'Not authorized to edit this project'
          : 'Not authorized for this project',
    })
    return null
  }

  return access
}

async function requireWorkspaceAccess(
  request: FastifyRequest,
  reply: FastifyReply,
  workspace: WorkspaceRuntime,
  requiredAccess: ProjectAccessLevel = 'read'
): Promise<AccessContext | null> {
  const access = await requireUserContext(request, reply)
  if (!access) return null

  const projectAccess = await getProjectAccessForServer(
    workspace.projectId,
    access.convexUserId
  )
  const hasRequiredAccess =
    requiredAccess === 'edit' ? projectAccess.canEdit : projectAccess.canAccess

  if (!hasRequiredAccess) {
    await reply.status(403).send({
      error:
        requiredAccess === 'edit'
          ? 'Not authorized to edit this workspace'
          : 'Not authorized for this workspace',
    })
    return null
  }

  return access
}

async function requirePreviewAccess(
  request: FastifyRequest,
  reply: FastifyReply,
  workspace: WorkspaceRuntime,
  previewToken: string
): Promise<boolean> {
  if (previewToken === workspace.previewToken) {
    return true
  }

  const access = await requireWorkspaceAccess(request, reply, workspace, 'read')
  return Boolean(access)
}

function getAuthorizationHeaderValue(value: string | string[] | undefined): string | undefined {
  if (typeof value === 'string') return value
  if (Array.isArray(value) && value.length > 0) return value[0]
  return undefined
}

async function hasPreviewUpgradeAccess(
  request: IncomingMessage,
  workspace: WorkspaceRuntime,
  previewToken: string
): Promise<boolean> {
  if (previewToken === workspace.previewToken) {
    return true
  }

  const tokenPayload = await getTokenPayload(getAuthorizationHeaderValue(request.headers.authorization))
  if (!tokenPayload) {
    return false
  }

  const user = await getUserByWorkosId(tokenPayload.sub)
  if (!user?._id) {
    return false
  }

  const access = await getProjectAccessForServer(workspace.projectId, user._id)
  return access.canAccess
}

function copyProxyRequestHeaders(headers: IncomingHttpHeaders): Record<string, string | string[]> {
  const forwarded: Record<string, string | string[]> = {}

  for (const [key, value] of Object.entries(headers)) {
    if (!value) continue
    const normalized = key.toLowerCase()
    if (HOP_BY_HOP_HEADERS.has(normalized)) continue
    if (normalized === 'host') continue
    if (normalized === 'authorization') continue
    if (normalized === 'content-length') continue
    if (normalized === 'accept-encoding') continue

    if (Array.isArray(value)) {
      forwarded[key] = value
    } else {
      forwarded[key] = value
    }
  }

  forwarded.host = '127.0.0.1'
  return forwarded
}

function copyUpgradeProxyHeaders(headers: IncomingHttpHeaders): Record<string, string | string[]> {
  const forwarded: Record<string, string | string[]> = {}

  for (const [key, value] of Object.entries(headers)) {
    if (!value) continue
    const normalized = key.toLowerCase()
    if (normalized === 'host') continue
    if (normalized === 'authorization') continue

    if (Array.isArray(value)) {
      forwarded[key] = value
    } else {
      forwarded[key] = value
    }
  }

  return forwarded
}

function writeProxyResponseHeaders(headers: IncomingHttpHeaders, response: ServerResponse): void {
  for (const [headerName, headerValue] of Object.entries(headers)) {
    if (typeof headerValue === 'undefined') continue
    const normalized = headerName.toLowerCase()
    if (HOP_BY_HOP_HEADERS.has(normalized)) continue
    response.setHeader(headerName, headerValue)
  }
}

function headerValueToString(value: string | string[] | undefined): string {
  if (typeof value === 'string') return value
  if (Array.isArray(value)) return value.join(', ')
  return ''
}

function isHtmlResponse(contentTypeHeader: string): boolean {
  const contentType = contentTypeHeader.toLowerCase()
  return contentType.includes('text/html') || contentType.includes('application/xhtml+xml')
}

function escapeHtmlAttribute(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
}

function injectBridgeTagIntoHtmlDocument(html: string, bridgeScriptUrl: string): string {
  if (!html.trim()) return html
  if (html.includes('data-cozea-preview-bridge=')) return html

  const bridgeTag = `<script data-cozea-preview-bridge="1" src="${escapeHtmlAttribute(bridgeScriptUrl)}" defer></script>`

  if (/<\/head>/i.test(html)) {
    return html.replace(/<\/head>/i, `${bridgeTag}</head>`)
  }

  if (/<body[^>]*>/i.test(html)) {
    return html.replace(/<body[^>]*>/i, (match) => `${match}${bridgeTag}`)
  }

  return `${bridgeTag}${html}`
}

function writeRawHttpResponseToSocket(socket: Socket, response: IncomingMessage): void {
  if (socket.destroyed) return

  const statusCode = response.statusCode || 502
  const statusMessage = response.statusMessage || 'Bad Gateway'

  socket.write(`HTTP/1.1 ${statusCode} ${statusMessage}\r\n`)

  for (const [headerName, headerValue] of Object.entries(response.headers)) {
    if (typeof headerValue === 'undefined') continue
    if (Array.isArray(headerValue)) {
      for (const value of headerValue) {
        socket.write(`${headerName}: ${value}\r\n`)
      }
    } else {
      socket.write(`${headerName}: ${headerValue}\r\n`)
    }
  }

  socket.write('\r\n')
  response.pipe(socket)
}

function socketStatusText(statusCode: number): string {
  if (statusCode === 400) return 'Bad Request'
  if (statusCode === 403) return 'Forbidden'
  if (statusCode === 404) return 'Not Found'
  if (statusCode === 409) return 'Conflict'
  if (statusCode === 502) return 'Bad Gateway'
  return 'Error'
}

function writeSocketError(socket: Socket, statusCode: number, message: string): void {
  if (socket.destroyed) return

  const body = JSON.stringify({ error: message })
  const headers = [
    `HTTP/1.1 ${statusCode} ${socketStatusText(statusCode)}`,
    'Content-Type: application/json; charset=utf-8',
    `Content-Length: ${Buffer.byteLength(body)}`,
    'Connection: close',
    '',
    body,
  ]

  socket.write(headers.join('\r\n'))
  socket.end()
}

function parsePreviewUpgradeTarget(rawUrl: string | undefined): {
  workspaceId: string
  previewToken: string
  targetPath: string
} | null {
  if (!rawUrl) return null

  let parsedUrl: URL
  try {
    parsedUrl = new URL(rawUrl, 'http://localhost')
  } catch {
    return null
  }

  const match = /^\/runtime\/workspaces\/([^/]+)\/preview\/([^/]+)(?:\/(.*))?$/.exec(parsedUrl.pathname)
  if (!match) return null

  let workspaceIdDecoded = ''
  let previewTokenDecoded = ''
  try {
    workspaceIdDecoded = decodeURIComponent(match[1] || '')
    previewTokenDecoded = decodeURIComponent(match[2] || '')
  } catch {
    return null
  }

  const workspaceId = normalizeWorkspaceId(workspaceIdDecoded)
  const previewToken = normalizeString(previewTokenDecoded)
  if (!workspaceId || !previewToken) return null

  const wildcardPath = normalizeString(match[3]) || ''
  const routePath = wildcardPath.startsWith('/') ? wildcardPath : `/${wildcardPath}`
  const targetPath = `${routePath}${parsedUrl.search || ''}`

  return {
    workspaceId,
    previewToken,
    targetPath,
  }
}

function proxyPreviewUpgradeRequest(
  request: IncomingMessage,
  socket: Socket,
  head: Buffer,
  runtime: WorkspaceRuntime,
  targetPath: string
): void {
  const port = runtime.devServer.port
  if (!port || runtime.devServer.status !== 'running') {
    writeSocketError(socket, 409, 'Preview dev server is not running')
    return
  }

  const upstream = http.request({
    host: '127.0.0.1',
    port,
    method: request.method || 'GET',
    path: targetPath,
    headers: {
      ...copyUpgradeProxyHeaders(request.headers),
      host: `127.0.0.1:${port}`,
    },
  })

  let upgraded = false

  upstream.on('upgrade', (upstreamResponse, upstreamSocket, upstreamHead) => {
    upgraded = true
    if (socket.destroyed) {
      upstreamSocket.destroy()
      return
    }

    socket.write(
      `HTTP/1.1 ${upstreamResponse.statusCode || 101} ${upstreamResponse.statusMessage || 'Switching Protocols'}\r\n`
    )

    for (const [headerName, headerValue] of Object.entries(upstreamResponse.headers)) {
      if (typeof headerValue === 'undefined') continue
      if (Array.isArray(headerValue)) {
        for (const value of headerValue) {
          socket.write(`${headerName}: ${value}\r\n`)
        }
      } else {
        socket.write(`${headerName}: ${headerValue}\r\n`)
      }
    }

    socket.write('\r\n')

    if (upstreamHead.length > 0) {
      socket.write(upstreamHead)
    }
    if (head.length > 0) {
      upstreamSocket.write(head)
    }

    socket.pipe(upstreamSocket).pipe(socket)

    const closeBoth = () => {
      if (!socket.destroyed) socket.destroy()
      if (!upstreamSocket.destroyed) upstreamSocket.destroy()
    }

    socket.on('error', closeBoth)
    socket.on('close', closeBoth)
    upstreamSocket.on('error', closeBoth)
    upstreamSocket.on('close', closeBoth)
  })

  upstream.on('response', (upstreamResponse) => {
    if (upgraded) return
    writeRawHttpResponseToSocket(socket, upstreamResponse)
  })

  upstream.on('error', (error) => {
    const message = error instanceof Error ? error.message : 'Preview websocket proxy failed'
    runtime.devServer.status = 'stopped'
    runtime.devServer.lastError = message
    runtime.devServer.updatedAt = Date.now()
    runtime.updatedAt = Date.now()
    if (!upgraded) {
      writeSocketError(socket, 502, 'Preview websocket proxy failed')
    }
  })

  socket.on('close', () => {
    if (!upstream.destroyed) {
      upstream.destroy()
    }
  })

  upstream.end()
}

async function proxyPreviewRequest(
  request: FastifyRequest,
  reply: FastifyReply,
  runtime: WorkspaceRuntime,
  routePath: string
): Promise<void> {
  await waitForStartingDevServerGrace(runtime)
  await refreshDevServerStatus(runtime)

  const port = runtime.devServer.port
  if (!port || runtime.devServer.status !== 'running') {
    await reply.status(409).send({ error: 'Preview dev server is not running' })
    return
  }

  const method = request.method.toUpperCase()
  const rawUrl = request.raw.url || ''
  const queryIndex = rawUrl.indexOf('?')
  const querySuffix = queryIndex >= 0 ? rawUrl.slice(queryIndex) : ''
  const targetPath = `${routePath}${querySuffix}`
  const canHaveBody = !['GET', 'HEAD'].includes(method)
  let bridgeScriptUrl = runtime.bridgeScriptUrl || buildBridgeScriptUrl(request)

  try {
    const parsedRequestUrl = new URL(rawUrl, 'http://localhost')
    const queryBridgeScript = normalizeString(parsedRequestUrl.searchParams.get('cozeaBridgeScript'))
    if (queryBridgeScript) {
      const parsedBridge = new URL(queryBridgeScript)
      if (parsedBridge.protocol === 'http:' || parsedBridge.protocol === 'https:') {
        bridgeScriptUrl = parsedBridge.toString()
      }
    }
  } catch {
    // keep resolved bridge URL as-is
  }

  reply.hijack()

  const upstream = http.request(
    {
      host: '127.0.0.1',
      port,
      method,
      path: targetPath,
      headers: {
        ...copyProxyRequestHeaders(request.headers),
        host: `127.0.0.1:${port}`,
      },
    },
    (upstreamResponse) => {
      const response = reply.raw
      const contentType = headerValueToString(upstreamResponse.headers['content-type'])
      const contentEncoding = headerValueToString(upstreamResponse.headers['content-encoding']).toLowerCase()
      const canInjectBridge =
        method === 'GET'
        && Boolean(bridgeScriptUrl)
        && isHtmlResponse(contentType)
        && !contentEncoding
        && upstreamResponse.statusCode !== 304

      if (!canInjectBridge) {
        response.statusCode = upstreamResponse.statusCode || 502
        response.statusMessage = upstreamResponse.statusMessage || response.statusMessage
        writeProxyResponseHeaders(upstreamResponse.headers, response)
        upstreamResponse.pipe(response)
        return
      }

      const chunks: Buffer[] = []
      upstreamResponse.on('data', (chunk: Buffer | string) => {
        chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk)))
      })

      upstreamResponse.on('end', () => {
        if (response.writableEnded || response.destroyed) return

        const html = Buffer.concat(chunks).toString('utf8')
        const rewrittenHtml = injectBridgeTagIntoHtmlDocument(html, bridgeScriptUrl!)
        const rewrittenLength = Buffer.byteLength(rewrittenHtml, 'utf8')

        response.statusCode = upstreamResponse.statusCode || 502
        response.statusMessage = upstreamResponse.statusMessage || response.statusMessage

        for (const [headerName, headerValue] of Object.entries(upstreamResponse.headers)) {
          if (typeof headerValue === 'undefined') continue
          const normalized = headerName.toLowerCase()
          if (HOP_BY_HOP_HEADERS.has(normalized)) continue
          if (normalized === 'content-length') continue
          if (normalized === 'etag') continue
          if (normalized === 'content-encoding') continue
          response.setHeader(headerName, headerValue)
        }

        if (!response.hasHeader('content-type')) {
          response.setHeader('Content-Type', 'text/html; charset=utf-8')
        }
        response.setHeader('Content-Length', String(rewrittenLength))
        response.end(rewrittenHtml)
      })

      upstreamResponse.on('error', (error) => {
        if (response.writableEnded || response.destroyed) return
        const message = error instanceof Error ? error.message : 'Preview proxy response failed'
        response.statusCode = 502
        response.setHeader('Content-Type', 'application/json; charset=utf-8')
        response.end(JSON.stringify({ error: message }))
      })
    }
  )

  upstream.on('error', (error) => {
    const response = reply.raw
    if (response.writableEnded || response.destroyed) return

    const message = error instanceof Error ? error.message : 'Preview proxy request failed'
    runtime.devServer.status = 'stopped'
    runtime.devServer.lastError = message
    runtime.devServer.updatedAt = Date.now()
    runtime.updatedAt = Date.now()
    response.statusCode = 502
    response.setHeader('Content-Type', 'application/json; charset=utf-8')
    response.end(JSON.stringify({ error: message }))
  })

  request.raw.on('aborted', () => {
    if (!upstream.destroyed) {
      upstream.destroy()
    }
  })

  if (canHaveBody) {
    request.raw.pipe(upstream)
  } else {
    upstream.end()
  }
}

export const runtimeWorkspacesRoutes: FastifyPluginAsync = async (fastify) => {
  const workspaceIdleTtlMs = parseInteger(process.env.WEB_VM_WORKSPACE_IDLE_TTL_MS, DEFAULT_WORKSPACE_IDLE_TTL_MS)
  const terminalIdleTtlMs = parseInteger(process.env.WEB_VM_TERMINAL_IDLE_TTL_MS, DEFAULT_TERMINAL_IDLE_TTL_MS)

  const cleanupInterval = setInterval(() => {
    const now = Date.now()

    for (const runtime of workspacesByProject.values()) {
      const terminalIdleSince = Math.max(runtime.terminal.updatedAt, runtime.terminal.lastInputAt)
      const hasTerminalSubscribers = runtime.terminal.subscribers.size > 0

      if (!hasTerminalSubscribers && now - terminalIdleSince > terminalIdleTtlMs && isTerminalProcessRunning(runtime.terminal)) {
        stopTerminalProcess(runtime, 'Terminal stopped due to inactivity.')
      }

      const workspaceIdleSince = Math.max(runtime.updatedAt, runtime.terminal.updatedAt, runtime.devServer.updatedAt)
      if (now - workspaceIdleSince > workspaceIdleTtlMs && !hasTerminalSubscribers) {
        stopAndRemoveWorkspace(runtime, 'Workspace stopped due to inactivity.')
      }
    }
  }, 60_000)
  cleanupInterval.unref()

  const previewUpgradeHandler = (request: IncomingMessage, socket: Socket, head: Buffer) => {
    const target = parsePreviewUpgradeTarget(request.url)
    if (!target) {
      return
    }

    void (async () => {
      const runtime = workspacesById.get(target.workspaceId)
      if (!runtime) {
        writeSocketError(socket, 404, 'Workspace not found')
        return
      }

      const hasAccess = await hasPreviewUpgradeAccess(request, runtime, target.previewToken)
      if (!hasAccess) {
        writeSocketError(socket, 403, 'Not authorized for this workspace')
        return
      }

      await waitForStartingDevServerGrace(runtime)
      await refreshDevServerStatus(runtime)
      runtime.lastAction = 'read'
      runtime.updatedAt = Date.now()
      proxyPreviewUpgradeRequest(request, socket, head, runtime, target.targetPath)
    })().catch((error) => {
      fastify.log.error({ err: error }, 'Preview websocket upgrade failed')
      writeSocketError(socket, 502, 'Preview websocket proxy failed')
    })
  }

