  fastify.post<{
    Params: {
      workspaceId: string
    }
    Body: {
      filePaths?: string[]
      filePath?: string
    }
  }>('/:workspaceId/files/delete', async (request, reply) => {
    const workspaceId = normalizeWorkspaceId(request.params.workspaceId)
    if (!workspaceId) {
      return reply.status(400).send({ error: 'workspaceId is required' })
    }

    const runtime = workspacesById.get(workspaceId)
    if (!runtime) {
      return reply.status(404).send({ error: 'Workspace not found' })
    }

    const access = await requireWorkspaceAccess(request, reply, runtime, 'edit')
    if (!access) return

    const rawPaths: string[] = []
    if (Array.isArray(request.body?.filePaths)) {
      for (const entry of request.body.filePaths) {
        if (typeof entry === 'string') rawPaths.push(entry)
      }
    }
    if (typeof request.body?.filePath === 'string') {
      rawPaths.push(request.body.filePath)
    }

    const normalizedPaths = Array.from(
      new Set(
        rawPaths
          .map((value) => normalizeWorkspaceFilePath(value))
          .filter((value): value is string => typeof value === 'string' && value.length > 0)
      )
    )

    if (normalizedPaths.length === 0) {
      return reply.status(400).send({ error: 'filePaths must include at least one path' })
    }

    const deleted: string[] = []
    const skipped: string[] = []

    for (const filePath of normalizedPaths) {
      const absolutePath = toAbsoluteWorkspacePath(runtime.workspaceDir, filePath)
      if (!absolutePath) {
        skipped.push(filePath)
        continue
      }

      const targetStats = await statWorkspacePath(absolutePath)
      if (!targetStats) {
        skipped.push(filePath)
        continue
      }

      if (targetStats.isDirectory()) {
        await rm(absolutePath, { recursive: true, force: true })
      } else {
        await unlink(absolutePath)
      }
      deleted.push(filePath)
    }

    runtime.ownerUserId = access.convexUserId
    runtime.lastAction = 'read'
    runtime.updatedAt = Date.now()

    return reply.send({
      ok: true,
      workspaceId: runtime.workspaceId,
      projectId: runtime.projectId,
      deleted,
      skipped,
    })
  })

