    }

    const access = await requireWorkspaceAccess(request, reply, runtime, 'edit')
    if (!access) return

    runtime.ownerUserId = access.convexUserId

    await ensureTerminalRunning(runtime)

    return reply.send({
      workspaceId: runtime.workspaceId,
      projectId: runtime.projectId,
      sessionId: runtime.terminal.sessionId,
      status: runtime.terminal.status,
      shell: runtime.terminal.shellLabel,
      workspaceDir: runtime.workspaceDir,
      createdAt: runtime.terminal.createdAt,
      updatedAt: runtime.terminal.updatedAt,
    })
  })

  fastify.post<{
    Params: {
      workspaceId: string
    }
  }>('/:workspaceId/terminal/stop', async (request, reply) => {
    const workspaceId = normalizeWorkspaceId(request.params.workspaceId)
    if (!workspaceId) {
      return reply.status(400).send({ error: 'workspaceId is required' })
    }

    const runtime = workspacesById.get(workspaceId)
    if (!runtime) {
      return reply.status(404).send({ error: 'Workspace not found' })
    }

    const access = await requireWorkspaceAccess(request, reply, runtime, 'edit')
    if (!access) return

    runtime.ownerUserId = access.convexUserId

    stopTerminalProcess(runtime, `Terminal stopped by ${access.convexUserId}.`)

    return reply.send({
      workspaceId: runtime.workspaceId,
      projectId: runtime.projectId,
      sessionId: runtime.terminal.sessionId,
      status: runtime.terminal.status,
      shell: runtime.terminal.shellLabel,
      workspaceDir: runtime.workspaceDir,
      createdAt: runtime.terminal.createdAt,
      updatedAt: runtime.terminal.updatedAt,
    })
  })

  fastify.get<{
    Params: {
      workspaceId: string
    }
    Querystring: {
      sessionId?: string
    }
  }>('/:workspaceId/terminal/stream', async (request, reply) => {
    const workspaceId = normalizeWorkspaceId(request.params.workspaceId)
    if (!workspaceId) {
      return reply.status(400).send({ error: 'workspaceId is required' })
    }

    const runtime = workspacesById.get(workspaceId)
    if (!runtime) {
      return reply.status(404).send({ error: 'Workspace not found' })
    }

    const access = await requireWorkspaceAccess(request, reply, runtime, 'edit')
    if (!access) return

    const expectedSessionId = normalizeString(request.query.sessionId)
    if (expectedSessionId && expectedSessionId !== runtime.terminal.sessionId) {
      return reply.status(409).send({ error: 'Terminal session changed. Refresh and reconnect.' })
    }

    const subscriberId = randomUUID()
    const response = reply.raw
    const origin = typeof request.headers.origin === 'string' ? request.headers.origin : null

    reply.hijack()
    response.statusCode = 200
    response.setHeader('Content-Type', 'text/event-stream; charset=utf-8')
    response.setHeader('Cache-Control', 'no-cache, no-transform')
    response.setHeader('Connection', 'keep-alive')
    response.setHeader('X-Accel-Buffering', 'no')
    if (origin) {
      response.setHeader('Access-Control-Allow-Origin', origin)
      response.setHeader('Access-Control-Allow-Credentials', 'true')
      response.setHeader('Vary', 'Origin')
    }
    response.flushHeaders?.()
    response.write(': connected\\n\\n')

    for (const event of runtime.terminal.backlog) {
      writeSse(response, event)
    }

    runtime.terminal.subscribers.set(subscriberId, response)

    const heartbeat = setInterval(() => {
      if (response.destroyed || response.writableEnded) {
        unregisterSubscriber(runtime, subscriberId)
        return
      }

      try {
        response.write(': keep-alive\\n\\n')
      } catch {
        unregisterSubscriber(runtime, subscriberId)
      }
    }, STREAM_HEARTBEAT_MS)
    heartbeat.unref()
    subscriberHeartbeats.set(subscriberId, heartbeat)

    request.raw.on('close', () => {
      unregisterSubscriber(runtime, subscriberId)
    })
  })

  fastify.post<{
    Params: {
      workspaceId: string
    }
    Body: {
      command?: string
    }
  }>('/:workspaceId/terminal/command', async (request, reply) => {
    const workspaceId = normalizeWorkspaceId(request.params.workspaceId)
    const command = typeof request.body?.command === 'string' ? request.body.command : ''

    if (!workspaceId) {
      return reply.status(400).send({ error: 'workspaceId is required' })
    }

    if (!command.trim()) {
      return reply.status(400).send({ error: 'command is required' })
    }

    const runtime = workspacesById.get(workspaceId)
    if (!runtime) {
      return reply.status(404).send({ error: 'Workspace not found' })
    }

    const access = await requireWorkspaceAccess(request, reply, runtime, 'edit')
    if (!access) return

    await ensureTerminalRunning(runtime)

    if (
      !runtime.terminal.child
      || runtime.terminal.child.killed
      || (runtime.terminal.status !== 'running' && runtime.terminal.status !== 'starting')
    ) {
      return reply.status(409).send({ error: 'Terminal session is not running' })
    }

    const normalizedCommand = command.replace(/\r?\n/g, '\n').trimEnd()
    runtime.terminal.lastInputAt = Date.now()

    emitTerminalEvent(runtime, {
      type: 'meta',
      data: `$ ${normalizedCommand}`,
    })

    runtime.terminal.child.stdin.write(`${normalizedCommand}\n`)

    return reply.send({
      ok: true,
      workspaceId: runtime.workspaceId,
      projectId: runtime.projectId,
      sessionId: runtime.terminal.sessionId,
    })
  })

  fastify.post<{
    Params: {
      workspaceId: string
    }
    Body: {
      data?: string
    }
  }>('/:workspaceId/terminal/input', async (request, reply) => {
    const workspaceId = normalizeWorkspaceId(request.params.workspaceId)
    const data = typeof request.body?.data === 'string' ? request.body.data : ''

    if (!workspaceId) {
      return reply.status(400).send({ error: 'workspaceId is required' })
    }

    if (!data.length) {
      return reply.status(400).send({ error: 'data is required' })
    }

    const runtime = workspacesById.get(workspaceId)
    if (!runtime) {
      return reply.status(404).send({ error: 'Workspace not found' })
    }

    const access = await requireWorkspaceAccess(request, reply, runtime, 'edit')
    if (!access) return

    await ensureTerminalRunning(runtime)

    if (
      !runtime.terminal.child
      || runtime.terminal.child.killed
      || (runtime.terminal.status !== 'running' && runtime.terminal.status !== 'starting')
    ) {
      return reply.status(409).send({ error: 'Terminal session is not running' })
    }

    runtime.terminal.lastInputAt = Date.now()
    runtime.terminal.child.stdin.write(data)

    return reply.send({
      ok: true,
      workspaceId: runtime.workspaceId,
      projectId: runtime.projectId,
      sessionId: runtime.terminal.sessionId,
    })
  })

  fastify.all<{
    Params: {
      workspaceId: string
      previewToken: string
      '*': string
    }
  }>('/:workspaceId/preview/:previewToken/*', async (request, reply) => {
    const workspaceId = normalizeWorkspaceId(request.params.workspaceId)
    const previewToken = normalizeString(request.params.previewToken)
    const wildcardPath = normalizeString(request.params['*']) || ''

    if (!workspaceId || !previewToken) {
      return reply.status(400).send({ error: 'workspaceId and preview token are required' })
    }

    const runtime = workspacesById.get(workspaceId)
    if (!runtime) {
      return reply.status(404).send({ error: 'Workspace not found' })
    }

    const canAccess = await requirePreviewAccess(request, reply, runtime, previewToken)
    if (!canAccess) return

    const routePath = wildcardPath.startsWith('/') ? wildcardPath : `/${wildcardPath}`
    await proxyPreviewRequest(request, reply, runtime, routePath)
  })

  fastify.all<{
    Params: {
      workspaceId: string
      previewToken: string
    }
  }>('/:workspaceId/preview/:previewToken', async (request, reply) => {
    const workspaceId = normalizeWorkspaceId(request.params.workspaceId)
    const previewToken = normalizeString(request.params.previewToken)

    if (!workspaceId || !previewToken) {
      return reply.status(400).send({ error: 'workspaceId and preview token are required' })
    }

    const runtime = workspacesById.get(workspaceId)
    if (!runtime) {
      return reply.status(404).send({ error: 'Workspace not found' })
    }

    const canAccess = await requirePreviewAccess(request, reply, runtime, previewToken)
    if (!canAccess) return

    await proxyPreviewRequest(request, reply, runtime, '/')
  })
}

