        void addToolOutput({
          tool: toolName,
          toolCallId,
          output: JSON.stringify(outputPayload),
        })
        return
      }

      if (toolName === 'build_complete') {
        const currentTasks = latestTasksRef.current
        if (currentTasks.length === 0) {
          logGeminiTodowrite('build_complete_blocked_missing_tasks', {
            toolCallId,
            input,
