import { useCallback, useEffect, useRef, useState } from 'react'
import { useSearchParams } from 'react-router-dom'
import { X, MoreHorizontal } from "lucide-react"
import { cn } from "@/lib/utils"
import { useFileTabsStore, pathsReferToSameFile } from "@/stores/useFileTabsStore"
import { useEditorStore } from "@/stores/useEditorStore"
import { getFileIcon } from "@/lib/fileExplorer/fileIcons"
import { UnsavedChangesDialog } from "@/components/editor/UnsavedChangesDialog"
import { useAccessibleProject } from "@/features/projects/hooks/useAccessibleProject"
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"

const EMPTY_ARRAY: string[] = []

export function EditorTabs() {
    const { project, slugParam, projectIdParam } = useAccessibleProject()
    const [searchParams, setSearchParams] = useSearchParams()
    const projectId = project?.slug ?? slugParam ?? projectIdParam ?? ''

    const filePath = searchParams.get('path')

    const fileTabsStore = useFileTabsStore()
    const { openFiles, activeFile } = projectId
        ? fileTabsStore.actions.getProjectTabs(projectId)
        : { openFiles: EMPTY_ARRAY, activeFile: null }
    const { setActiveFile, closeFile, openFile } = fileTabsStore.actions

    const editorModels = useEditorStore((state) => state.models)
    const editorActions = useEditorStore((state) => state.actions)

    const [showUnsavedDialog, setShowUnsavedDialog] = useState(false)
    const [pendingClosePath, setPendingClosePath] = useState<string | null>(null)
    const [hoveredPath, setHoveredPath] = useState<string | null>(null)
    const syncingFromUrlRef = useRef(false)
    const scrollerRef = useRef<HTMLDivElement | null>(null)
    const [showLeftFade, setShowLeftFade] = useState(false)
    const [showRightFade, setShowRightFade] = useState(false)

    const updateScrollFades = useCallback(() => {
        const el = scrollerRef.current
        if (!el) {
            setShowLeftFade(false)
            setShowRightFade(false)
            return
        }

        const maxScrollLeft = Math.max(0, el.scrollWidth - el.clientWidth)
        if (maxScrollLeft <= 1) {
            setShowLeftFade(false)
            setShowRightFade(false)
            return
        }

        setShowLeftFade(el.scrollLeft > 2)
        setShowRightFade(el.scrollLeft < maxScrollLeft - 2)
    }, [])

    useEffect(() => {
        if (filePath && projectId) {
            syncingFromUrlRef.current = true
            openFile(projectId, filePath)
            setActiveFile(projectId, filePath)
        }
    }, [filePath, projectId, openFile, setActiveFile])

    const handleTabClick = (path: string) => {
        if (projectId) {
            setActiveFile(projectId, path)
            setSearchParams({ path })
        }
    }

    const handleCloseTab = (e: React.MouseEvent, path: string) => {
        e.stopPropagation()
        if (!projectId) return

        const model = editorModels[path]
        if (model?.isDirty) {
            setPendingClosePath(path)
            setShowUnsavedDialog(true)
            return
        }

        editorActions.closeFile(path)
        closeFile(projectId, path)
    }

    const handleDiscardAndClose = () => {
        if (pendingClosePath && projectId) {
            editorActions.closeFile(pendingClosePath)
            closeFile(projectId, pendingClosePath)
        }
        setShowUnsavedDialog(false)
        setPendingClosePath(null)
    }

    const handleSaveAndClose = async () => {
        if (pendingClosePath && projectId) {
            await editorActions.saveFile(pendingClosePath)
            editorActions.closeFile(pendingClosePath)
            closeFile(projectId, pendingClosePath)
        }
        setShowUnsavedDialog(false)
        setPendingClosePath(null)
    }

    const handleCancelClose = () => {
        setShowUnsavedDialog(false)
        setPendingClosePath(null)
    }

    const handleCloseAll = () => {
        if (!projectId) return
        const hasUnsaved = openFiles.some(path => editorModels[path]?.isDirty)

        if (hasUnsaved) {
            openFiles.forEach(path => {
                if (!editorModels[path]?.isDirty) {
                    editorActions.closeFile(path)
                    closeFile(projectId, path)
                }
            })
        } else {
            openFiles.forEach(path => {
                editorActions.closeFile(path)
                closeFile(projectId, path)
            })
        }
    }

    const handleCloseAllSaved = () => {
        if (!projectId) return
        openFiles.forEach(path => {
            if (!editorModels[path]?.isDirty) {
                editorActions.closeFile(path)
                closeFile(projectId, path)
            }
        })
    }

    useEffect(() => {
        if (!projectId) return

        if (syncingFromUrlRef.current) {
            if ((activeFile && filePath && pathsReferToSameFile(activeFile, filePath)) || !filePath) {
                syncingFromUrlRef.current = false
            }
            return
        }

        const urlPath = searchParams.get('path')

        if (activeFile) {
            if (!urlPath || !pathsReferToSameFile(activeFile, urlPath)) {
                const nextParams = new URLSearchParams(searchParams)
                nextParams.set('path', activeFile)
                setSearchParams(nextParams, { replace: true })
            }
            return
        }

        if (urlPath) {
            const nextParams = new URLSearchParams(searchParams)
            nextParams.delete('path')
            setSearchParams(nextParams, { replace: true })
        }
    }, [activeFile, filePath, projectId, searchParams, setSearchParams])

    useEffect(() => {
        const el = scrollerRef.current
        if (!el) return

        updateScrollFades()

        const onScroll = () => updateScrollFades()
        el.addEventListener('scroll', onScroll, { passive: true })

        const resizeObserver = new ResizeObserver(() => updateScrollFades())
        resizeObserver.observe(el)

        return () => {
            el.removeEventListener('scroll', onScroll)
            resizeObserver.disconnect()
        }
    }, [openFiles.length, updateScrollFades])

    if (openFiles.length === 0) return null

    return (
        <>
            <div className="relative flex w-full min-w-0 items-center h-9 bg-transparent">
                <div className="relative flex-1 min-w-0 h-full">
                    <div ref={scrollerRef} className="flex items-center h-full overflow-x-auto scrollbar-hide">
                        {openFiles.map((path, index) => {
                            const isActive = path === activeFile || (activeFile != null && pathsReferToSameFile(path, activeFile))
                            const nextPath = openFiles[index + 1]
                            const isNextActive = nextPath
                                ? (nextPath === activeFile || (activeFile != null && pathsReferToSameFile(nextPath, activeFile)))
                                : false
                            const isHovered = hoveredPath != null && pathsReferToSameFile(path, hoveredPath)
                            const isNextHovered = nextPath != null && hoveredPath != null && pathsReferToSameFile(nextPath, hoveredPath)
                            const showSeparator = !isActive && !isNextActive && !isHovered && !isNextHovered && index < openFiles.length - 1
                            const fileName = path.split('/').pop() || 'file'
                            const model = editorModels[path]
                            const isDirty = model?.isDirty ?? false
                            return (
                                <div
                                    key={path}
                                    onClick={() => handleTabClick(path)}
                                    onMouseEnter={() => setHoveredPath(path)}
                                    onMouseLeave={() => setHoveredPath((current) => (current && pathsReferToSameFile(current, path) ? null : current))}
                                    className={cn(
                                        "relative flex items-center gap-2 px-3 h-full min-w-[120px] max-w-[200px] shrink-0 text-xs cursor-pointer select-none group",
                                        isActive
                                            ? "bg-foreground/14 text-foreground rounded-full h-7 my-1"
                                            : "bg-transparent text-muted-foreground hover:bg-foreground/10 hover:text-foreground rounded-full h-7 my-1"
                                    )}
                                >
                                    {showSeparator && (
                                        <span
                                            className="pointer-events-none absolute right-0 top-1/2 h-4 -translate-y-1/2 w-px bg-border/70"
                                            aria-hidden
                                        />
                                    )}
                                    {getFileIcon(fileName, { width: 14, height: 14 })}
                                    <span className="truncate flex-1">{fileName}</span>
                                    {isDirty && (
                                        <span
                                            className="w-2 h-2 rounded-full bg-amber-500 shrink-0"
                                            title="Unsaved changes"
                                        />
                                    )}
                                    <button
                                        onClick={(e) => handleCloseTab(e, path)}
                                        className={cn(
                                            "rounded-sm p-0.5 opacity-0 group-hover:opacity-100 hover:bg-muted text-muted-foreground hover:text-foreground transition-all",
                                            isActive && "opacity-100",
                                            isDirty && "group-hover:opacity-100"
                                        )}
                                    >
                                        <X className="h-3 w-3" />
                                    </button>
                                </div>
                            )
                        })}
                    </div>

                    <div
                        className={cn(
                            "tab-scroll-fade-left pointer-events-none absolute left-0 top-0 h-full w-6 transition-opacity duration-150",
                            showLeftFade ? "opacity-100" : "opacity-0"
                        )}
                    />
                    <div
                        className={cn(
                            "tab-scroll-fade-right pointer-events-none absolute right-0 top-0 h-full w-6 transition-opacity duration-150",
                            showRightFade ? "opacity-100" : "opacity-0"
                        )}
                    />
                </div>

                <div className="shrink-0 flex items-center h-full bg-transparent">
                    <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                            <button className="h-9 w-9 flex items-center justify-center text-muted-foreground hover:text-foreground hover:bg-muted/50 transition-colors">
                                <MoreHorizontal className="h-4 w-4" />
                            </button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                            <DropdownMenuItem onClick={handleCloseAll}>
                                Close All
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={handleCloseAllSaved}>
                                Close All Saved
                            </DropdownMenuItem>
                        </DropdownMenuContent>
                    </DropdownMenu>
                </div>
            </div>

            <UnsavedChangesDialog
                open={showUnsavedDialog}
                fileName={pendingClosePath?.split('/').pop() || 'file'}
                onCancel={handleCancelClose}
                onDiscard={handleDiscardAndClose}
                onSave={handleSaveAndClose}
            />
        </>
    )
}

import { useEffect, useMemo, useState } from 'react'
import { Button } from '@/components/ui/button'
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog'
import { Input } from '@/components/ui/input'
import type { DevCommandSuggestion } from '@shared/electronApiTypes'

interface DevCommandPickerDialogProps {
  open: boolean
  defaultCommand?: string
  suggestions: DevCommandSuggestion[]
  onOpenChange: (open: boolean) => void
  onConfirm: (command: string) => void
}

function formatConfidence(value: number): string {
  const clamped = Math.max(0, Math.min(1, value))
  return `${Math.round(clamped * 100)}%`
}

export function DevCommandPickerDialog({
  open,
  defaultCommand,
  suggestions,
  onOpenChange,
  onConfirm,
}: DevCommandPickerDialogProps) {
  const [command, setCommand] = useState(defaultCommand ?? '')

  useEffect(() => {
    if (open) {
      setCommand(defaultCommand ?? '')
    }
  }, [defaultCommand, open])

  const orderedSuggestions = useMemo(
    () => [...suggestions].sort((a, b) => b.confidence - a.confidence).slice(0, 6),
    [suggestions]
  )

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>Select Dev Command</DialogTitle>
          <DialogDescription>
            Cozea could not confidently pick a dev server command. Choose one to run.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-3">
          {orderedSuggestions.length > 0 ? (
            <div className="space-y-2">
              {orderedSuggestions.map((suggestion) => (
                <button
                  key={`${suggestion.command}:${suggestion.reason}`}
                  type="button"
                  className="w-full rounded-md border px-3 py-2 text-left text-sm hover:bg-muted/50"
                  onClick={() => setCommand(suggestion.command)}
                >
                  <div className="flex items-center justify-between gap-3">
                    <code className="truncate text-xs">{suggestion.command}</code>
                    <span className="text-[11px] text-muted-foreground">
                      {formatConfidence(suggestion.confidence)}
                    </span>
                  </div>
                  <p className="mt-1 text-[11px] text-muted-foreground">{suggestion.reason}</p>
                </button>
              ))}
            </div>
          ) : null}

          <Input
            value={command}
            onChange={(event) => setCommand(event.target.value)}
            placeholder="npm run dev"
          />
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button
            onClick={() => onConfirm(command.trim())}
            disabled={!command.trim()}
          >
            Run Command
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

import { useEffect, useState } from 'react'
import { useMutation, useQuery } from 'convex/react'
import { ChevronDown, X } from 'lucide-react'
import type { Id } from '../../../../convex/_generated/dataModel'
import { api } from '../../../../convex/_generated/api'

import { Button } from '@/components/ui/button'
import { Checkbox } from '@/components/ui/checkbox'
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from '@/components/ui/collapsible'
import { useAuth } from '@/contexts/AuthContext'
import { cn } from '@/lib/utils'
import {
  applyTaskOverlayCheckedMarkerIds,
  getSyntheticOverlaySource,
  type TaskOverlayMarker,
  type TaskOverlayPayload,
} from '@/features/projects/lib/taskFocusOverlay'

interface TaskFocusOverlayProps {
  task: TaskOverlayPayload | null | undefined
  className?: string
}

export function TaskFocusOverlay({ task, className }: TaskFocusOverlayProps) {
  const { convexUserId } = useAuth()
  const [isOpen, setIsOpen] = useState(true)
  const [isDismissed, setIsDismissed] = useState(false)
  const updateManualTask = useMutation(api.projectTasks.setManualTaskCheckedMarkers)
  const updateSharedTask = useMutation(api.projectTasks.setSharedTaskCheckedMarkers)
  const overlayState = useQuery(
    api.projectTasks.getOverlayTaskState,
    task && convexUserId
      ? {
          projectId: task.projectId as Id<'projects'>,
          viewerUserId: convexUserId,
          source: task.source,
          storageId: task.storageId,
        }
      : 'skip',
  )
  const [markers, setMarkers] = useState<TaskOverlayMarker[]>(() =>
    applyTaskOverlayCheckedMarkerIds(task, overlayState?.checkedMarkerIds),
  )

  useEffect(() => {
    setIsOpen(true)
    setIsDismissed(false)
  }, [task])

  useEffect(() => {
    setMarkers(applyTaskOverlayCheckedMarkerIds(task, overlayState?.checkedMarkerIds))
  }, [overlayState?.checkedMarkerIds, task])

  if (!task || isDismissed) return null
  const activeTask = task

  const checkedCount = markers.filter((marker) => marker.checked).length

  function handleToggleMarker(markerId: string): void {
    if (!convexUserId) return

    const previousMarkers = markers
    const nextMarkers = markers.map((marker) =>
      marker.id === markerId
        ? {
            ...marker,
            checked: !marker.checked,
          }
        : marker,
    )
    const checkedMarkerIds = nextMarkers
      .filter((marker) => marker.checked)
      .map((marker) => marker.id)

    setMarkers(nextMarkers)

    const persist = async () => {
      try {
        if (activeTask.source === 'manual') {
          await updateManualTask({
            projectId: activeTask.projectId as Id<'projects'>,
            actorUserId: convexUserId,
            taskKey: activeTask.storageId,
            checkedMarkerIds,
          })
          return
        }

        const source = getSyntheticOverlaySource(activeTask.source)
        if (!source) return

        await updateSharedTask({
          projectId: activeTask.projectId as Id<'projects'>,
          actorUserId: convexUserId,
          source,
          storageId: activeTask.storageId,
          totalMarkerCount: activeTask.markers.length,
          checkedMarkerIds,
          taskTitle: activeTask.title,
          taskContext: activeTask.context,
        })
      } catch {
        setMarkers(previousMarkers)
      }
    }

    void persist()
  }

  return (
    <div
      className={cn(
        'pointer-events-auto absolute bottom-4 right-4 z-20 w-[320px] max-w-[calc(100%-2rem)] rounded-[24px] bg-secondary/95 p-3 shadow-[0_20px_48px_rgba(15,23,42,0.16)] backdrop-blur dark:bg-secondary/80 dark:shadow-[0_24px_56px_rgba(0,0,0,0.42)]',
        className,
      )}
    >
      <Collapsible open={isOpen} onOpenChange={setIsOpen} className="space-y-3">
        <div className="flex items-start gap-2">
          <div className="min-w-0 flex-1">
            <div className="flex items-center gap-2">
              <p className="text-[11px] font-medium text-muted-foreground">Task</p>
              <span className="inline-flex h-5 min-w-5 items-center justify-center rounded-full bg-sidebar-accent/80 px-1.5 text-[10px] tabular-nums text-sidebar-accent-foreground dark:bg-sidebar-accent">
                {checkedCount}/{markers.length}
              </span>
            </div>
            <h3 className="truncate text-sm font-semibold text-foreground">{activeTask.title}</h3>
          </div>

          <div className="flex items-center gap-1">
            <CollapsibleTrigger asChild>
              <Button variant="ghost" size="icon-sm" className="shrink-0 rounded-full">
                <ChevronDown
                  className={cn('h-4 w-4 transition-transform duration-200', !isOpen && '-rotate-90')}
                />
              </Button>
            </CollapsibleTrigger>
            <Button
              variant="ghost"
              size="icon-sm"
              className="shrink-0 rounded-full"
              onClick={() => setIsDismissed(true)}
            >
              <X className="h-4 w-4" />
            </Button>
          </div>
        </div>

        <CollapsibleContent className="overflow-hidden data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down">
          <div className="space-y-3">
            <p className="line-clamp-2 text-xs leading-5 text-muted-foreground">
              {activeTask.description}
            </p>

            <div className="space-y-1">
              {markers.map((marker) => (
                <label
                  key={marker.id}
                  className="flex cursor-pointer items-center gap-3 rounded-xl px-1 py-1.5 transition-colors hover:bg-background/40"
                >
                  <Checkbox
                    checked={marker.checked}
                    onCheckedChange={() => handleToggleMarker(marker.id)}
                    aria-label={marker.label}
                  />
                  <span
                    className={cn(
                      'text-sm',
                      marker.checked
                        ? 'text-muted-foreground line-through'
                        : 'text-foreground',
                    )}
                  >
                    {marker.label}
                  </span>
                </label>
              ))}
            </div>
          </div>
        </CollapsibleContent>
      </Collapsible>
    </div>
  )
}

