function formatTimeOnly(timestamp: number) {
  const date = new Date(timestamp)
  return date.toLocaleTimeString('en-US', {
    hour: '2-digit',
    minute: '2-digit',
    hour12: true,
  })
}

function formatDateHeader(timestamp: number) {
  const date = new Date(timestamp)
  const today = new Date()
  const yesterday = new Date(today)
  yesterday.setDate(yesterday.getDate() - 1)

  // Reset times to compare dates only
  const dateOnly = new Date(date.getFullYear(), date.getMonth(), date.getDate())
  const todayOnly = new Date(today.getFullYear(), today.getMonth(), today.getDate())
  const yesterdayOnly = new Date(yesterday.getFullYear(), yesterday.getMonth(), yesterday.getDate())

  if (dateOnly.getTime() === todayOnly.getTime()) {
    return 'TODAY'
  } else if (dateOnly.getTime() === yesterdayOnly.getTime()) {
    return 'YESTERDAY'
  } else {
    return date.toLocaleDateString('en-US', {
      day: '2-digit',
      month: 'long',
      year: 'numeric',
    }).toUpperCase().replace(',', '')
  }
}

function getDateKey(timestamp: number) {
  const date = new Date(timestamp)
  return `${date.getFullYear()}-${date.getMonth()}-${date.getDate()}`
}

// Group activity by date
function groupActivityByDate<T extends { timestamp: number }>(items: T[]): { dateHeader: string; items: T[] }[] {
  const groups: Map<string, { dateHeader: string; items: T[] }> = new Map()

  for (const item of items) {
    const key = getDateKey(item.timestamp)
    if (!groups.has(key)) {
      groups.set(key, {
        dateHeader: formatDateHeader(item.timestamp),
        items: [],
      })
    }
    groups.get(key)!.items.push(item)
  }

  return Array.from(groups.values())
}

function getChangeIcon(changeType: string) {
  const baseClasses = 'h-3.5 w-3.5'
  switch (changeType) {
    case 'create':
      return (
        <span className="inline-flex h-5 w-5 items-center justify-center rounded-full bg-secondary">
          <Plus className={`${baseClasses} text-green-500`} />
        </span>
      )
    case 'delete':
      return (
        <span className="inline-flex h-5 w-5 items-center justify-center rounded-full bg-secondary">
          <Minus className={`${baseClasses} text-red-500`} />
        </span>
      )
    case 'modify':
    default:
      return (
        <span className="inline-flex h-5 w-5 items-center justify-center rounded-full bg-secondary">
          <Asterisk className={`${baseClasses} text-amber-500`} />
        </span>
      )
  }
}

function formatRelativeTime(timestamp: number) {
  const now = Date.now()
  const diff = now - timestamp
  const minutes = Math.floor(diff / 60000)
  const hours = Math.floor(diff / 3600000)
  const days = Math.floor(diff / 86400000)

  if (minutes < 1) return 'just now'
  if (minutes < 60) return `${minutes}m ago`
  if (hours < 24) return `${hours}h ago`
  if (days < 7) return `${days}d ago`
  return new Date(timestamp).toLocaleDateString()
}

// Component to display comments for a change
const ChangeComments = memo(function ChangeComments({
  changeId,
  viewerUserId,
  commentCount,
  isSelected,
  shouldPreload,
  expandOnSelect,
}: ChangeCommentsProps) {
  const [isExpanded, setIsExpanded] = useState(false)
  const comments = useQuery(
    api.activity.getCommentsForChange,
    commentCount > 0 && (isExpanded || shouldPreload)
      ? {
          changeId,
          viewerUserId: viewerUserId ?? undefined,
        }
      : "skip"
  ) as ChangeComment[] | undefined
  const addComment = useMutation(api.activity.addComment)
  const toggleCommentReaction = useMutation(api.activity.toggleCommentReaction)
  const [replyingToCommentId, setReplyingToCommentId] = useState<Id<"changeComments"> | null>(null)
  const [replyDraftByComment, setReplyDraftByComment] = useState<Record<string, string>>({})
  const [submittingReplyFor, setSubmittingReplyFor] = useState<string | null>(null)
  const [pendingReactionKey, setPendingReactionKey] = useState<string | null>(null)

  useEffect(() => {
    if (isSelected && expandOnSelect) {
      setIsExpanded(true)
    }
  }, [expandOnSelect, isSelected])

  const commentsByParent = useMemo(() => {
    const grouped = new Map<string, ChangeComment[]>()
    if (!comments) return grouped

    for (const comment of comments) {
      const key = comment.parentCommentId?.toString() ?? "__root__"
      const bucket = grouped.get(key) ?? []
      bucket.push(comment)
      grouped.set(key, bucket)
    }

    return grouped
  }, [comments])

  const topLevelComments = commentsByParent.get("__root__") ?? []

  const handleToggleReaction = async (
    commentId: Id<"changeComments">,
    emoji: string
  ) => {
    if (!viewerUserId) return
    const pendingKey = `${commentId}:${emoji}`
    setPendingReactionKey(pendingKey)
    try {
      await toggleCommentReaction({
        commentId,
        userId: viewerUserId,
        emoji,
      })
    } catch (error) {
      console.error("Failed to toggle comment reaction:", error)
    } finally {
      setPendingReactionKey((current) => (current === pendingKey ? null : current))
    }
  }

  const handleSubmitReply = async (parentCommentId: Id<"changeComments">) => {
    if (!viewerUserId) return
    const draft = replyDraftByComment[parentCommentId.toString()]?.trim()
    if (!draft) return

    const pendingKey = parentCommentId.toString()
    setSubmittingReplyFor(pendingKey)
    try {
      await addComment({
        changeId,
        userId: viewerUserId,
        content: draft,
        parentCommentId,
      })
      setReplyDraftByComment((current) => ({ ...current, [pendingKey]: "" }))
      setReplyingToCommentId(null)
    } catch (error) {
      console.error("Failed to add reply:", error)
    } finally {
      setSubmittingReplyFor((current) => (current === pendingKey ? null : current))
    }
  }

  if (commentCount <= 0) return null

  const renderComment = (comment: ChangeComment, depth: number) => {
    const nestedReplies =
      depth === 0 ? commentsByParent.get(comment.id.toString()) ?? [] : []
    const replyKey = comment.id.toString()
    const replyDraft = replyDraftByComment[replyKey] ?? ""
    const isReplyComposerOpen = depth === 0 && replyingToCommentId === comment.id
    const isSubmittingReply = submittingReplyFor === replyKey
    const thumbsReaction = comment.reactions.find((reaction) => reaction.emoji === "👍")
    const nonThumbReactions = comment.reactions
      .filter((reaction) => reaction.emoji !== "👍")
      .sort((a, b) => b.count - a.count)
    const reactionPillItems: ChangeCommentReaction[] = [
      {
        emoji: "👍",
        count: thumbsReaction?.count ?? 0,
        reactedByViewer: thumbsReaction?.reactedByViewer ?? false,
      },
      ...nonThumbReactions,
    ]
    const hasManyReactionTypes = reactionPillItems.length > 4

    return (
      <div key={comment.id} className={cn("flex gap-3", depth === 0 ? "pb-4" : "pb-3")}>
        {comment.userImage ? (
          <img
            src={comment.userImage}
            alt={comment.userName}
            className="h-8 w-8 rounded-full object-cover shrink-0"
          />
        ) : (
          <div
            className="h-8 w-8 rounded-full flex items-center justify-center text-xs font-medium text-white shrink-0"
            style={{ backgroundColor: comment.userColor }}
          >
            {comment.userName?.charAt(0).toUpperCase() || 'U'}
          </div>
        )}

        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-1.5 mb-1 min-w-0">
            <span className="text-sm font-semibold truncate shrink min-w-0">{comment.userName}</span>
            <span className="text-xs text-muted-foreground shrink-0">•</span>
            <span className="text-xs text-muted-foreground shrink-0 whitespace-nowrap">
              {formatRelativeTime(comment.createdAt)}
            </span>
          </div>

          <CommentRichText
            content={comment.content}
            className="text-sm text-foreground/90 mb-3"
          />

          <div className="flex items-center gap-2">
            <div
              className={cn(
                "inline-flex rounded-full bg-muted/50 p-1",
                hasManyReactionTypes && "max-w-[220px] overflow-x-auto scrollbar-hide"
              )}
            >
              <div className="inline-flex items-center gap-1">
                {reactionPillItems.map((reaction) => (
                  <button
                    key={`${comment.id}:${reaction.emoji}`}
                    type="button"
                    onClick={() => void handleToggleReaction(comment.id, reaction.emoji)}
                    disabled={!viewerUserId || pendingReactionKey === `${comment.id}:${reaction.emoji}`}
                    className="inline-flex items-center gap-1 whitespace-nowrap rounded-full px-2 py-1 text-xs text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
                  >
                    <span>{reaction.emoji}</span>
                    <span>{reaction.count}</span>
                  </button>
                ))}
              </div>
            </div>

            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <button
                  type="button"
                  disabled={!viewerUserId}
                  className="inline-flex items-center gap-1 px-3 py-1.5 rounded-full bg-muted/50 hover:bg-muted text-sm text-muted-foreground hover:text-foreground transition-colors disabled:opacity-50"
                >
                  <Smile className="h-4 w-4" />
                  <span>+</span>
                </button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="start" className="min-w-0">
                {["❤️", "🎉", "😄", "🚀"].map((emoji) => (
                  <DropdownMenuItem
                    key={emoji}
                    onClick={() => void handleToggleReaction(comment.id, emoji)}
                    disabled={pendingReactionKey === `${comment.id}:${emoji}`}
                    className="text-base"
                  >
                    {emoji}
                  </DropdownMenuItem>
                ))}
              </DropdownMenuContent>
            </DropdownMenu>

            {depth === 0 && (
              <>
                <span className="text-muted-foreground/50">•</span>

                <button
                  type="button"
                  onClick={() => setReplyingToCommentId(comment.id)}
                  disabled={!viewerUserId}
                  className="text-sm text-muted-foreground hover:text-foreground transition-colors disabled:opacity-50"
                >
                  Reply
                </button>
              </>
            )}
          </div>

          {isReplyComposerOpen && (
            <div className="mt-3 rounded-lg border border-border/60 bg-muted/20 p-3 space-y-2">
              <Textarea
                value={replyDraft}
                onChange={(event) =>
                  setReplyDraftByComment((current) => ({
                    ...current,
                    [replyKey]: event.target.value,
                  }))
                }
                onKeyDown={(event) => {
                  if (event.key === 'Enter' && (event.metaKey || event.ctrlKey)) {
                    event.preventDefault()
                    void handleSubmitReply(comment.id)
                  }
                }}
                placeholder={`Reply to ${comment.userName}`}
                className="min-h-[72px] resize-none border-0 focus-visible:ring-0 focus-visible:ring-offset-0 rounded-md bg-background"
                disabled={isSubmittingReply}
              />
              <div className="flex items-center justify-end gap-2">
                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => {
                    setReplyingToCommentId(null)
                    setReplyDraftByComment((current) => ({ ...current, [replyKey]: "" }))
                  }}
                  disabled={isSubmittingReply}
                >
                  Cancel
                </Button>
                <Button
                  size="sm"
                  onClick={() => void handleSubmitReply(comment.id)}
                  disabled={!viewerUserId || !replyDraft.trim() || isSubmittingReply}
                >
                  Send Reply
                </Button>
              </div>
            </div>
          )}

          {nestedReplies.length > 0 && (
            <div className="mt-3 border-l border-border/60 pl-4 space-y-3">
              {nestedReplies.map((reply) => renderComment(reply, depth + 1))}
            </div>
          )}
        </div>
      </div>
    )
  }

  return (
    <div className="ml-[88px] mt-2 mb-3">
      <button
        type="button"
        onClick={(event) => {
          event.stopPropagation()
          setIsExpanded((current) => !current)
        }}
        className="text-xs font-medium text-muted-foreground hover:text-foreground mb-2 flex items-center gap-1"
      >
        {isExpanded ? 'Hide' : 'Show'} {commentCount} {commentCount === 1 ? 'comment' : 'comments'}
      </button>
      <div
        aria-hidden={!isExpanded}
        className={cn(
          "grid overflow-hidden transition-[grid-template-rows,opacity,transform] duration-300 ease-out",
          isExpanded
            ? "grid-rows-[1fr] opacity-100 translate-y-0"
            : "grid-rows-[0fr] opacity-0 -translate-y-1"
        )}
      >
        <div className="min-h-0">
          <div className="relative min-h-12">
            {comments === undefined ? (
              <Shimmer className="text-xs text-muted-foreground">Loading comments…</Shimmer>
            ) : comments.length === 0 ? (
              <p className="text-xs text-muted-foreground">No comments yet.</p>
            ) : (
              <>
                <div className="absolute left-[19px] top-0 bottom-0 flex flex-col items-center pointer-events-none">
                  <div className="w-2 h-2 rounded-full bg-border shrink-0" />
                  <div
                    className="w-px flex-1 border-l border-dashed border-border"
                    style={{
                      maskImage: 'linear-gradient(to bottom, black 0%, black 60%, transparent 100%)',
                      WebkitMaskImage: 'linear-gradient(to bottom, black 0%, black 60%, transparent 100%)',
                    }}
                  />
                </div>

                <div className="space-y-0 pl-12">
                  {topLevelComments.map((comment) => renderComment(comment, 0))}
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  )
})
ChangeComments.displayName = "ChangeComments"

export function ChangesPage() {
  const [searchParams, setSearchParams] = useSearchParams()
  const { convexUserId } = useAuth()
  const { project } = useAccessibleProject()
  const [selectedChangeId, setSelectedChangeId] = useState<Id<"fileChanges"> | null>(null)
  const [selectionWasUserDriven, setSelectionWasUserDriven] = useState(false)
  const [backgroundPreloadIds, setBackgroundPreloadIds] = useState<Id<"fileChanges">[]>([])
  const selectedUserId = searchParams.get('userId')

  // Get activity feed
  const activity = useQuery(
    api.activity.getRecentActivity,
    project?._id ? { projectId: project._id, limit: 100 } : 'skip'
  ) as ActivityFeedItem[] | undefined

  const filteredActivity = useMemo(() => {
    if (!activity) return activity
    if (!selectedUserId) return activity
    return activity.filter((item) => item.userId === selectedUserId)
  }, [activity, selectedUserId])

  const selectedFilterUserName = useMemo(() => {
    if (!selectedUserId || !activity) return null
    return activity.find((item) => item.userId === selectedUserId)?.userName ?? null
  }, [activity, selectedUserId])

  // Get comment counts for all changes
  const changeIds = useMemo(
    () => filteredActivity?.map((item) => item.id as Id<"fileChanges">) ?? [],
    [filteredActivity]
  )
  const commentCounts = useQuery(
    api.activity.getCommentCountsForChanges,
    changeIds.length > 0 ? { changeIds } : 'skip'
  )
  const selectedChange = useQuery(
    api.activity.getChangeWithContent,
    selectedChangeId ? { changeId: selectedChangeId } : 'skip'
  ) as SelectedChangeSummary | null | undefined
  const showSplitPane = Boolean(selectedChangeId)
  const [cachedSelectedChange, setCachedSelectedChange] = useState<SelectedChangeSummary | null>(null)
  const displayedSelectedChange = selectedChange ?? cachedSelectedChange
  const isSelectedChangeLoading = Boolean(selectedChangeId) && selectedChange === undefined
  const groupedActivity = useMemo(
    () => (filteredActivity ? groupActivityByDate(filteredActivity) : []),
    [filteredActivity]
  )
  const latestChangeId = filteredActivity?.[0]?.id as Id<"fileChanges"> | undefined
  const backgroundPreloadIdSet = useMemo(
    () => new Set(backgroundPreloadIds.map((id) => id.toString())),
    [backgroundPreloadIds]
  )

  useEffect(() => {
    if (!selectedChangeId) {
      setCachedSelectedChange(null)
      return
    }

    if (selectedChange) {
      setCachedSelectedChange(selectedChange)
      return
    }

    if (selectedChange === null) {
      setCachedSelectedChange(null)
    }
  }, [selectedChange, selectedChangeId])

  // Auto-select the most recent change when activity loads
  useEffect(() => {
    if (!filteredActivity || filteredActivity.length === 0) {
      setSelectionWasUserDriven(false)
      setSelectedChangeId(null)
      return
    }

    const selectedStillVisible = selectedChangeId
      ? filteredActivity.some((item) => item.id === selectedChangeId)
      : false

    if (selectedChangeId === null || !selectedStillVisible) {
      setSelectionWasUserDriven(false)
      setSelectedChangeId(filteredActivity[0].id as Id<"fileChanges">)
    }
  }, [filteredActivity, selectedChangeId])

  useEffect(() => {
    if (!filteredActivity || filteredActivity.length === 0 || !latestChangeId) {
      setBackgroundPreloadIds([])
      return
    }

    const deferredIds = filteredActivity
      .map((item) => item.id as Id<"fileChanges">)
      .filter((id) => id !== latestChangeId)

    if (deferredIds.length === 0) {
      setBackgroundPreloadIds([])
      return
    }

    setBackgroundPreloadIds([])

    const preloadBatchSize = 6
    let cursor = 0
    let cancelled = false
    const canUseIdleCallbacks =
      typeof window !== "undefined" &&
      typeof window.requestIdleCallback === "function" &&
      typeof window.cancelIdleCallback === "function"
    const idleHandles: number[] = []
    const timeoutHandles: Array<ReturnType<typeof setTimeout>> = []

    const preloadNextBatch = () => {
      if (cancelled || cursor >= deferredIds.length) return

      const batch = deferredIds.slice(cursor, cursor + preloadBatchSize)
      cursor += preloadBatchSize

      setBackgroundPreloadIds((current) => {
        if (batch.length === 0) return current
        const existing = new Set(current.map((id) => id.toString()))
        const next = [...current]
        for (const id of batch) {
          const key = id.toString()
          if (!existing.has(key)) {
            existing.add(key)
            next.push(id)
          }
        }
        return next
      })

      scheduleNextBatch()
    }

    const scheduleNextBatch = () => {
      if (cancelled || cursor >= deferredIds.length) return
      if (canUseIdleCallbacks) {
        const handle = window.requestIdleCallback(
          () => preloadNextBatch(),
          { timeout: 1200 }
        )
        idleHandles.push(handle)
        return
      }

      const timeoutHandle = globalThis.setTimeout(() => preloadNextBatch(), 120)
      timeoutHandles.push(timeoutHandle)
    }

    scheduleNextBatch()

    return () => {
      cancelled = true
      if (canUseIdleCallbacks) {
        for (const handle of idleHandles) {
          window.cancelIdleCallback(handle)
        }
      }
      for (const handle of timeoutHandles) {
        globalThis.clearTimeout(handle)
      }
    }
  }, [filteredActivity, latestChangeId])

  // Mark sync feed as seen when page loads
  useEffect(() => {
    if (project?.slug) {
      markSyncFeedAsSeen(project.slug)
    }
  }, [project?.slug])

  const headerControls = useMemo(
    () => (
      <div className="flex items-center gap-2">
        {selectedChangeId && displayedSelectedChange && (
          <>
            <div className="flex items-center gap-2 min-w-0 max-w-[420px]">
              {getChangeIcon(displayedSelectedChange.changeType)}
              <span className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-muted text-xs min-w-0 max-w-[260px]">
                {getFileIcon(displayedSelectedChange.filePath.split('/').pop() || displayedSelectedChange.filePath, {
                  width: 14,
                  height: 14,
                })}
                <span className="truncate">
                  {displayedSelectedChange.filePath.split('/').pop() || displayedSelectedChange.filePath}
                </span>
              </span>
              {isSelectedChangeLoading && (
                <Shimmer className="text-[11px] text-muted-foreground">Updating…</Shimmer>
              )}
            </div>
            <div className="flex items-center gap-1.5 shrink-0">
              {displayedSelectedChange.userImage ? (
                <img
                  src={displayedSelectedChange.userImage}
                  alt={displayedSelectedChange.userName}
                  className="h-4 w-4 rounded-full object-cover"
                  title={displayedSelectedChange.userName}
                />
              ) : (
                <div
                  className="h-4 w-4 rounded-full flex items-center justify-center text-[9px] font-medium text-white"
                  style={{ backgroundColor: displayedSelectedChange.userColor }}
                  title={displayedSelectedChange.userName}
                >
                  {displayedSelectedChange.userName?.charAt(0).toUpperCase() || 'U'}
                </div>
              )}
              <span className="text-xs text-muted-foreground">
                {formatRelativeTime(displayedSelectedChange.timestamp)}
              </span>
            </div>
          </>
        )}
        {selectedChangeId && !displayedSelectedChange && (
          <Shimmer className="text-xs text-muted-foreground">Loading selected change…</Shimmer>
        )}
        {!selectedChangeId && (
          <span className="text-xs text-muted-foreground">Select a change to view diff</span>
        )}
      </div>
    ),
    [displayedSelectedChange, isSelectedChangeLoading, selectedChangeId]
  )

  useProjectHeader(headerControls)

  return (
    <div className="relative flex h-full min-h-0 overflow-hidden bg-content-surface">
      {/* Timeline Panel */}
      <div className={`flex min-h-0 min-w-0 overflow-hidden flex-col ${showSplitPane ? 'w-1/2' : 'w-full'} transition-all`}>
        {/* Timeline Content */}
        <div className="relative flex-1 min-h-0">
          <ScrollArea className="h-full">
            <div className="p-4">
              {!project?._id ? (
                null
              ) : filteredActivity === undefined ? (
                null
              ) : filteredActivity.length === 0 ? (
                <Card className="p-12 text-center">
                  <Activity className="h-12 w-12 mx-auto mb-4 text-muted-foreground opacity-50" />
                  <h3 className="text-lg font-medium mb-2">No Changes Yet</h3>
                  <p className="text-sm text-muted-foreground">
                    {selectedUserId
                      ? "No changes found for this user in the current feed window."
                      : "File changes will appear here in real-time as you and your team edit files."}
                  </p>
                </Card>
              ) : (
                <div className="space-y-6">
                  {selectedUserId && (
                    <div className="flex items-center gap-2">
                      <Badge variant="outline" className="text-[11px]">
                        {selectedFilterUserName
                          ? `Filtered by ${selectedFilterUserName}`
                          : "Filtered by selected user"}
                      </Badge>
                      <Button
                        variant="ghost"
                        size="sm"
                        className="h-6 px-2 text-[11px]"
                        onClick={() => {
                          const nextParams = new URLSearchParams(searchParams)
                          nextParams.delete('userId')
                          setSearchParams(nextParams, { replace: true })
                        }}
                      >
                        Clear filter
                      </Button>
                    </div>
                  )}
                  {groupedActivity.map((group) => (
                    <div key={group.dateHeader}>
                      {/* Date Header */}
                      <div className="flex items-center gap-3 mb-3">
                        <span className="text-xs font-semibold text-muted-foreground tracking-wider">
                          {group.dateHeader}
                        </span>
                        <div className="flex-1 h-px bg-border" />
                      </div>

                      {/* Items for this date */}
                      <div className="space-y-1">
                        {group.items.map((item) => {
                          const rowChangeId = item.id as Id<"fileChanges">
                          const shouldPreloadRowComments =
                            rowChangeId === latestChangeId ||
                            backgroundPreloadIdSet.has(rowChangeId.toString())

                          return (
                            <div key={item.id}>
                            <div
                              onClick={() => {
                                setSelectionWasUserDriven(true)
                                setSelectedChangeId(rowChangeId)
                              }}
                              className={`
                                flex items-start gap-3 py-2 px-3 rounded-full cursor-pointer transition-colors
                                ${selectedChangeId === item.id
                                  ? 'bg-primary/10'
                                  : 'hover:bg-muted/50'
                                }
                              `}
                            >
                              {/* Time Column */}
                              <div className="w-20 shrink-0 pt-1 mr-2">
                                <span className="text-sm text-muted-foreground whitespace-nowrap">
                                  {formatTimeOnly(item.timestamp)}
                                </span>
                              </div>

                              {/* Avatar */}
                              <div className="shrink-0 pt-0.5">
                                {item.userImage ? (
                                  <img
                                    src={item.userImage}
                                    alt={item.userName}
                                    className="w-8 h-8 rounded-full object-cover"
                                  />
                                ) : (
                                  <div
                                    className="w-8 h-8 rounded-full flex items-center justify-center text-xs font-medium text-white"
                                    style={{ backgroundColor: item.userColor }}
                                  >
                                    {item.isAgent ? (
                                      <Bot className="h-4 w-4" />
                                    ) : (
                                      item.userName?.charAt(0).toUpperCase() || 'U'
                                    )}
                                  </div>
                                )}
                              </div>

                              {/* Content - single line */}
                              <div className="flex-1 min-w-0 flex items-center gap-2 pt-1.5">
                                <span className="font-medium text-sm truncate max-w-[120px]" title={item.userName}>
                                  {item.userName}
                                </span>
                                {getChangeIcon(item.changeType)}
                                <span className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-muted text-xs shrink min-w-0 max-w-[180px]">
                                  {getFileIcon(item.filePath.split('/').pop() || item.filePath, { width: 14, height: 14 })}
                                  <span className="truncate">{item.filePath.split('/').pop()}</span>
                                </span>
                                {item.isAgent && (
                                  <Badge variant="outline" className="text-[10px] px-1 py-0">
                                    AI
                                  </Badge>
                                )}
                                {(item.additions !== undefined && item.additions > 0) && (
                                  <span className="text-xs text-green-500">+{item.additions}</span>
                                )}
                                {(item.deletions !== undefined && item.deletions > 0) && (
                                  <span className="text-xs text-red-500">-{item.deletions}</span>
                                )}
                                {commentCounts && commentCounts[item.id] > 0 && (
                                  <span className="inline-flex items-center gap-1 text-xs text-muted-foreground ml-auto">
                                    <MessageSquare className="h-3 w-3" />
                                    {commentCounts[item.id]}
                                  </span>
                                )}
                              </div>
                            </div>
                            {/* Comments under this change */}
                            {commentCounts && commentCounts[item.id] > 0 && (
                              <ChangeComments
                                changeId={rowChangeId}
                                viewerUserId={convexUserId ?? null}
                                commentCount={commentCounts[item.id]}
                                isSelected={selectedChangeId === item.id}
                                shouldPreload={shouldPreloadRowComments}
                                expandOnSelect={selectionWasUserDriven && selectedChangeId === item.id}
                              />
                            )}
                          </div>
                          )
                        })}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </ScrollArea>
          <div className="pointer-events-none absolute left-0 right-0 top-0 h-8 bg-gradient-to-b from-content-surface to-transparent z-10" />
          <div className="pointer-events-none absolute left-0 right-0 bottom-0 h-8 bg-gradient-to-t from-content-surface to-transparent z-10" />
        </div>
      </div>

      {/* Diff Panel */}
      {showSplitPane && (
        <div className="w-1/2 min-h-0 min-w-0 overflow-hidden bg-background">
          {selectedChangeId ? (
            <DiffPanel
              changeId={selectedChangeId}
              onClose={() => setSelectedChangeId(null)}
              showHeader={false}
            />
          ) : null}
        </div>
      )}
      {showSplitPane && (
        <div className="pointer-events-none absolute inset-y-0 left-1/2 z-20 -translate-x-1/2">
          <div
            className="h-full w-px bg-border"
            style={{
              maskImage: 'linear-gradient(to bottom, transparent 0%, black 10%, black 90%, transparent 100%)',
              WebkitMaskImage: 'linear-gradient(to bottom, transparent 0%, black 10%, black 90%, transparent 100%)',
            }}
          />
        </div>
      )}
    </div>
  )
}

import { useState, useCallback, useMemo, useEffect } from 'react'
import { useProjectHeader } from '@/hooks/useProjectHeader'
import { Button } from '@/components/ui/button'
import { Card } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { useOptionalProjectSyncContext } from '../contexts/ProjectSyncContext'
import { DependenciesAddDialog } from '../components/DependenciesAddDialog'
import { useDependenciesStore, selectDependenciesSnapshot, selectDependencyJobs } from '@/stores/useDependenciesStore'
import {
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import {
  Package,
  RefreshCw,
  Plus,
  Loader2,
  ArrowUp,
  Trash2,
  MoreHorizontal,
  List,
  ChevronLeft,
  ChevronRight,
} from 'lucide-react'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import { useAccessibleProject } from '@/features/projects/hooks/useAccessibleProject'


export function ProjectDependenciesPage() {
  const { project } = useAccessibleProject()
  const syncContext = useOptionalProjectSyncContext()
  const projectPath = syncContext?.projectPath ?? null
  const [filter, setFilter] = useState<'all' | 'dependencies' | 'devDependencies'>('all')
  const [statusFilter, setStatusFilter] = useState<'all' | 'outdated' | 'missing'>('all')
  const [currentPage, setCurrentPage] = useState(1)
  const [addDialogOpen, setAddDialogOpen] = useState(false)
  const ITEMS_PER_PAGE = 10

  const snapshot = useDependenciesStore(selectDependenciesSnapshot(projectPath))
  const jobs = useDependenciesStore(selectDependencyJobs(projectPath))
  const setSnapshot = useDependenciesStore((state) => state.actions.setSnapshot)
  const setError = useDependenciesStore((state) => state.actions.setError)
  const dependencies = useMemo(() => snapshot?.items ?? [], [snapshot?.items])
  const error = snapshot?.error ?? null
  const runningJobs = jobs.filter((job) => job.status === 'running')

  const sortedDeps = useMemo(() => {
    return [...dependencies].sort((a, b) => a.name.localeCompare(b.name))
  }, [dependencies])

  const filteredDeps = sortedDeps.filter((dep) => {
    if (filter === 'dependencies' && dep.type !== 'dependency') return false
    if (filter === 'devDependencies' && dep.type !== 'devDependency') return false
    if (statusFilter === 'outdated' && dep.status !== 'outdated') return false
    if (statusFilter === 'missing' && dep.status !== 'missing') return false
    return true
  })

  const prodCount = dependencies.filter(d => d.type === 'dependency').length
  const devCount = dependencies.filter(d => d.type === 'devDependency').length

  // Pagination
  const totalPages = Math.ceil(filteredDeps.length / ITEMS_PER_PAGE)
  const paginatedDeps = useMemo(() => {
    const startIndex = (currentPage - 1) * ITEMS_PER_PAGE
    return filteredDeps.slice(startIndex, startIndex + ITEMS_PER_PAGE)
  }, [filteredDeps, currentPage])

  // Reset page when filter changes
  useEffect(() => {
    setCurrentPage(1)
  }, [filter, statusFilter])

  useEffect(() => {
    if (totalPages > 0 && currentPage > totalPages) {
      setCurrentPage(totalPages)
    }
  }, [currentPage, totalPages])

  const inspectNow = useCallback(async () => {
    if (!projectPath || !window.electronAPI?.dependencies) return
    try {
      const result = await window.electronAPI.dependencies.inspect({ projectPath })
      if (result.success && result.snapshot) {
        setSnapshot(projectPath, result.snapshot)
      } else if (result.error) {
        setError(projectPath, result.error)
      }
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Failed to inspect dependencies'
      setError(projectPath, message)
    }
  }, [projectPath, setError, setSnapshot])

  // Generate page numbers with ellipsis
  const getPageNumbers = () => {
    const pages: (number | 'ellipsis')[] = []
    if (totalPages <= 5) {
      for (let i = 1; i <= totalPages; i++) pages.push(i)
    } else {
      if (currentPage <= 3) {
        pages.push(1, 2, 3, 'ellipsis', totalPages)
      } else if (currentPage >= totalPages - 2) {
        pages.push(1, 'ellipsis', totalPages - 2, totalPages - 1, totalPages)
      } else {
        pages.push(1, 'ellipsis', currentPage, 'ellipsis', totalPages)
      }
    }
    return pages
  }

  const handleRefresh = useCallback(() => {
    void inspectNow()
  }, [inspectNow])

  const handleAdd = useCallback(async (name: string, options: { dev?: boolean; version?: string }) => {
    if (!projectPath || !window.electronAPI?.dependencies) return
    const result = await window.electronAPI.dependencies.run({
      projectPath,
      action: 'add',
      packageName: name,
      version: options.version,
      dev: options.dev,
    })
    if (!result.success && result.error) {
      setError(projectPath, result.error)
    }
  }, [projectPath, setError])

  const handleUpdate = useCallback(async (name: string, updateMode: 'latest' | 'range') => {
    if (!projectPath || !window.electronAPI?.dependencies) return
    const result = await window.electronAPI.dependencies.run({
      projectPath,
      action: 'update',
      packageName: name,
      updateMode,
    })
    if (!result.success && result.error) {
      setError(projectPath, result.error)
    }
  }, [projectPath, setError])

  const handleRemove = useCallback(async (name: string) => {
    if (!projectPath || !window.electronAPI?.dependencies) return
    const result = await window.electronAPI.dependencies.run({
      projectPath,
      action: 'remove',
      packageName: name,
    })
    if (!result.success && result.error) {
      setError(projectPath, result.error)
    }
  }, [projectPath, setError])

  const headerControls = useMemo(
    () => (
      <div className="flex items-center gap-1.5">
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="secondary" size="sm" className="h-7 gap-1.5 rounded-full px-2.5 text-xs">
              <Package className="h-3 w-3" />
              {filter === 'all' ? `All (${dependencies.length})` : filter === 'dependencies' ? `Dependencies (${prodCount})` : `Dev (${devCount})`}
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            <DropdownMenuItem onClick={() => setFilter('all')}>All ({dependencies.length})</DropdownMenuItem>
            <DropdownMenuItem onClick={() => setFilter('dependencies')}>Dependencies ({prodCount})</DropdownMenuItem>
            <DropdownMenuItem onClick={() => setFilter('devDependencies')}>Dev ({devCount})</DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
        <Tooltip>
          <TooltipTrigger asChild>
            <span>
              <Button
                variant="secondary"
                size="sm"
                onClick={handleRefresh}
                className="h-7 rounded-full px-2"
                disabled={!projectPath}
                aria-label="Refresh dependencies"
              >
                <RefreshCw className="h-3 w-3" />
              </Button>
            </span>
          </TooltipTrigger>
          <TooltipContent side="bottom">Refresh dependencies</TooltipContent>
        </Tooltip>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="outline" size="sm" className="h-7 gap-1.5 rounded-full px-2.5 text-xs">
              <List className="h-3 w-3" />
              {statusFilter === 'all' ? 'All statuses' : statusFilter === 'outdated' ? 'Outdated' : 'Missing'}
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            <DropdownMenuItem onClick={() => setStatusFilter('all')}>All statuses</DropdownMenuItem>
            <DropdownMenuItem onClick={() => setStatusFilter('outdated')}>Outdated</DropdownMenuItem>
            <DropdownMenuItem onClick={() => setStatusFilter('missing')}>Missing</DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
        <Button size="sm" className="h-7 gap-1.5 rounded-full px-2.5 text-xs" onClick={() => setAddDialogOpen(true)} disabled={!projectPath}>
          <Plus className="h-3.5 w-3.5" />
          Add Package
        </Button>
      </div>
    ),
    [
      dependencies.length,
      devCount,
      filter,
      handleRefresh,
      projectPath,
      prodCount,
      statusFilter,
    ]
  )

  useProjectHeader(headerControls)

  if (project === undefined) {
    return (
      <div className="flex items-center justify-center h-full">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    )
  }

  return (
    <div className="flex flex-col h-full bg-content-surface">
      {/* Scrollable Content */}
      <div className="app-scrollbar flex-1 overflow-auto min-h-0">
        <div className="px-6 pt-2 pb-4 space-y-2">
          {runningJobs.length > 0 && (
            <Card className="p-3 text-xs flex items-center gap-2">
              <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
              <div>
                Running {runningJobs.length} task{runningJobs.length > 1 ? 's' : ''}…
              </div>
            </Card>
          )}
        </div>

        {/* Error State */}
        {error && (
          <Card className="p-4 mx-6 mt-2 mb-6 border-destructive/50 bg-destructive/10 text-destructive text-sm text-center">
            {error}
          </Card>
        )}

        {/* Dependencies Table */}
        {filteredDeps.length === 0 ? (
          <Card className="p-12 m-6 text-center">
            <Package className="h-12 w-12 mx-auto mb-4 text-muted-foreground opacity-50" />
            <h3 className="text-lg font-medium mb-2">No packages found</h3>
            <p className="text-sm text-muted-foreground">
              No dependencies found in package.json.
            </p>
          </Card>
        ) : (
          <div className="px-4 pb-4">
            <Card className="border-0 shadow-none bg-transparent">
              <div className="relative w-full">
                <div className="overflow-hidden rounded-2xl bg-secondary/80 dark:bg-secondary/40 px-2 py-1">
                  <table className="w-full caption-bottom text-sm [&_th]:px-4 [&_td]:px-4">
                    <TableHeader className="[&_tr]:border-b [&_tr]:border-border/60">
                      <TableRow className="hover:bg-transparent">
                        <TableHead className="w-[280px]">Package</TableHead>
                        <TableHead>Declared</TableHead>
                        <TableHead>Installed</TableHead>
                        <TableHead>Latest</TableHead>
                        <TableHead>Status</TableHead>
                        <TableHead>Type</TableHead>
                        <TableHead className="text-right w-[80px]">Actions</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody className="[&_tr]:border-b [&_tr]:border-border/60 [&_tr:last-child]:border-0">
                      {paginatedDeps.map((dep) => (
                        <TableRow key={dep.name}>
                          <TableCell className="font-medium">
                            <div className="flex items-center gap-2">
                              <Package className="h-4 w-4 text-muted-foreground" />
                              {dep.name}
                            </div>
                          </TableCell>
                          <TableCell>
                            <code className="text-xs bg-muted px-1.5 py-0.5 rounded">
                              {dep.declared}
                            </code>
                          </TableCell>
                          <TableCell>
                            <code className="text-xs bg-muted px-1.5 py-0.5 rounded">
                              {dep.installed ?? '—'}
                            </code>
                          </TableCell>
                          <TableCell>
                            <code className="text-xs bg-muted px-1.5 py-0.5 rounded">
                              {dep.latest ?? '—'}
                            </code>
                          </TableCell>
                          <TableCell>
                            <Badge variant={dep.status === 'outdated' ? 'destructive' : dep.status === 'missing' ? 'secondary' : 'default'}>
                              {dep.status}
                            </Badge>
                          </TableCell>
                          <TableCell>
                            <Badge variant={dep.type === 'dependency' ? 'default' : 'secondary'}>
                              {dep.type === 'dependency'
                                ? 'prod'
                                : dep.type === 'devDependency'
                                  ? 'dev'
                                  : dep.type}
                            </Badge>
                          </TableCell>
                          <TableCell className="text-right">
                            <DropdownMenu>
                              <DropdownMenuTrigger asChild>
                                <Button variant="ghost" size="sm">
                                  <MoreHorizontal className="h-4 w-4" />
                                </Button>
                              </DropdownMenuTrigger>
                              <DropdownMenuContent align="end">
                                <DropdownMenuItem onClick={() => handleUpdate(dep.name, 'latest')}>
                                  <ArrowUp className="h-4 w-4 mr-2" />
                                  Update to Latest
                                </DropdownMenuItem>
                                <DropdownMenuItem onClick={() => handleUpdate(dep.name, 'range')}>
                                  <ArrowUp className="h-4 w-4 mr-2" />
                                  Update within range
                                </DropdownMenuItem>
                                <DropdownMenuSeparator />
                                <DropdownMenuItem className="text-destructive" onClick={() => handleRemove(dep.name)}>
                                  <Trash2 className="h-4 w-4 mr-2" />
                                  Uninstall
                                </DropdownMenuItem>
                              </DropdownMenuContent>
                            </DropdownMenu>
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </table>
                </div>
              </div>
              {filteredDeps.length > ITEMS_PER_PAGE && (
                <div className="mt-4 flex items-center justify-between">
                  <div className="text-sm text-muted-foreground">
                    Showing <span className="font-medium">{((currentPage - 1) * ITEMS_PER_PAGE) + 1}-{Math.min(currentPage * ITEMS_PER_PAGE, filteredDeps.length)}</span> of <span className="font-medium">{filteredDeps.length}</span> entries
                  </div>
                  <div className="flex items-center gap-1">
                    <Button
                      variant="secondary"
                      size="icon"
                      className="h-8 w-8 rounded-full"
                      onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                      disabled={currentPage === 1}
                    >
                      <ChevronLeft className="h-4 w-4" />
                    </Button>
                    {getPageNumbers().map((page, i) => (
                      typeof page === 'number' ? (
                        <Button
                          key={i}
                          variant={currentPage === page ? 'default' : 'secondary'}
                          size="icon"
                          className="h-8 w-8 rounded-full"
                          onClick={() => setCurrentPage(page)}
                        >
                          {page}
                        </Button>
                      ) : (
                        <span key={i} className="px-2 text-muted-foreground">...</span>
                      )
                    ))}
                    <Button
                      variant="secondary"
                      size="icon"
                      className="h-8 w-8 rounded-full"
                      onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
                      disabled={currentPage === totalPages || totalPages === 0}
                    >
                      <ChevronRight className="h-4 w-4" />
                    </Button>
                  </div>
                </div>
              )}
            </Card>
          </div>
        )}
      </div>

      {projectPath && (
        <DependenciesAddDialog
          open={addDialogOpen}
          onOpenChange={setAddDialogOpen}
          projectPath={projectPath}
          onAdd={handleAdd}
        />
      )}
    </div>
  )
}

import { useCallback, useEffect, useState } from 'react'
import { Link, useLocation, useSearchParams } from 'react-router-dom'
import { FileViewer } from '../components/FileViewer'
import { useFileTabsStore } from '@/stores/useFileTabsStore'
import { Button } from '@/components/ui/button'
import { TerminalPanel } from '../components/TerminalPanel'
import { TaskFocusOverlay } from '../components/TaskFocusOverlay'
import {
  ArrowLeft,
  Code,
  Settings,
  Users,
  Clock,
  FolderOpen,
  MousePointerClick,
} from 'lucide-react'
import {
  Empty,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
  EmptyDescription,
} from '@/components/ui/empty'
import { useAccessibleProject } from '@/features/projects/hooks/useAccessibleProject'
import { useOptionalProjectSyncContext } from '../contexts/ProjectSyncContext'
import { buildProjectPath } from '@/features/projects/lib/projectRoutes'
import type { TaskOverlayLocationState, TaskOverlayPayload } from '@/features/projects/lib/taskFocusOverlay'

export function ProjectDetailPage() {
  const { project, slugParam, projectIdParam } = useAccessibleProject()
  const location = useLocation()
  const [, setSearchParams] = useSearchParams()
  const syncContext = useOptionalProjectSyncContext()
  const projectPath = syncContext?.projectPath ?? null
  const projectKey = project?.slug ?? slugParam ?? projectIdParam ?? ''
  const locationState = (location.state as TaskOverlayLocationState | null) ?? null
  const [taskOverlay, setTaskOverlay] = useState<TaskOverlayPayload | null>(
    () => locationState?.taskOverlay ?? null,
  )

  useEffect(() => {
    if (locationState?.taskOverlay) {
      setTaskOverlay(locationState.taskOverlay)
    }
  }, [locationState?.taskOverlay])

  const handleOpenFile = useCallback((file: string, line?: number, column?: number) => {
    const normalizedFile = file.replace(/\\/g, '/')
    const normalizedProject = projectPath
      ? projectPath.replace(/\\/g, '/').replace(/\/+$/, '')
      : null
    const isAbsolute = normalizedFile.startsWith('/') || /^[A-Za-z]:\//.test(normalizedFile)

    const pathForUrl = normalizedProject
      ? (isAbsolute || normalizedFile.startsWith(normalizedProject))
        ? normalizedFile
        : `${normalizedProject}/${normalizedFile.replace(/^\/+/, '')}`
      : normalizedFile

    const params = new URLSearchParams()
    params.set('path', pathForUrl)
    if (line) params.set('line', String(line))
    if (column) params.set('column', String(column))
    setSearchParams(params)
  }, [projectPath, setSearchParams])

  // File tabs store
  const fileTabsStore = useFileTabsStore()
  const { activeFile } = projectKey
    ? fileTabsStore.actions.getProjectTabs(projectKey)
    : { activeFile: null }

  // Loading state - show shell immediately
  // Only show 404 if we are loaded (project === null) and explicitly not found
  if (project === null) {
    return (
      <div className="flex flex-col items-center justify-center h-full py-16 space-y-4">
        <FolderOpen className="h-16 w-16 text-muted-foreground" />
        <h2 className="text-xl font-semibold">Project not found</h2>
        <p className="text-muted-foreground">
          The project you're looking for doesn't exist or has been deleted.
        </p>
        <Button asChild>
          <Link to="/projects">View all projects</Link>
        </Button>
      </div>
    )
  }

  // Ensure stores are initialized even if project is loading (we have the slug)
  if (!projectKey) return null

  // Editor Layout - always shown, with tabs when files are open
  return (
    <div className="flex flex-col h-[calc(100%+2.5rem)] -mt-10 bg-background overflow-hidden">
      {/* Editor Content */}
      <div className="flex-1 min-h-0 relative pt-10">
        {activeFile ? (
          <FileViewer path={activeFile} />
        ) : (
          <Empty className="h-full py-0">
            <EmptyHeader>
              <EmptyMedia>
                <MousePointerClick className="h-8 w-8" />
              </EmptyMedia>
              <EmptyTitle>No file selected</EmptyTitle>
              <EmptyDescription>
                Select a file from the sidebar to start editing.
              </EmptyDescription>
            </EmptyHeader>
          </Empty>
        )}
        {taskOverlay?.context.kind === 'file' ? <TaskFocusOverlay task={taskOverlay} /> : null}
      </div>

      {projectPath && (
        <TerminalPanel projectPath={projectPath} onOpenFile={handleOpenFile} />
      )}

    </div>
  )
}

// Format dates
const formatDate = (timestamp: number) => {
  return new Date(timestamp).toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  })
}

const formatRelativeTime = (timestamp: number) => {
  const now = Date.now()
  const diffMs = now - timestamp
  const diffMins = Math.floor(diffMs / 60000)
  const diffHours = Math.floor(diffMs / 3600000)
  const diffDays = Math.floor(diffMs / 86400000)

  if (diffMins < 1) return 'Just now'
  if (diffMins < 60) return `${diffMins} min ago`
  if (diffHours < 24) return `${diffHours} hour${diffHours > 1 ? 's' : ''} ago`
  if (diffDays < 7) return `${diffDays} day${diffDays > 1 ? 's' : ''} ago`
  return formatDate(timestamp)
}

// Dashboard component - can be used separately or on a different route
export function ProjectDashboard() {
  const { project } = useAccessibleProject()

  if (!project) return null

  return (
    <div className="space-y-6 p-6">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" asChild>
          <Link to="/projects">
            <ArrowLeft className="h-4 w-4" />
          </Link>
        </Button>
        <div className="flex-1">
          <h1 className="text-2xl font-bold">{project.name}</h1>
          <p className="text-muted-foreground">{project.description || 'No description'}</p>
        </div>
        <Button asChild>
          <Link to={`${buildProjectPath(String(project._id))}?path=README.md`}>
            <Code className="h-4 w-4 mr-2" />
            Open Editor
          </Link>
        </Button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="p-4 rounded-lg border bg-card">
          <div className="flex items-center gap-2 text-muted-foreground">
            <Users className="h-4 w-4" />
            <span className="text-sm">Team Members</span>
          </div>
          <p className="text-2xl font-bold mt-2">1</p>
        </div>
        <div className="p-4 rounded-lg border bg-card">
          <div className="flex items-center gap-2 text-muted-foreground">
            <Code className="h-4 w-4" />
            <span className="text-sm">Template</span>
          </div>
          <p className="text-lg font-semibold mt-2 capitalize">{project.template || 'Custom'}</p>
        </div>
        <div className="p-4 rounded-lg border bg-card">
          <div className="flex items-center gap-2 text-muted-foreground">
            <Clock className="h-4 w-4" />
            <span className="text-sm">Created</span>
          </div>
          <p className="text-lg font-semibold mt-2">{formatDate(project.createdAt)}</p>
        </div>
        <div className="p-4 rounded-lg border bg-card">
          <div className="flex items-center gap-2 text-muted-foreground">
            <Clock className="h-4 w-4" />
            <span className="text-sm">Last Updated</span>
          </div>
          <p className="text-lg font-semibold mt-2">{formatRelativeTime(project.updatedAt)}</p>
        </div>
      </div>

      {/* Actions */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <Link
          to={`${buildProjectPath(String(project._id))}?path=README.md`}
          className="p-6 rounded-lg border bg-card hover:bg-accent transition-colors"
        >
          <Code className="h-6 w-6 mb-2" />
          <h3 className="font-semibold">Open in Editor</h3>
          <p className="text-sm text-muted-foreground mt-1">
            Edit project code and configurations
          </p>
        </Link>
        <Link
          to={buildProjectPath(String(project._id), 'settings')}
          className="p-6 rounded-lg border bg-card hover:bg-accent transition-colors"
        >
          <Settings className="h-6 w-6 mb-2" />
          <h3 className="font-semibold">Project Settings</h3>
          <p className="text-sm text-muted-foreground mt-1">
            Configure project options and integrations
          </p>
        </Link>
      </div>
    </div>
  )
}

