          <div className="space-y-4 py-4">
            {selectedProvider === 'openai' && (
              <div className="space-y-2">
                <p className="text-sm font-medium">OpenAI method</p>
                <Select
                  value={openaiMethod}
                  onValueChange={(value) => setOpenaiMethod(value as 'oauth' | 'device' | 'api_key')}
